'use strict';
const $=id=>document.getElementById(id);
async function loadWordData(){
  const node=$('word-data');
  if(!window.DecompressionStream){throw new Error('需要支持 DecompressionStream 的现代 Chrome 或 Edge 浏览器。')}
  let compressed;
  if(node.dataset.src){
    const response=await fetch(node.dataset.src,{cache:'default'});
    if(!response.ok)throw new Error('离线词库文件未能加载：HTTP '+response.status+'。请从解压后的完整目录启动。');
    compressed=await response.arrayBuffer();
  }else{
    const chars=node.textContent.replace(/\s/g,'');
    const binary=atob(chars);
    const raw=new Uint8Array(binary.length);
    for(let i=0;i<binary.length;i++)raw[i]=binary.charCodeAt(i);
    compressed=raw;
  }
  const stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'));
  const payload=JSON.parse(await new Response(stream).text());
  if(Array.isArray(payload))return payload;
  const {f:fields,g:glosses,r:rows}=payload;
  if(!Array.isArray(fields)||!Array.isArray(rows)||!Array.isArray(glosses))throw Error('词库数据格式错误');
  return rows.map(row=>{
    const w={};for(let i=0;i<row.length;i++){if(row[i]!==null)w[fields[i]]=row[i]}
    if(w.glosses)w.glosses=w.glosses.map(x=>typeof x==='number'?glosses[x]:x);
    return w;
  });
}
async function loadEditorialData(){
 const node=$('editorial-data');
 if(!node)throw new Error('缺少校订词义数据标记');
 if(node.dataset.src){
  const response=await fetch(node.dataset.src,{cache:'default'});
  if(!response.ok)throw new Error('中文释义数据无法加载：HTTP '+response.status);
  return response.json();
 }
 return JSON.parse(node.textContent);
}
