const CHINESE_FORM_CORRECTIONS={"affairs":"n. 事务；事情；公共事务；时事（affair 的复数）","approaching":"a. 即将到来的；临近的；v. approach 的现在分词，表示接近、着手处理","automated":"a. 自动化的；v. automate 的过去式和过去分词","conditions":"n. 条件；状况；环境；条款（condition 的复数）；v. 使适应、制约（condition 的第三人称单数）","coordinated":"a. 协调一致的；v. coordinate 的过去式和过去分词","costs":"n. 成本；费用；支出（cost 的复数）；v. 花费（cost 的第三人称单数）","cringing":"v. 畏缩；退缩；因难堪而缩起身体（cringe 的现在分词）","deflated":"a. 泄了气的；灰心丧气的；v. deflate 的过去式和过去分词","details":"n. 细节；详情（detail 的复数）；v. 详细说明（detail 的第三人称单数）","disillusioned":"a. 幻想破灭的；失望的；v. disillusion 的过去式和过去分词","enlightening":"a. 富有启发性的；令人增长见识的；v. enlighten 的现在分词","inured":"a. 习惯于困难或痛苦的；已适应的；v. inure 的过去式和过去分词","mechanized":"a. 机械化的；v. mechanize 的过去式和过去分词","muted":"a. 柔和的；低沉的；减弱的；v. mute 的过去式和过去分词","overriding":"a. 首要的；压倒一切的；v. override 的现在分词，表示凌驾于或否决","relations":"n. 关系；交往；外交关系（relation 的复数）","scads":"n. 大量；许多（scad 的复数；口语，常用 scads of）","seats":"n. 座位；席位（seat 的复数）；v. 安排入座（seat 的第三人称单数）","shoes":"n. 鞋子（shoe 的复数）；v. 为……穿鞋（shoe 的第三人称单数）","stairs":"n. 楼梯（通常以复数形式使用，尤其指一段楼梯）","steps":"n. 脚步；台阶；步骤（step 的复数）；v. 迈步（step 的第三人称单数）","water-skiing":"n. 滑水运动；在机动船拖曳下穿着水橇滑行","words":"n. 单词；话语；言辞（word 的复数）；v. 措辞、用词（word 的第三人称单数）"};
