const LEARN_GRAM=[{"word":"suggest","category":"动词句型","avoid":"She suggested me to apply.","prefer":"She suggested that I apply.","why":"suggest 不直接接“某人 + to do”；可以用 suggest doing 或 suggest that + 从句。","pattern":"suggest doing / suggest that ..."},{"word":"discuss","category":"动词句型","avoid":"We discussed about the plan.","prefer":"We discussed the plan.","why":"discuss 本身直接带讨论对象；名词 discussion 才常接 about。","pattern":"discuss a problem / a discussion about ..."},{"word":"explain","category":"动词句型","avoid":"Please explain me the process.","prefer":"Please explain the process to me.","why":"explain 后先接说明内容，再用 to 引出听者。","pattern":"explain something to someone"},{"word":"enter","category":"动词句型","avoid":"We entered into the room.","prefer":"We entered the room.","why":"enter 表进入具体地点时直接接地点；enter into 多用于协议、讨论等抽象对象。","pattern":"enter a room / enter into an agreement"},{"word":"attend","category":"动词句型","avoid":"She attended to the lecture.","prefer":"She attended the lecture.","why":"attend a lecture 表出席；attend to a problem 表处理。","pattern":"attend a meeting / attend to a problem"},{"word":"reach","category":"动词句型","avoid":"We reached to the station.","prefer":"We reached the station.","why":"reach 表抵达时直接接目的地。","pattern":"reach the station / arrive at the station"},{"word":"contact","category":"动词句型","avoid":"I will contact with you tomorrow.","prefer":"I will contact you tomorrow.","why":"contact 用作动词可以直接带宾语。","pattern":"contact someone / be in contact with someone"},{"word":"emphasize","category":"动词句型","avoid":"The article emphasizes on accuracy.","prefer":"The article emphasizes accuracy.","why":"emphasize 是及物动词；名词 emphasis 才可以说 place emphasis on。","pattern":"emphasize something / place emphasis on something"},{"word":"mention","category":"动词句型","avoid":"He mentioned about a mistake.","prefer":"He mentioned a mistake.","why":"mention 直接接被提及的内容。","pattern":"mention an issue / mention that ..."},{"word":"approve","category":"动词句型","avoid":"My supervisor approved to the proposal.","prefer":"My supervisor approved the proposal.","why":"approve something = 正式批准；approve of something = 赞同其性质或行为。","pattern":"approve a proposal / approve of a decision"},{"word":"allow","category":"动词句型","avoid":"The rules don't allow to park here.","prefer":"The rules don't allow parking here.","why":"allow doing 与 allow somebody to do 是不同结构。","pattern":"allow parking / allow someone to park"},{"word":"prevent","category":"动词句型","avoid":"It prevents me to work.","prefer":"It prevents me from working.","why":"prevent somebody from doing 为固定搭配。","pattern":"prevent someone from doing"},{"word":"consider","category":"动词句型","avoid":"I consider to change the method.","prefer":"I am considering changing the method.","why":"consider 表“考虑做某事”时通常后接 -ing。","pattern":"consider doing / consider whether ..."},{"word":"avoid","category":"动词句型","avoid":"Try to avoid to repeat it.","prefer":"Try to avoid repeating it.","why":"avoid 后接名词或 -ing，不接 to do。","pattern":"avoid doing"},{"word":"manage","category":"动词句型","avoid":"I managed finishing the task.","prefer":"I managed to finish the task.","why":"manage to do 强调最终成功做到。","pattern":"manage to do"},{"word":"promise","category":"动词句型","avoid":"She promised doing it.","prefer":"She promised to do it.","why":"promise to do 表承诺自己去做。","pattern":"promise to do / promise that ..."},{"word":"encourage","category":"动词句型","avoid":"My mentor encouraged me trying.","prefer":"My mentor encouraged me to try.","why":"encourage someone to do 是常见句型。","pattern":"encourage someone to do"},{"word":"remind","category":"动词句型","avoid":"Please remind me submitting it.","prefer":"Please remind me to submit it.","why":"提醒未来要做的事：remind someone to do。","pattern":"remind someone to do / remind someone of"},{"word":"look forward","category":"动词句型","avoid":"I look forward to meet you.","prefer":"I look forward to meeting you.","why":"look forward to 中的 to 是介词，后面接 -ing 或名词。","pattern":"look forward to doing"},{"word":"be used","category":"动词句型","avoid":"I'm used to work late.","prefer":"I'm used to working late.","why":"be used to 表“习惯于”，to 是介词；used to do 表过去习惯。","pattern":"be used to doing / used to do"},{"word":"object","category":"动词句型","avoid":"They objected against the change.","prefer":"They objected to the change.","why":"object to something / doing something；to 是介词。","pattern":"object to a change"},{"word":"prefer","category":"动词句型","avoid":"I prefer tea than coffee.","prefer":"I prefer tea to coffee.","why":"比较两者时用 prefer A to B。","pattern":"prefer A to B"},{"word":"consist","category":"动词句型","avoid":"The team consists from ten members.","prefer":"The team consists of ten members.","why":"consist of 表由……组成；consist in 表本质在于。","pattern":"consist of"},{"word":"comprise","category":"动词句型","avoid":"The committee comprises of five people.","prefer":"The committee comprises five people.","why":"comprise 可直接接组成部分；be composed of 更明确。","pattern":"comprise five parts / be composed of five parts"},{"word":"depend","category":"介词搭配","avoid":"It depends of the context.","prefer":"It depends on the context.","why":"depend on 是固定搭配，表示依赖或取决于。","pattern":"depend on / depend upon"},{"word":"responsible","category":"介词搭配","avoid":"She is responsible of the report.","prefer":"She is responsible for the report.","why":"responsible for 表负责某事；responsible to 表向某人负责。","pattern":"responsible for / responsible to"},{"word":"interested","category":"介词搭配","avoid":"I'm interested about linguistics.","prefer":"I'm interested in linguistics.","why":"interested in 表对某事有兴趣。","pattern":"be interested in"},{"word":"related","category":"介词搭配","avoid":"The issue is related with timing.","prefer":"The issue is related to timing.","why":"related to 是较常用的固定结构。","pattern":"be related to"},{"word":"similar","category":"介词搭配","avoid":"This is similar with our method.","prefer":"This is similar to our method.","why":"similar to 表与……相似。","pattern":"similar to"},{"word":"arrive","category":"介词搭配","avoid":"We arrived to Amsterdam yesterday.","prefer":"We arrived in Amsterdam yesterday.","why":"城市或国家常用 arrive in；具体地点常用 arrive at。","pattern":"arrive in a city / arrive at a station"},{"word":"married","category":"介词搭配","avoid":"She's married with a doctor.","prefer":"She's married to a doctor.","why":"be married to someone 为常见表达。","pattern":"be married to"},{"word":"listen","category":"介词搭配","avoid":"Listen the recording again.","prefer":"Listen to the recording again.","why":"listen to something；hear something 则不需要 to。","pattern":"listen to / hear something"},{"word":"ask","category":"介词搭配","avoid":"He asked me a help.","prefer":"He asked me for help.","why":"ask someone for something；ask someone a question。","pattern":"ask for help"},{"word":"wait","category":"介词搭配","avoid":"I waited the bus for an hour.","prefer":"I waited for the bus for an hour.","why":"wait for something；await something 则是及物动词。","pattern":"wait for / await"},{"word":"apply","category":"介词搭配","avoid":"I applied a job yesterday.","prefer":"I applied for a job yesterday.","why":"apply for a position；apply to a university。","pattern":"apply for a job / apply to a university"},{"word":"account","category":"介词搭配","avoid":"It accounts 40% of the total.","prefer":"It accounts for 40% of the total.","why":"account for 可表示占比，也可以表示解释某现象。","pattern":"account for a proportion"},{"word":"impact","category":"介词搭配","avoid":"It has an impact to our results.","prefer":"It has an impact on our results.","why":"名词 impact on；动词 impact something。","pattern":"have an impact on"},{"word":"information","category":"名词与冠词","avoid":"I need an information.","prefer":"I need some information.","why":"information 通常不可数，数量化可说 a piece of information。","pattern":"some information / a piece of information"},{"word":"advice","category":"名词与冠词","avoid":"She gave me an advice.","prefer":"She gave me some advice.","why":"advice 通常不可数；advise 是动词。","pattern":"give advice / a piece of advice"},{"word":"research","category":"名词与冠词","avoid":"We conducted many researches.","prefer":"We conducted several studies.","why":"research 泛指研究活动时通常不可数；可说 research projects 或 studies。","pattern":"conduct research / conduct studies"},{"word":"equipment","category":"名词与冠词","avoid":"The lab bought three equipments.","prefer":"The lab bought three pieces of equipment.","why":"equipment 通常不可数。","pattern":"some equipment / pieces of equipment"},{"word":"evidence","category":"名词与冠词","avoid":"We have many evidences.","prefer":"We have several pieces of evidence.","why":"evidence 通常不可数。","pattern":"strong evidence / pieces of evidence"},{"word":"progress","category":"名词与冠词","avoid":"We made a great progress.","prefer":"We made great progress.","why":"progress 表进展时通常不可数。","pattern":"make progress"},{"word":"phenomenon","category":"名词与冠词","avoid":"These phenomenons need explaining.","prefer":"These phenomena need explaining.","why":"phenomenon 单数，phenomena 复数。","pattern":"a phenomenon / several phenomena"},{"word":"criterion","category":"名词与冠词","avoid":"One of the criterias is cost.","prefer":"One of the criteria is cost.","why":"criterion 单数，criteria 复数。","pattern":"a criterion / several criteria"},{"word":"analysis","category":"名词与冠词","avoid":"We ran two analysises.","prefer":"We ran two analyses.","why":"analysis 的复数是 analyses。","pattern":"an analysis / two analyses"},{"word":"number","category":"数量与比较","avoid":"The amount of students increased.","prefer":"The number of students increased.","why":"可数个体通常用 number of；不可数整体量用 amount of。","pattern":"number of students / amount of water"},{"word":"fewer","category":"数量与比较","avoid":"There are less errors now.","prefer":"There are fewer errors now.","why":"可数个体通常用 fewer；不可数量通常用 less。","pattern":"fewer errors / less noise"},{"word":"each","category":"数量与比较","avoid":"Each experiments were repeated.","prefer":"Each experiment was repeated.","why":"each 通常接单数名词和单数谓语。","pattern":"each experiment / all experiments"},{"word":"much","category":"数量与比较","avoid":"Much people participated.","prefer":"Many people participated.","why":"many 修饰复数可数名词；much 修饰不可数名词。","pattern":"many people / much time"},{"word":"although","category":"句子衔接","avoid":"Although it rained, but we went out.","prefer":"Although it rained, we went out.","why":"although 引导让步从句，一般不再在主句前并用 but。","pattern":"although ..., ..."},{"word":"because","category":"句子衔接","avoid":"Because of the test failed, we reran it.","prefer":"Because the test failed, we reran it.","why":"because 后接从句；because of 后接名词短语。","pattern":"because + clause / because of + noun"},{"word":"despite","category":"句子衔接","avoid":"Despite it was late, we continued.","prefer":"Although it was late, we continued.","why":"despite 后接名词或 -ing；despite the fact that 可接从句。","pattern":"despite + noun/-ing"},{"word":"however","category":"句子衔接","avoid":"The model is small, however it is accurate.","prefer":"The model is small; however, it is accurate.","why":"连接副词 however 连接独立句子时通常用分号或句号，避免逗号拼接。","pattern":"...; however, ..."},{"word":"therefore","category":"句子衔接","avoid":"The data were missing, therefore we stopped.","prefer":"The data were missing; therefore, we stopped.","why":"正式写作中避免逗号拼接两个独立句子。","pattern":"...; therefore, ..."},{"word":"actually","category":"语用与语域","avoid":"Actually, you are wrong.","prefer":"I see your point, but I read the evidence differently.","why":"直接纠正可能显得生硬；这里修改的是语气，不是语法错误。","pattern":"I see your point, but ..."},{"word":"want","category":"语用与语域","avoid":"I want you to fix it now.","prefer":"Could you take a look at this when you have time?","why":"I want you to ... 有时显得命令式，请求同事时可以软化语气。","pattern":"Could you ... when ...?"},{"word":"since","category":"时间与时态","avoid":"I live here since 2020.","prefer":"I have lived here since 2020.","why":"since 指持续状态的起点，持续到现在时常用现在完成时。","pattern":"have/has + past participle + since"},{"word":"for","category":"时间与时态","avoid":"I have lived here since five years.","prefer":"I have lived here for five years.","why":"for 表持续时长；since 表起点。","pattern":"for five years / since 2020"},{"word":"until","category":"时间与时态","avoid":"Please send it until Friday.","prefer":"Please send it by Friday.","why":"by Friday = 不迟于周五；until Friday = 状态持续到周五。","pattern":"by a deadline / until a time"},{"word":"when","category":"时间与时态","avoid":"When I will arrive, I will call you.","prefer":"When I arrive, I will call you.","why":"表示将来的时间从句通常用一般现在时，主句可以用 will。","pattern":"when + present, ... will ..."},{"word":"if","category":"时间与时态","avoid":"If I will have time, I will join.","prefer":"If I have time, I will join.","why":"真实条件句中，if 从句一般使用现在时表示将来。","pattern":"if + present, ... will ..."},{"word":"know","category":"时间与时态","avoid":"I am knowing the answer.","prefer":"I know the answer.","why":"know 表状态意义时通常不使用进行时。","pattern":"I know / I have known"},{"word":"already","category":"时间与时态","avoid":"I already finish the report.","prefer":"I have already finished the report.","why":"谈刚完成并与现在有关的事情，现在完成时常较自然；美式英语也可用过去时。","pattern":"have already + past participle"},{"word":"used","category":"时间与时态","avoid":"I am used to wake up early.","prefer":"I am used to waking up early.","why":"be used to + -ing 表适应、习惯；used to + 动词原形表过去习惯。","pattern":"be used to doing / used to do"},{"word":"software","category":"名词与冠词","avoid":"I bought a software.","prefer":"I bought a software program.","why":"software 泛指软件通常不可数，可说 a program 或 a piece of software。","pattern":"software / a software program"},{"word":"feedback","category":"名词与冠词","avoid":"She gave me many feedbacks.","prefer":"She gave me a lot of feedback.","why":"feedback 在一般商务、学术英语中通常不可数。","pattern":"give feedback / receive feedback"},{"word":"homework","category":"名词与冠词","avoid":"I have two homeworks.","prefer":"I have two homework assignments.","why":"homework 通常不可数；具体任务可数 assignment。","pattern":"do homework / two assignments"},{"word":"people","category":"名词与冠词","avoid":"Two persons are waiting outside.","prefer":"Two people are waiting outside.","why":"people 是普通对话中的常用复数；persons 多见于法律或正式告示。","pattern":"two people / one person"},{"word":"make","category":"搭配习惯","avoid":"I did a mistake.","prefer":"I made a mistake.","why":"英语习惯说 make a mistake、make a decision。","pattern":"make a mistake / make a decision"},{"word":"do","category":"搭配习惯","avoid":"I made my homework last night.","prefer":"I did my homework last night.","why":"do homework、do research；make a plan、make an effort。","pattern":"do homework / do research"},{"word":"photo","category":"搭配习惯","avoid":"Can you make a photo of us?","prefer":"Can you take a photo of us?","why":"日常英语说 take a photo / picture。","pattern":"take a photo"},{"word":"heavy","category":"搭配习惯","avoid":"There was a strong rain.","prefer":"There was heavy rain.","why":"描述雨量大，通常用 heavy rain；strong winds 则很常见。","pattern":"heavy rain / strong wind"},{"word":"experiment","category":"搭配习惯","avoid":"We made an experiment yesterday.","prefer":"We conducted an experiment yesterday.","why":"科学语境常说 conduct/run/perform an experiment。","pattern":"conduct an experiment / run a test"},{"word":"according","category":"搭配习惯","avoid":"According to me, it's unnecessary.","prefer":"In my view, it's unnecessary.","why":"according to 用于引述他人或资料；表达自己的观点用 in my view。","pattern":"according to the report / in my view"},{"word":"hand","category":"句子衔接","avoid":"On the other side, the method is costly.","prefer":"On the other hand, the method is costly.","why":"on the other hand 用于观点或利弊对照；the other side 常偏物理两侧。","pattern":"on the other hand"},{"word":"contrary","category":"句子衔接","avoid":"In contrary, the opposite is true.","prefer":"On the contrary, the opposite is true.","why":"on the contrary 往往表示反驳前述主张，不只是增加第二种情况。","pattern":"on the contrary / in contrast"},{"word":"historic","category":"词义细辨","avoid":"The lecture covered historic methods of measurement.","prefer":"The lecture covered historical methods of measurement.","why":"historical = 与历史有关；historic = 具有历史重要性的。","pattern":"historical records / historic achievement"},{"word":"economic","category":"词义细辨","avoid":"This is a more economic way to travel.","prefer":"This is a more economical way to travel.","why":"economical = 省钱、节约；economic = 与经济有关。","pattern":"economical choice / economic policy"},{"word":"effective","category":"词义细辨","avoid":"The program uses less memory, so it is more effective.","prefer":"The program uses less memory, so it is more efficient.","why":"efficient 强调资源利用；effective 强调实现预期目标。","pattern":"efficient algorithm / effective treatment"},{"word":"sensitive","category":"词义细辨","avoid":"The equipment is sensible to temperature.","prefer":"The equipment is sensitive to temperature.","why":"sensitive = 敏感、易受影响；sensible = 明智、合理。","pattern":"sensitive to / sensible decision"},{"word":"suggest","category":"动词句型","avoid":"The supervisor suggested us to redo the test.","prefer":"The supervisor suggested that we redo the test.","why":"Suggest 可以接 -ing 或 that 从句，通常不直接接 somebody to do。","pattern":"suggest (that) + clause"},{"word":"advise","category":"动词句型","avoid":"She advised to check the settings.","prefer":"She advised us to check the settings.","why":"Advise 可接 somebody to do；不带宾语时常用 advise doing。","pattern":"advise somebody to do"},{"word":"recommend","category":"动词句型","avoid":"I recommend you to read the report.","prefer":"I recommend that you read the report.","why":"Recommend 可接 that 从句、-ing，通常避免 recommend somebody to do。","pattern":"recommend doing / that ..."},{"word":"explain","category":"动词句型","avoid":"Can you explain me the procedure?","prefer":"Can you explain the procedure to me?","why":"Explain 的受众通常通过 to 引出。","pattern":"explain something to somebody"},{"word":"discuss","category":"动词句型","avoid":"We discussed about the issue.","prefer":"We discussed the issue.","why":"Discuss 是及物动词，直接接议题宾语；discussion about 才自然。","pattern":"discuss an issue"},{"word":"mention","category":"动词句型","avoid":"She mentioned about the delay.","prefer":"She mentioned the delay.","why":"Mention 后直接接所提到的事情。","pattern":"mention something"},{"word":"reply","category":"动词句型","avoid":"She replied me yesterday.","prefer":"She replied to me yesterday.","why":"Reply to someone；answer someone 可以直接接宾语。","pattern":"reply to somebody"},{"word":"contact","category":"动词句型","avoid":"Please contact to the coordinator.","prefer":"Please contact the coordinator.","why":"Contact 作动词直接接人。","pattern":"contact somebody"},{"word":"insist","category":"动词句型","avoid":"He insisted to check again.","prefer":"He insisted on checking again.","why":"Insist on doing 是常用的坚持某事结构。","pattern":"insist on doing"},{"word":"avoid","category":"动词句型","avoid":"We should avoid to repeat the error.","prefer":"We should avoid repeating the error.","why":"Avoid 后接名词或 -ing。","pattern":"avoid doing"},{"word":"allow","category":"动词句型","avoid":"The tool allows to edit the file.","prefer":"The tool allows users to edit the file.","why":"Allow somebody to do；若不说施事，可说 allow editing。","pattern":"allow somebody to do"},{"word":"prevent","category":"动词句型","avoid":"The shield prevents noise to enter.","prefer":"The shield prevents noise from entering.","why":"Prevent X from -ing 表阻止某事发生。","pattern":"prevent something from doing"},{"word":"responsible","category":"介词搭配","avoid":"She is responsible of the software.","prefer":"She is responsible for the software.","why":"Be responsible for 表对……负责。","pattern":"responsible for"},{"word":"interested","category":"介词搭配","avoid":"I'm interested on this subject.","prefer":"I'm interested in this subject.","why":"Be interested in 是固定搭配。","pattern":"interested in"},{"word":"similar","category":"介词搭配","avoid":"Their approach is similar with ours.","prefer":"Their approach is similar to ours.","why":"Similar to 是标准搭配。","pattern":"similar to"},{"word":"apply","category":"介词搭配","avoid":"I applied to a research job.","prefer":"I applied for a research job.","why":"Apply for a position；apply to a university。","pattern":"apply for a position"},{"word":"result","category":"介词搭配","avoid":"The noise resulted to data loss.","prefer":"The noise resulted in data loss.","why":"Result in 是造成结果；result from 是起因于。","pattern":"result in / result from"},{"word":"experience","category":"可数性","avoid":"She has many experiences in data analysis.","prefer":"She has a lot of experience in data analysis.","why":"表示技能或积累的经验时 experience 通常不可数；经历事件时才可数。","pattern":"have experience in"},{"word":"research","category":"可数性","avoid":"We did many researches on clocks.","prefer":"We carried out several studies on clocks.","why":"Research 通常不可数；具体研究可用 studies、projects。","pattern":"research / studies"},{"word":"furniture","category":"可数性","avoid":"We bought three furnitures.","prefer":"We bought three pieces of furniture.","why":"Furniture 是不可数名词。","pattern":"pieces of furniture"},{"word":"advice","category":"可数性","avoid":"He gave me an advice.","prefer":"He gave me a piece of advice.","why":"Advice 不可数；suggestion 可数。","pattern":"a piece of advice"},{"word":"feedback","category":"可数性","avoid":"We received three feedbacks.","prefer":"We received three pieces of feedback.","why":"Feedback 通常不可数；可数化时用 pieces of feedback。","pattern":"feedback (uncountable)"},{"word":"relevant","category":"词形与语域","avoid":"This is a relevance point.","prefer":"This is a relevant point.","why":"Relevant 是形容词修饰名词；relevance 是名词。","pattern":"relevant point"},{"word":"precise","category":"词形与语域","avoid":"The instrument measured the distance precise.","prefer":"The instrument measured the distance precisely.","why":"动词 measured 要用副词 precisely 修饰。","pattern":"measure precisely"},{"word":"significant","category":"词形与语域","avoid":"The effect is statistic significant.","prefer":"The effect is statistically significant.","why":"Statistically 修饰形容词 significant。","pattern":"statistically significant"},{"word":"analysis","category":"词形与语域","avoid":"The team made two analysis.","prefer":"The team performed two analyses.","why":"Analysis 的复数是 analyses。","pattern":"analysis → analyses"},{"word":"criteria","category":"词形与语域","avoid":"One criteria is important.","prefer":"One criterion is important.","why":"Criterion 为单数，criteria 为复数。","pattern":"criterion → criteria"},{"word":"phenomenon","category":"词形与语域","avoid":"These phenomenon are unusual.","prefer":"These phenomena are unusual.","why":"Phenomena 是 phenomenon 的复数。","pattern":"phenomenon → phenomena"},{"word":"comparison","category":"逻辑与结构","avoid":"In the other hand, the system is stable.","prefer":"On the other hand, the system is stable.","why":"On the other hand 是表示对比的连接表达。","pattern":"on the other hand"}];
const LEARN_CHUNKS=[{"word":"point","category":"表达观点","phrase":"The point is that ...","zh":"重点在于……","example":"The point is that the sample is too small.","tip":"强调论证核心，后接完整从句。","register":"中性"},{"word":"argue","category":"表达观点","phrase":"I would argue that ...","zh":"我倾向于认为……","example":"I would argue that the evidence is still inconclusive.","tip":"比 I think 更有论证色彩，但并不表示事实已获证明。","register":"正式"},{"word":"seem","category":"表达观点","phrase":"It seems to me that ...","zh":"在我看来似乎……","example":"It seems to me that we need another measurement.","tip":"表达有保留的判断；避免故作确定。","register":"中性"},{"word":"view","category":"表达观点","phrase":"From my perspective, ...","zh":"从我的角度看……","example":"From my perspective, the timeline is realistic.","tip":"强调判断视角；比 In my opinion 稍正式。","register":"中性"},{"word":"extent","category":"表达观点","phrase":"To some extent, ...","zh":"在一定程度上……","example":"To some extent, both explanations are plausible.","tip":"表示局部认同，不等于完全肯定。","register":"中性"},{"word":"matter","category":"表达观点","phrase":"What matters most is ...","zh":"最重要的是……","example":"What matters most is whether the results are reproducible.","tip":"用于强调真正重要的标准。","register":"中性"},{"word":"assume","category":"表达观点","phrase":"This assumes that ...","zh":"这预设了……","example":"This assumes that the background remains stable.","tip":"提示前提，而非直接否定结论。","register":"学术"},{"word":"imply","category":"表达观点","phrase":"This does not necessarily imply that ...","zh":"这并不必然意味着……","example":"This does not necessarily imply that the model is wrong.","tip":"把观察与结论明确区分。","register":"学术"},{"word":"suggest","category":"表达观点","phrase":"The evidence suggests that ...","zh":"证据提示……","example":"The evidence suggests that the effect is temperature-dependent.","tip":"比 proves 更审慎，适合不确定的研究结果。","register":"学术"},{"word":"prove","category":"表达观点","phrase":"This alone does not prove that ...","zh":"这一点本身不足以证明……","example":"This alone does not prove that the two variables are independent.","tip":"提醒区分相关、迹象与严格证明。","register":"学术"},{"word":"show","category":"解释数据","phrase":"The figure shows that ...","zh":"图表显示……","example":"The figure shows that the response changes with temperature.","tip":"后接图表直接呈现的现象。","register":"学术"},{"word":"increase","category":"解释数据","phrase":"increase by / increase to","zh":"增加了／增加至","example":"The value increased by 20% to 120.","tip":"by 指增量，to 指最终值；特别容易混淆。","register":"中性"},{"word":"decrease","category":"解释数据","phrase":"decrease from ... to ...","zh":"从……降至……","example":"The rate decreased from 12% to 8%.","tip":"用明确起点和终点避免歧义。","register":"中性"},{"word":"account","category":"解释数据","phrase":"account for ...% of","zh":"占……的百分之……","example":"These events account for 15% of the sample.","tip":"既可表示占比，也可表示解释原因；看宾语。","register":"学术"},{"word":"consistent","category":"解释数据","phrase":"be consistent with","zh":"与……相符","example":"The observations are consistent with the prediction.","tip":"相符不等于唯一证据或确证。","register":"学术"},{"word":"significant","category":"解释数据","phrase":"statistically significant","zh":"统计显著","example":"The difference was statistically significant.","tip":"统计显著不等于实际影响大；需要同时看效应量。","register":"学术"},{"word":"range","category":"解释数据","phrase":"range from ... to ...","zh":"范围从……到……","example":"The measurements range from 3 to 8 units.","tip":"用于区间；不要用 between ... to ...。","register":"中性"},{"word":"depend","category":"解释数据","phrase":"depend on the choice of","zh":"取决于……的选择","example":"The estimate depends on the choice of threshold.","tip":"说明分析结果对方法的敏感性。","register":"学术"},{"word":"compare","category":"解释数据","phrase":"compared with / compared to","zh":"与……相比","example":"The error is smaller compared with the baseline.","tip":"两个介词都常见，具体风格由上下文决定。","register":"中性"},{"word":"correlate","category":"解释数据","phrase":"be correlated with","zh":"与……相关","example":"The variables are positively correlated with each other.","tip":"相关不自动表明因果关系。","register":"学术"},{"word":"follow","category":"沟通协作","phrase":"follow up on","zh":"跟进……","example":"I'll follow up on the calibration results tomorrow.","tip":"follow up on 后接事项；follow up with 后接人。","register":"工作"},{"word":"update","category":"沟通协作","phrase":"keep someone updated","zh":"持续告知某人进展","example":"I'll keep you updated as the test progresses.","tip":"比 I will inform you every time 更自然。","register":"工作"},{"word":"confirm","category":"沟通协作","phrase":"Could you confirm whether ...?","zh":"能否确认是否……？","example":"Could you confirm whether the file was received?","tip":"正式、明确且礼貌。","register":"工作"},{"word":"clarify","category":"沟通协作","phrase":"Could you clarify what you mean by ...?","zh":"能否说明……的具体含义？","example":"Could you clarify what you mean by alignment?","tip":"侧重消除歧义，不应被理解为质疑对方能力。","register":"工作"},{"word":"appreciate","category":"沟通协作","phrase":"I'd appreciate it if ...","zh":"如果……我将很感谢","example":"I'd appreciate it if you could send the latest version.","tip":"if 后接完整句子，常用 could。","register":"工作"},{"word":"chance","category":"沟通协作","phrase":"when you get a chance","zh":"有空的时候","example":"Could you review this when you get a chance?","tip":"比 whenever 强调不紧急，不能用于急事。","register":"口语"},{"word":"available","category":"沟通协作","phrase":"Would you be available to ...?","zh":"你方便……吗？","example":"Would you be available to discuss this on Friday?","tip":"询问时间或意愿；具体目标要清晰。","register":"工作"},{"word":"schedule","category":"沟通协作","phrase":"works for me","zh":"对我来说合适","example":"Thursday afternoon works for me.","tip":"在约时间时简洁自然。","register":"口语"},{"word":"agree","category":"沟通协作","phrase":"I agree with the main point, but ...","zh":"大方向同意，不过……","example":"I agree with the main point, but I have a concern about the assumptions.","tip":"先说明共同点，再讨论分歧。","register":"工作"},{"word":"concern","category":"沟通协作","phrase":"One concern I have is ...","zh":"我有一个顾虑是……","example":"One concern I have is the limited sample size.","tip":"聚焦问题而不是评价个人。","register":"工作"},{"word":"understand","category":"日常交流","phrase":"I see what you mean.","zh":"我明白你的意思。","example":"I see what you mean, but I experienced something different.","tip":"表示理解，不一定表示赞同。","register":"口语"},{"word":"make","category":"日常交流","phrase":"That makes sense.","zh":"这样说得通。","example":"That makes sense given the constraints.","tip":"比 That's reasonable 更口语化。","register":"口语"},{"word":"sure","category":"日常交流","phrase":"I'm not entirely sure.","zh":"我还不太确定。","example":"I'm not entirely sure whether it will work.","tip":"比 I don't know 更强调程度不确定。","register":"口语"},{"word":"mind","category":"日常交流","phrase":"Do you mind if ...?","zh":"你介意我……吗？","example":"Do you mind if I open the window?","tip":"回答 yes 可能表示介意；表达允许常说 No, go ahead。","register":"口语"},{"word":"let","category":"日常交流","phrase":"Let me check.","zh":"我查一下。","example":"Let me check the details before I answer.","tip":"表达暂不立即作答而非不知道。","register":"口语"},{"word":"give","category":"日常交流","phrase":"give it a try","zh":"试一试","example":"Let's give it a try on a small sample.","tip":"it 指此前谈到的方法或活动。","register":"口语"},{"word":"come","category":"日常交流","phrase":"come across","zh":"偶然遇到／发现","example":"I came across an interesting paper yesterday.","tip":"与 come up with（想出）不同。","register":"口语"},{"word":"figure","category":"日常交流","phrase":"figure out","zh":"弄明白；解决","example":"I finally figured out why the plot looked wrong.","tip":"比 understand 多了经过思考或尝试的意味。","register":"口语"},{"word":"work","category":"日常交流","phrase":"work out","zh":"顺利解决；算出；锻炼","example":"The new approach worked out well.","tip":"多义语块；具体含义由上下文决定。","register":"口语"},{"word":"turn","category":"日常交流","phrase":"turn out to be","zh":"结果竟然是……","example":"The issue turned out to be a configuration error.","tip":"强调事后发现的结果。","register":"口语"},{"word":"keep","category":"日常交流","phrase":"keep in mind","zh":"记住；考虑到","example":"Keep in mind that the test data are preliminary.","tip":"常用于提醒前提或限制。","register":"中性"},{"word":"bring","category":"日常交流","phrase":"bring up","zh":"提出（话题）","example":"I'll bring it up at the meeting.","tip":"与 bring about（引起变化）不同。","register":"口语"},{"word":"come","category":"日常交流","phrase":"come up with","zh":"想出（主意）","example":"We came up with a better way to measure the delay.","tip":"宾语是 idea、solution、plan 等。","register":"口语"},{"word":"put","category":"日常交流","phrase":"put off","zh":"推迟","example":"We had to put off the meeting until Monday.","tip":"不等于 cancel（取消）。","register":"口语"},{"word":"run","category":"日常交流","phrase":"run into","zh":"偶遇；碰到问题","example":"We ran into an unexpected timing problem.","tip":"用于无意遇到，不等于 run toward。","register":"口语"},{"word":"end","category":"日常交流","phrase":"end up doing","zh":"最后竟然做了……","example":"We ended up repeating the experiment.","tip":"强调结果与原计划可能不同。","register":"口语"},{"word":"regard","category":"正式写作","phrase":"with regard to","zh":"关于；就……而言","example":"With regard to timing, the results are promising.","tip":"较正式；日常可用 about。","register":"正式"},{"word":"respect","category":"正式写作","phrase":"in this respect","zh":"在这一方面","example":"The methods differ in this respect.","tip":"this 回指明确的前述方面。","register":"正式"},{"word":"other","category":"正式写作","phrase":"on the other hand","zh":"另一方面（对比）","example":"The method is precise; on the other hand, it is expensive.","tip":"表示对立或权衡，不只是列举第二点。","register":"正式"},{"word":"addition","category":"正式写作","phrase":"in addition to","zh":"除了……之外还……","example":"In addition to the simulation, we ran a lab test.","tip":"to 是介词，后接名词或 -ing。","register":"正式"},{"word":"contrast","category":"正式写作","phrase":"in contrast to","zh":"与……形成对比","example":"In contrast to the old design, this version uses less memory.","tip":"需要清楚的比较对象。","register":"正式"},{"word":"terms","category":"正式写作","phrase":"in terms of","zh":"从……角度而言","example":"In terms of accuracy, the models are similar.","tip":"不宜在一个段落中反复滥用。","register":"正式"},{"word":"account","category":"正式写作","phrase":"take into account","zh":"考虑到","example":"The estimate takes temperature drift into account.","tip":"比 consider 更明确强调纳入因素。","register":"正式"},{"word":"light","category":"正式写作","phrase":"in light of","zh":"鉴于……","example":"In light of the new evidence, we revised the conclusion.","tip":"偏正式，常用于证据导致的判断调整。","register":"正式"},{"word":"due","category":"正式写作","phrase":"due to / because of","zh":"由于……","example":"The delay was due to a hardware issue.","tip":"两者后面一般接名词短语。","register":"中性"},{"word":"regardless","category":"正式写作","phrase":"regardless of","zh":"不论……","example":"The procedure applies regardless of the setting.","tip":"后接名词、代词或 -ing。","register":"中性"},{"word":"point","category":"沟通与澄清","phrase":"That's a fair point.","zh":"这点说得有道理。","example":"That's a fair point, but the evidence is limited.","tip":"认可论点不等于同意全部结论。","register":"通用 · 中性"},{"word":"confirm","category":"沟通与澄清","phrase":"Just to confirm, ...","zh":"我确认一下……","example":"Just to confirm, we meet at ten, right?","tip":"复述时间、结论或行动安排以减少误会。","register":"通用 · 中性"},{"word":"follow","category":"沟通与澄清","phrase":"I didn't quite follow.","zh":"我没有完全听懂。","example":"I didn't quite follow the last step of your argument.","tip":"自然表达对论述逻辑的不理解。","register":"口语 · 中性"},{"word":"add","category":"沟通与澄清","phrase":"Could I just add something?","zh":"我能补充一点吗？","example":"Could I just add something about the measurement uncertainty?","tip":"适合小组讨论中礼貌插话。","register":"会议 · 礼貌"},{"word":"mean","category":"沟通与澄清","phrase":"Do you mean that ...?","zh":"你的意思是……吗？","example":"Do you mean that the phase remains constant?","tip":"用来核实对方的意思，而非直接反驳。","register":"通用 · 中性"},{"word":"come","category":"沟通与澄清","phrase":"come back to a point","zh":"回到先前的观点","example":"Let's come back to that point after the demonstration.","tip":"与 come up with 的“想出”不同。","register":"会议 · 中性"},{"word":"bear","category":"沟通与澄清","phrase":"bear in mind","zh":"记住；考虑到","example":"Bear in mind that the data are preliminary.","tip":"比 keep in mind 稍正式。","register":"工作 · 中性"},{"word":"available","category":"邮件与安排","phrase":"Are you available for ...?","zh":"你有时间参加……吗？","example":"Are you available for a short call this afternoon?","tip":"询问对方日程时提供具体活动或时间。","register":"工作 · 中性"},{"word":"following","category":"邮件与安排","phrase":"following up on ...","zh":"跟进……","example":"I'm following up on our discussion about the schedule.","tip":"不宜用于完全没有先前背景的第一次联系。","register":"邮件 · 中性"},{"word":"attach","category":"邮件与安排","phrase":"Please find attached ...","zh":"请见附件……","example":"Please find attached the revised agenda.","tip":"正式邮件中常用；简明的 I've attached ... 也自然。","register":"邮件 · 正式"},{"word":"regard","category":"邮件与安排","phrase":"with regard to ...","zh":"关于……","example":"With regard to the test results, I have one question.","tip":"较正式；日常交流可用 about。","register":"书面 · 正式"},{"word":"get","category":"邮件与安排","phrase":"get back to someone","zh":"稍后回复某人","example":"I'll get back to you after checking the figures.","tip":"指以后再联系，不等于返回某个物理地点。","register":"工作 · 口语"},{"word":"move","category":"邮件与安排","phrase":"move the meeting forward","zh":"将会议提前","example":"Could we move the meeting forward by an hour?","tip":"Forward 对时间变化的理解可能受说话者视角影响；明确写具体新时间最稳妥。","register":"工作 · 中性"},{"word":"conduct","category":"学术搭配","phrase":"conduct an experiment","zh":"开展实验","example":"We conducted an experiment to measure the delay.","tip":"与 make an experiment 相比更地道。","register":"学术 · 正式"},{"word":"draw","category":"学术搭配","phrase":"draw a conclusion","zh":"得出结论","example":"We should not draw a conclusion from one trial.","tip":"证据不足时可加 tentative 或 preliminary 限定。","register":"学术 · 正式"},{"word":"pose","category":"学术搭配","phrase":"pose a question","zh":"提出问题","example":"This observation poses an important question.","tip":"不是 ask a question 的每一语境都可直接替换。","register":"学术 · 正式"},{"word":"raise","category":"学术搭配","phrase":"raise a concern","zh":"提出担忧","example":"The reviewer raised a concern about sample selection.","tip":"与 express a concern 意思接近，raise 强调将问题提出来。","register":"工作 · 正式"},{"word":"address","category":"学术搭配","phrase":"address an issue","zh":"处理；讨论一个问题","example":"The report addresses several sources of uncertainty.","tip":"Address 可表示处理或讨论，不保证问题已完全解决。","register":"学术 · 正式"},{"word":"provide","category":"学术搭配","phrase":"provide evidence for ...","zh":"为……提供证据","example":"The measurements provide evidence for a temperature effect.","tip":"提供支持不等于证明唯一解释。","register":"学术 · 正式"},{"word":"rely","category":"学术搭配","phrase":"rely on an assumption","zh":"依赖一个假设","example":"The model relies on an assumption about independence.","tip":"在严谨论证中应明确假设内容。","register":"学术 · 正式"},{"word":"consistent","category":"审慎论证","phrase":"be consistent with ...","zh":"与……相符","example":"The data are consistent with the simulation.","tip":"不意味着已经证实某个机制是唯一原因。","register":"学术 · 审慎"},{"word":"suggest","category":"审慎论证","phrase":"the results suggest that ...","zh":"结果表明／提示……","example":"The results suggest that further tests are needed.","tip":"比 prove 更适合初步或受限证据。","register":"学术 · 审慎"},{"word":"within","category":"审慎论证","phrase":"within the scope of ...","zh":"在……范围内","example":"The conclusion holds within the scope of this model.","tip":"用于标明适用范围，避免无条件推广。","register":"学术 · 正式"},{"word":"subject","category":"审慎论证","phrase":"be subject to ...","zh":"受到……影响；受……约束","example":"The estimate is subject to measurement uncertainty.","tip":"意义根据后接名词而变化。","register":"学术 · 正式"},{"word":"account","category":"审慎论证","phrase":"account for a difference","zh":"解释一种差异","example":"Temperature drift may account for the difference.","tip":"Account for 不一定表示已完全证明原因。","register":"学术 · 中性"},{"word":"rule","category":"审慎论证","phrase":"rule out an alternative","zh":"排除另一种可能","example":"We cannot rule out an alternative explanation.","tip":"无法排除与已证实相反；科学写作常用否定形式。","register":"学术 · 审慎"},{"word":"bear","category":"阅读逻辑","phrase":"bear on ...","zh":"与……有关系","example":"This question bears directly on the interpretation.","tip":"比 relate to 较正式。","register":"学术 · 正式"},{"word":"in","category":"阅读逻辑","phrase":"in light of ...","zh":"鉴于……","example":"In light of the new data, we revised the plan.","tip":"强调新信息影响判断。","register":"书面 · 正式"},{"word":"by","category":"阅读逻辑","phrase":"by contrast","zh":"相比之下","example":"The first run was stable; by contrast, the second drifted.","tip":"用于清晰的对照。","register":"学术 · 中性"},{"word":"at","category":"阅读逻辑","phrase":"at least","zh":"至少","example":"At least three measurements are needed.","tip":"不要误读成 at most（至多）。","register":"通用 · 中性"},{"word":"on","category":"阅读逻辑","phrase":"on the whole","zh":"总的来说","example":"On the whole, the new design performs better.","tip":"允许存在例外情况。","register":"通用 · 中性"},{"word":"as","category":"阅读逻辑","phrase":"as a result","zh":"结果；因此","example":"The probe was disconnected; as a result, the trace was flat.","tip":"表示事件结果，不等于 on the contrary。","register":"通用 · 中性"},{"word":"carry","category":"短语动词","phrase":"carry out a procedure","zh":"执行程序","example":"The team carried out the safety checks first.","tip":"Carry out 偏行动执行，适用于测试、计划等。","register":"工作 · 中性"},{"word":"look","category":"短语动词","phrase":"look into an issue","zh":"调查问题","example":"We'll look into the discrepancy tomorrow.","tip":"与 look up（查询词条）不同。","register":"工作 · 口语"},{"word":"call","category":"短语动词","phrase":"call off a meeting","zh":"取消会议","example":"The organizer called off the meeting.","tip":"与 put off（推迟）不同。","register":"通用 · 中性"},{"word":"put","category":"短语动词","phrase":"put something off","zh":"推迟某事","example":"We put the test off until Monday.","tip":"代词宾语时一般说 put it off。","register":"口语 · 中性"},{"word":"come","category":"短语动词","phrase":"come up with an idea","zh":"想出主意","example":"She came up with a simple solution.","tip":"与 come across（偶然遇见）不同。","register":"口语 · 中性"},{"word":"work","category":"短语动词","phrase":"work out a solution","zh":"找到解决方案","example":"We worked out a solution together.","tip":"与 work out（锻炼）是不同义项。","register":"通用 · 中性"},{"word":"phase","category":"学术搭配","phrase":"phase shift","zh":"相位偏移","example":"We measured a small phase shift after the reset.","tip":"名词短语常作为专业搭配使用。","register":"技术 · 中性"},{"word":"error","category":"学术搭配","phrase":"systematic error","zh":"系统误差","example":"A systematic error can bias every measurement.","tip":"不同于 random error（随机误差）。","register":"学术 · 中性"},{"word":"estimate","category":"学术搭配","phrase":"make an estimate","zh":"作出估计","example":"We made an estimate of the expected uncertainty.","tip":"与精确测量值区别，通常应说明假设。","register":"学术 · 中性"},{"word":"finding","category":"学术搭配","phrase":"report the findings","zh":"报告研究发现","example":"The paper reports the findings of a pilot study.","tip":"Findings 不等于报告中所有原始数据。","register":"学术 · 正式"}];
const LEARN_TONE=[{"category":"请求协助","goal":"请求同事看材料","direct":"Read this now.","natural":"Could you take a look at this when you have a moment?","why":"原句可能像命令。加入明确的动作和时间弹性，更适合非紧急工作请求。","tone":"工作 · 委婉"},{"category":"请求进度","goal":"询问进度","direct":"Why haven't you finished it?","natural":"Could you let me know how it's progressing?","why":"关注任务状态，比直接质问完成情况更建设性。","tone":"工作 · 中性"},{"category":"不同意见","goal":"提出分歧","direct":"You are wrong about this.","natural":"I see your point, but I interpret the result differently.","why":"先承认对方观点可以理解，再说清楚具体分歧。","tone":"协作 · 委婉"},{"category":"有保留的结论","goal":"汇报初步发现","direct":"This proves that the method works.","natural":"These preliminary results suggest that the method may work.","why":"低证据强度对应 suggest / may；避免过度断言。","tone":"学术 · 谨慎"},{"category":"建议修改","goal":"给出具体建议","direct":"You should change this section.","natural":"It might help to clarify the assumptions in this section.","why":"将评价转化为可执行的修改建议。","tone":"写作 · 建议"},{"category":"纠正误解","goal":"温和澄清","direct":"That's not what I said.","natural":"I may not have explained it clearly. What I meant was ...","why":"用对事不对人的方式纠正误解；不必一味自责。","tone":"合作 · 中性"},{"category":"拒绝邀请","goal":"礼貌拒绝","direct":"I don't want to go.","natural":"Thanks for inviting me, but I won't be able to make it.","why":"先表达感谢，再简洁拒绝；无需编造复杂借口。","tone":"社交 · 友好"},{"category":"表达不确定","goal":"明确不确定程度","direct":"Maybe yes, maybe no.","natural":"I'm not sure yet; I need to check the data first.","why":"给出不确定来源和下一步，有助于沟通。","tone":"通用 · 中性"},{"category":"请求澄清","goal":"要求进一步解释","direct":"I don't understand you.","natural":"Could you clarify what you mean by “stable”?","why":"指向具体模糊部分，降低对人的评价。","tone":"学术 · 中性"},{"category":"发邮件提醒","goal":"温和提醒","direct":"You didn't answer my email.","natural":"Just following up on my previous message about the schedule.","why":"适用于普通跟进；紧急事项应明确时限。","tone":"工作 · 委婉"},{"category":"分享坏消息","goal":"客观说明限制","direct":"Your plan failed.","natural":"The current approach hasn't produced the expected result yet.","why":"聚焦结果与时间范围，不把方法受挫变成人身判断。","tone":"工作 · 客观"},{"category":"请求延长时间","goal":"提出合理请求","direct":"I need more time.","natural":"Would it be possible to extend the deadline until Friday?","why":"明确请求期限，便于对方回应。","tone":"工作 · 礼貌"},{"category":"接受建议","goal":"积极回应","direct":"OK.","natural":"That's helpful; I'll incorporate that change.","why":"表示理解建议并说明后续动作，比只回复 OK 更充分。","tone":"工作 · 积极"},{"category":"保留意见","goal":"不立即承诺","direct":"Yes, I'll do it.","natural":"Let me check the timeline before I commit to that.","why":"没有把握时不应因为礼貌而作虚假承诺。","tone":"协作 · 谨慎"},{"category":"提出请求","goal":"询问是否方便","direct":"Can you do it?","natural":"Would you have time to review it this week?","why":"具体时间和任务使请求更易答复。","tone":"工作 · 委婉"},{"category":"表达感谢","goal":"具体感谢","direct":"Thanks.","natural":"Thanks for taking the time to explain the setup.","why":"具体说明对方帮助了什么，常更自然。","tone":"工作 · 友好"},{"category":"认错修正","goal":"承担责任","direct":"There was an error.","natural":"I made an error in the calculation; I've corrected it in the updated version.","why":"适当明确责任和改正措施，不要只使用被动表达。","tone":"学术 · 负责"},{"category":"强调风险","goal":"不过度夸大","direct":"This is a disaster.","natural":"This could introduce a systematic bias into the results.","why":"说明具体后果比情绪性评语更准确。","tone":"学术 · 精确"},{"category":"比较结论","goal":"区分不同维度","direct":"This is better.","natural":"This method is more accurate but requires more computation.","why":"“更好”应明确评价指标与代价。","tone":"学术 · 平衡"},{"category":"正式请求","goal":"书面邮件开头","direct":"I am writing to ask a question.","natural":"I'm writing to ask whether the updated file is available.","why":"直指目的，避免开头过长。","tone":"邮件 · 中性"},{"category":"电话或会议","goal":"没听清时","direct":"What?","natural":"Sorry, could you repeat the last part?","why":"简单礼貌地指出需要重复的部分。","tone":"口语 · 友好"},{"category":"提出不同方案","goal":"建议替代","direct":"Your idea won't work.","natural":"Could we consider an alternative approach?","why":"保留讨论空间，适用于技术方案未定时。","tone":"工作 · 合作"},{"category":"承认局限","goal":"承认范围限制","direct":"We have solved the problem.","natural":"We've resolved the issue in the lab, but field validation is still pending.","why":"区分实验室验证和正式环境验证。","tone":"学术 · 精确"},{"category":"确认理解","goal":"复述并核对","direct":"I understand.","natural":"Just to make sure I understood, do you mean the clock phase stays fixed?","why":"复杂信息下可复述关键点，减少沟通误差。","tone":"工作 · 精确"}];
const learnAnchors=new Map();
for(const [kind,items] of [['patterns',LEARN_GRAM],['chunks',LEARN_CHUNKS]])for(const item of items){const key=item.word.toLowerCase();if(!learnAnchors.has(key))learnAnchors.set(key,{patterns:[],chunks:[]});learnAnchors.get(key)[kind].push(item)}
let learnTab='patterns',learnCategory='all',learnPage=1,learnPageSize=12,learnPracticeType='mixed';
let learnDrillIndex=0,learnDrills=[],learnReveal=false,learnTyped='',learnAnswered=false;
let learnProgress={};try{learnProgress=JSON.parse(localStorage.getItem('lexicon-learner-progress-v19')||'{}')||{}}catch(e){learnProgress={}}
const learnEsc=(s)=>escapeHTML(String(s||''));
function learnerEntryPanel(w){const m=learnAnchors.get(w.word.toLowerCase())||{patterns:[],chunks:[]};const practice=precisionWordMap.get(w.word.toLowerCase());if(!m.patterns.length&&!m.chunks.length&&!practice)return '';
 const g=m.patterns[0],c=m.chunks[0];const lines=[];if(practice)lines.push(`<div class="precision-learner-link"><button type="button" data-prec-word="${learnEsc(w.word)}">练习该词的语境用法 · ${practice.length} 题 →</button></div>`);
 if(g)lines.push(`<p><b>${learnEsc(g.category)}</b> · ${learnEsc(g.pattern)}<br><span>${learnEsc(g.why)}</span></p>`);
 if(c)lines.push(`<p><b>自然语块</b> · <i>${learnEsc(c.phrase)}</i> — ${learnEsc(c.zh)}</p>`);
 return `<div class="learner-focus"><h4>LEARN TO USE · 活用提示</h4>${lines.join('')}<button type="button" data-learn-anchor="${learnEsc(w.word)}">打开该词的句型与语块 →</button></div>`;
}
function learnerRecords(){return learnTab==='patterns'?LEARN_GRAM:learnTab==='chunks'?LEARN_CHUNKS:LEARN_TONE}
function renderLearnerCategory(){const arr=learnerRecords();const cats=[...new Set(arr.map(x=>x.category))];const sel=$('learner-category');const old=learnCategory;
sel.innerHTML='<option value="all">全部类型</option>'+cats.map(x=>`<option value="${learnEsc(x)}">${learnEsc(x)}</option>`).join('');learnCategory=cats.includes(old)?old:'all';sel.value=learnCategory;
}
function learnerCard(item){if(learnTab==='patterns'){
 return `<article class="learner-card"><span class="learner-card-kicker">${learnEsc(item.category)}</span><h3>${learnEsc(item.word)}</h3><div class="learner-compare"><div><small>不推荐直接照搬 · NEEDS WORK</small><p>${learnEsc(item.avoid)}</p></div><div class="learner-good"><small>更稳妥的表达 · BETTER CHOICE</small><p>${learnEsc(item.prefer)}</p></div></div><p>${learnEsc(item.why)}</p><div class="learner-small">常见结构 · ${learnEsc(item.pattern)}</div>${lookup.has(item.word)?`<button class="learner-mini-link" type="button" data-lword="${learnEsc(item.word)}">查看 ${learnEsc(item.word)} 的完整词条 ↗</button>`:''}</article>`;
}
if(learnTab==='chunks')return `<article class="learner-card"><span class="learner-card-kicker">${learnEsc(item.category)} · ${learnEsc(item.register)}</span><div class="learner-phrase">${learnEsc(item.phrase)}</div><h3 class="learner-card-translation">${learnEsc(item.zh)}</h3><div class="learner-example">${learnEsc(item.example)}</div><p>${learnEsc(item.tip)}</p>${lookup.has(item.word)?`<button class="learner-mini-link" type="button" data-lword="${learnEsc(item.word)}">查看词条 ${learnEsc(item.word)} ↗</button>`:''}</article>`;
return `<article class="learner-card"><span class="learner-card-kicker">${learnEsc(item.category)} · ${learnEsc(item.tone)}</span><h3>${learnEsc(item.goal)}</h3><div class="learner-compare"><div><small>较直接 · DIRECT</small><p>${learnEsc(item.direct)}</p></div><div class="learner-good"><small>更符合当前情境 · NATURAL</small><p>${learnEsc(item.natural)}</p></div></div><p>${learnEsc(item.why)}</p></article>`;
}
function renderLearnerList(reset=false){if(reset)learnPage=1;if(learnTab==='practice')return;
const q=$('learner-search').value.trim().toLowerCase();const cat=learnCategory;
const arr=learnerRecords().filter(x=>(cat==='all'||x.category===cat)&&(!q||Object.values(x).some(v=>String(v).toLowerCase().includes(q))));
const total=Math.max(1,Math.ceil(arr.length/learnPageSize));learnPage=Math.min(Math.max(learnPage,1),total);
const items=arr.slice((learnPage-1)*learnPageSize,learnPage*learnPageSize);
$('learner-items').innerHTML=items.length?items.map(learnerCard).join(''):'<p class="learner-empty">没有匹配的学习内容，请尝试其他关键词或类型。</p>';
$('learner-results').textContent=`${arr.length} 项 · 第 ${learnPage}/${total} 页`;
$('learner-pages').innerHTML=total>1?`<button data-learn-page="prev" ${learnPage===1?'disabled':''}>上一页</button><span>第 ${learnPage} / ${total} 页</span><button data-learn-page="next" ${learnPage===total?'disabled':''}>下一页</button>`:'';
}
function setLearnTab(tab){learnTab=tab;learnCategory='all';learnPage=1;
 document.querySelectorAll('[data-ltab]').forEach(b=>{const on=b.dataset.ltab===tab;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on))});
 $('learner-list-pane').classList.toggle('hidden',tab==='practice'||tab==='precision');$('learner-practice-pane').classList.toggle('hidden',tab!=='practice');$('precision-page').classList.toggle('hidden',tab!=='precision');
 if(tab==='precision'){precisionShowStats();precisionRenderGuide()}else if(tab==='practice'){if(!learnDrills.length)buildLearnDrills();renderLearnerDrill()}else{renderLearnerCategory();renderLearnerList(true)}
}
function openLearnerAnchor(word){navigate('learner');$('learner-search').value=word;
 const m=learnAnchors.get(word.toLowerCase());setLearnTab(m?.patterns?.length?'patterns':'chunks');
 $('learner-search').value=word;renderLearnerList(true);
 $('learner-page').scrollIntoView({block:'start',behavior:'smooth'});
}
function normalizeLearnerAnswer(text){return String(text||'').toLowerCase().replace(/[‘’]/g,"'").replace(/[“”]/g,'"').replace(/[–—]/g,'-').replace(/[^a-z0-9'\s-]/g,'').replace(/\s+/g,' ').trim()}
function allLearnDrills(){const e=LEARN_GRAM.filter(x=>x.category!=='语用与语域').map((x,i)=>({id:'g'+i,type:'edit',word:x.word,title:'改写句子，使它更自然、符合常用语法。',prompt:x.avoid,answer:x.prefer,explain:x.why}));
 const p=LEARN_CHUNKS.map((x,i)=>({id:'c'+i,type:'phrase',word:x.word,title:'看到中文提示，尝试自己写出英语语块。',prompt:x.zh,answer:x.phrase,explain:x.tip,example:x.example}));return e.concat(p)}
const learnAllDrills=allLearnDrills();
function buildLearnDrills(){const now=Date.now();const mode=$('learner-drill-type').value;learnPracticeType=mode;
 let pool=learnAllDrills.filter(q=>mode==='mixed'||q.type===mode);
 // Prioritize due and missed items; shuffle equal-priority items to avoid a rigid first-page loop.
 pool=pool.map(q=>({q,weight:!learnProgress[q.id]?2:(learnProgress[q.id].due||0)<=now?3:0,random:Math.random()})).sort((a,b)=>b.weight-a.weight||a.random-b.random).map(x=>x.q);
 learnDrills=pool.slice(0,Math.min(20,pool.length));learnDrillIndex=0;learnReveal=false;learnTyped='';learnAnswered=false;
 renderLearnerDrill();}
function renderLearnerDrill(){const q=learnDrills[learnDrillIndex];if(!q){$('learner-drill').innerHTML='<div class="learner-practice-main"><h3>已完成本轮练习</h3><p>你可以重新练习，或切换题型巩固薄弱环节。</p><button class="learner-primary" data-lrestart="1">开始下一轮</button></div>';return}
 const p=learnProgress[q.id]||{};
 $('learner-quiz-stats').textContent=`共 ${learnAllDrills.length} 道 · 已练 ${Object.keys(learnProgress).length} 道`;
 $('learner-drill').innerHTML=`<div class="learner-practice-main"><div class="learner-tasktype">${q.type==='edit'?'SENTENCE REPAIR · 改错':'ACTIVE RECALL · 语块回忆'} · ${learnDrillIndex+1}/${learnDrills.length}</div><div class="learner-prompt">${learnEsc(q.title)}</div><div class="learner-example learner-prompt-example">${learnEsc(q.prompt)}</div><div class="learner-small learner-drill-instruction">${q.type==='edit'?'输入一个自然、准确的完整句子。':'只写最贴切的英语语块，不必写完整句子。'}${p.attempts?' · 此题已经练习 '+p.attempts+' 次':''}</div><textarea id="learner-answer" spellcheck="false" aria-label="输入你的英语答案" placeholder="在这里输入…" ${learnReveal?'disabled':''}>${learnEsc(learnTyped)}</textarea><div class="learner-practice-actions">${learnReveal?'<button class="learner-secondary" data-lnext="1">暂不掌握 · 下一题 →</button>':`<button class="learner-primary" data-lcheck="1">核对参考答案</button><button class="learner-secondary" data-lreveal="1">查看参考答案</button>`}</div>${learnReveal?`<div class="learner-feedback"><b>${learnTyped&&normalizeLearnerAnswer(learnTyped)===normalizeLearnerAnswer(q.answer)?'与示例答案一致':'参考答案（并非唯一解）'}</b><div class="learner-phrase learner-answer-large">${learnEsc(q.answer)}</div><p>${learnEsc(q.explain)}</p>${q.example?`<p class="learner-example">${learnEsc(q.example)}</p>`:''}<div class="learner-grade-note">根据自己能否主动写出正确表达，选择复习间隔。</div><div class="learner-grades"><button data-lgrade="0">还不会 · 明天复习</button><button data-lgrade="1">有点犹豫 · 3 天后</button><button data-lgrade="2">能独立使用 · 7 天后</button></div></div>`:''}</div>`;
}
function gradeLearner(level){const q=learnDrills[learnDrillIndex];if(!q)return;const days=[1,3,7][level]||1;const p=learnProgress[q.id]||{attempts:0};
 learnProgress[q.id]={attempts:p.attempts+1,last:Date.now(),due:Date.now()+days*86400000,grade:level};
 try{localStorage.setItem('lexicon-learner-progress-v19',JSON.stringify(learnProgress))}catch(e){}
 learnDrillIndex++;learnReveal=false;learnTyped='';renderLearnerDrill();}
function installLearner(){
 $('learner-grammar-count').textContent=LEARN_GRAM.length;$('learner-chunk-count').textContent=LEARN_CHUNKS.length;$('learner-drill-count').textContent=learnAllDrills.length;
 document.querySelectorAll('[data-ltab]').forEach(b=>b.addEventListener('click',()=>setLearnTab(b.dataset.ltab)));
 $('learner-search').addEventListener('input',()=>renderLearnerList(true));$('learner-category').addEventListener('change',e=>{learnCategory=e.target.value;renderLearnerList(true)});
 $('learner-drill-type').addEventListener('change',buildLearnDrills);$('learner-restart').addEventListener('click',buildLearnDrills);
 $('learner-page').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.learnPage){learnPage+=b.dataset.learnPage==='next'?1:-1;renderLearnerList();$('learner-list-pane').scrollIntoView({block:'start',behavior:'smooth'})}
 if(b.dataset.lword)openLinkedWord(b.dataset.lword);
 if(b.dataset.lcheck!==undefined||b.dataset.lreveal!==undefined){const ta=$('learner-answer');learnTyped=ta?.value?.trim()||'';learnReveal=true;renderLearnerDrill()}
 if(b.dataset.lnext!==undefined){const q=learnDrills[learnDrillIndex];if(q){const p=learnProgress[q.id]||{attempts:0};learnProgress[q.id]={attempts:p.attempts+1,last:Date.now(),due:Date.now()+86400000,grade:0};try{localStorage.setItem('lexicon-learner-progress-v19',JSON.stringify(learnProgress))}catch(e){}}learnDrillIndex++;learnTyped='';learnReveal=false;renderLearnerDrill()}
 if(b.dataset.lgrade!==undefined)gradeLearner(Number(b.dataset.lgrade));
 if(b.dataset.lrestart!==undefined)buildLearnDrills();
 });
 document.addEventListener('click',e=>{const b=e.target.closest('[data-learn-anchor]');if(!b)return;e.stopPropagation();openLearnerAnchor(b.dataset.learnAnchor)},true);
 setLearnTab('patterns');
}

/* v20 · Practical English progression, all material embedded offline. */
const PRECISION_LESSONS=[{"topic":"动词句型","en":"Verb patterns","summary":"英语动词不仅决定意义，也决定后面需要什么结构。中文的“建议某人做”不能逐词对应到 suggest somebody to do。","rules":["suggest / avoid / consider 后常接 -ing；suggest 也可接 that 从句。","encourage / remind + 人 + to do；explain + 内容 + to + 人。","manage to do 表成功做到；try doing 与 try to do 含义不同。"],"examples":["I suggest testing the other configuration.","The supervisor encouraged us to repeat the test."],"pitfall":"将所有“动词 + 做事”统一翻译成 to do。","goal":"看到动词时先识别它允许的补语结构。"},{"topic":"介词选择","en":"Preposition choices","summary":"介词不是中文介词的一一翻译。它们体现地点尺度、参与关系和固定搭配；同一个中文“在”可能对应 at、in 或 on。","rules":["arrive in a city/country，但 arrive at a station/door。","depend on、interested in、responsible for 属于需要整体记忆的结构。","result in 强调造成结果；result from 强调起因。"],"examples":["The estimate depends on the threshold.","The error resulted from a calibration issue."],"pitfall":"把每一个中文“对／于／从”逐词转为英文介词。","goal":"优先学习介词和前后词形成的完整语块。"},{"topic":"冠词与数量","en":"Countability & articles","summary":"不少学术名词在英语里不可数。判断单复数、冠词和量词时，必须先明确说的是概念整体还是具体个体。","rules":["information / advice / evidence / equipment 通常不可数。","a piece of information 可数化，而不是 an information。","criterion→criteria、phenomenon→phenomena、analysis→analyses。"],"examples":["We found strong evidence for the effect.","Each participant received a unique identifier."],"pitfall":"把中文里的“一条建议／一条信息”直接写成 an advice / an information。","goal":"先决定名词可数性，再选择冠词、量词和动词一致形式。"},{"topic":"时间与时态","en":"Time & aspect","summary":"英语时态往往要同时表达时间位置与事件状态。since 指起点，for 指时长；by 和 until 的区别是完成期限与持续终点。","rules":["I have lived here since 2021 / for five years（强调持续至今）。","Please send it by Friday = 周五以前完成；I will stay until Friday = 持续到周五。","When/if 引导将来时间或真实条件，从句通常使用现在时。"],"examples":["When the results arrive, I will contact you.","The test has not finished yet."],"pitfall":"以为句子提到将来就必须在每个从句里使用 will。","goal":"分清起点、时长、完成期限与事件持续。"},{"topic":"语气与情态","en":"Modality & stance","summary":"表达礼貌与确定性是语言能力的重要部分。could、might、should、must 不只是动词替换，还影响判断强度和人际距离。","rules":["might/could 表可能；must 在不同语境可表示义务或很强的推断。","Could you...? 常用于礼貌请求，May I...? 常用于请求许可。","The results suggest... 往往比 The results prove... 更符合初步证据。"],"examples":["Could you clarify one detail?","The variation might be due to temperature drift."],"pitfall":"以为越正式就越应该使用 must、prove 或绝对副词。","goal":"让语气强度与证据程度和人际情境相匹配。"},{"topic":"学术证据","en":"Evidence & claims","summary":"科研英语要分清观察、统计关联、机制解释和因果推断。选词精确比追求复杂的“大词”更重要。","rules":["suggest / indicate 用于迹象；demonstrate/establish 常要求更充分的证据。","consistent with 表相符，不代表确认唯一解释。","statistical significance 与 practical importance 是两个问题。"],"examples":["The findings are consistent with the model.","Correlation alone does not establish causation."],"pitfall":"把任何有统计显著性的观察都写成 proves the hypothesis。","goal":"选择与证据强度一致的动词，并交代不确定性。"},{"topic":"因果与比较","en":"Cause & comparison","summary":"英语因果表达需要明确方向。result in 和 result from 正好相反；比较也应区分程度、对象及证据边界。","rules":["X results in Y（X 导致 Y）；Y results from X（Y 起因于 X）。","affect 通常是动词；effect 多用作名词，仍有较少见的动词用法。","although + 从句，despite + 名词或 -ing。"],"examples":["Poor calibration resulted in bias.","Despite the delay, the test was completed."],"pitfall":"用一个中文“由于”覆盖英语中原因、后果和转折的所有关系。","goal":"先画清逻辑箭头，再选择英文连接词。"},{"topic":"搭配与用词","en":"Natural collocations","summary":"自然英语往往按词组而非单词组织。make a decision、conduct research、pay attention 都是高价值的学习单位。","rules":["make a decision / make progress，而不是逐字套用中文动词。","conduct/perform/run an experiment；do research 同样常用。","reduce risk、draw a conclusion、take responsibility。"],"examples":["We conducted a controlled experiment.","Please pay attention to the units."],"pitfall":"把语法上可能成立的动词与名词任意组合，忽略约定搭配。","goal":"记住词与词的共现方式，而不是孤立记忆词义。"},{"topic":"短语动词","en":"Phrasal verbs","summary":"短语动词把简单动词和小品词组合成新意义，在口语和工作交流中极常见。许多不能用各部分字面意思相加理解。","rules":["come up with = 想出；come across = 偶然遇到。","look into = 调查；look after = 照顾。","put off = 推迟；run into = 遇到问题；carry out = 执行。"],"examples":["We ran into a software problem.","I will bring it up at the meeting."],"pitfall":"看到 run 就以为是“跑”，看到 bring 就以为是“带来”。","goal":"连同宾语和语境一起记忆短语动词。"},{"topic":"逻辑与衔接","en":"Logical flow","summary":"连接词描述逻辑，不是装饰文章的高级词。however 表转折，moreover 表补充，therefore 表推论；错误替换会改变论证。","rules":["however / therefore 是连接副词，连接两个独立句时常用分号或句号。","although + 从句；despite + 名词短语。","on the other hand 表权衡对照，不等同 moreover 的信息增加。"],"examples":["The method is precise; however, it is costly.","The method is accurate; moreover, it is fast."],"pitfall":"为了显得学术而任意交替使用 moreover、nevertheless、therefore。","goal":"确保每一个衔接词都准确反映前后命题的关系。"},{"topic":"邮件与礼貌","en":"Professional English","summary":"得体的工作英语强调具体、合作和合适的礼貌程度。直截了当未必错误，但请求协助、提出异议和跟进时要考虑关系。","rules":["Could you confirm whether...? 比 Confirm it. 更适合普通询问。","I'd appreciate it if you could...；I look forward to hearing...。","I have one concern about... 聚焦问题，不直接批评人。"],"examples":["Could you clarify which version you used?","I'll keep you updated as the work progresses."],"pitfall":"把中文礼貌套成冗长、含糊或过度道歉的英文。","goal":"简洁说明请求、背景和时间，并保持友好。"},{"topic":"词义辨析","en":"Precision in meaning","summary":"词形相似或中文释义相同，不代表两个词可以互换。要比较语义范围、常用宾语、说话者态度和语域。","rules":["accurate = 接近真实值；precise = 多次结果的一致程度。","efficient = 资源使用得当；effective = 能达到目标。","imply 是说话者暗示，infer 是听者推断。"],"examples":["The measurement is accurate but not precise.","The text implies a problem; readers infer a cause."],"pitfall":"只看一个汉语译词就决定英文同义词的替换。","goal":"用最小对比例句建立清晰的词义边界。"},{"topic":"日常互动","en":"Conversation moves","summary":"自然交流不只是语法正确，还要会接话、确认理解、委婉插话，以及对不确定的信息作适当回应。","rules":["使用 Do you mean ...? 核实对方意思，不假设自己已经听懂。","Could I just add something? 比 Wait, listen to me 更适合多数合作场景。","I'm afraid I can't ... 常用于礼貌拒绝；并非表达恐惧。","That's a good point, but ... 可以先肯定论点再提出不同看法。"],"examples":["Just to make sure I understood, do you mean the deadline is flexible?","Could I come back to that point after the presentation?"],"pitfall":"把中文直译成硬性的命令，或只用 yes/no 导致缺少必要的回应。","goal":"根据对话目的选择能推进交流的表达。"},{"topic":"职场邮件","en":"Workplace messages","summary":"工作邮件讲究明确目的、合理语气和可执行的下一步。礼貌不等于含糊，简洁也不等于生硬。","rules":["I'm writing to ... 直接说明目的，少用冗长的套话。","follow up on + 名词 用于跟进先前事项；get back to you 表示稍后回复。","Could you let me know by Friday? 清楚地提出回复期限。","attach a file / find the file attached 可以表达附件，避免请对方猜测。"],"examples":["I'm following up on our discussion about the revised schedule.","Please let me know if any additional information would be helpful."],"pitfall":"在同一封邮件里反复道歉，却没有交代所需行动和时间。","goal":"写出目的清楚、语气合适、行动明确的邮件。"},{"topic":"学术搭配","en":"Academic collocations","summary":"学术英语大量依靠稳定的动词和名词组合。认识 evidence、question、hypothesis 还不够，还需知道它们通常与哪些动词搭配。","rules":["conduct an experiment / carry out a study；不是 make an experiment。","draw a conclusion / reach a conclusion；不是 do a conclusion。","pose a question / raise a concern / address an issue 各有侧重。","provide evidence for / support a claim；不能仅凭词典同义词替换。"],"examples":["The study provides evidence for a systematic effect.","We conducted several tests before drawing a conclusion."],"pitfall":"直接把中文“做研究”“得出结论”逐词翻成 make research / make a conclusion。","goal":"将常见学术概念记忆为完整的搭配单元。"},{"topic":"论证与局限","en":"Claims and limitations","summary":"科学和论说写作需要区分观察、解释、证据强度和适用范围。语言的确定性应与实际证据一致。","rules":["suggest、indicate 一般比 prove 语气审慎；具体选择仍取决于证据。","be consistent with 并不等于 be uniquely explained by。","a limitation of the study 和 a possible explanation for the result 不是同一类陈述。","association ≠ causation；confounding factors 可能影响观察到的关系。"],"examples":["The results are consistent with, but do not establish, the proposed mechanism.","One limitation is the small number of observations."],"pitfall":"将相关性写成确定因果，或把显著性当成实际意义。","goal":"表达结论时保留合理的不确定性和边界。"},{"topic":"条件与让步","en":"Condition and concession","summary":"if、unless、provided that、although、despite 和 whereas 等表达承担不同逻辑功能，不能因为中文都有“如果／虽然”就随意替换。","rules":["unless 常等于 if ... not，但要检查否定范围和逻辑。","despite / in spite of 后接名词或 -ing，不直接接完整句子。","although / even though 后可以接从句；though 在口语中更灵活。","provided that 表条件得到满足时才成立；whereas 表示对照。"],"examples":["Despite the delay, the experiment proceeded as planned.","The method works provided that the assumptions hold."],"pitfall":"在 despite 后直接接主谓齐全的从句，或把 whereas 当作普通的 because。","goal":"把让步、条件、因果和对比严格区分。"},{"topic":"关系从句","en":"Relative clauses","summary":"关系从句帮助确定所谈对象或补充背景。限制性从句和非限制性从句在标点、意义和代词选择上有所不同。","rules":["who 通常指人；which 指事物；whose 可表示所属关系。","where 引导与地点相关的关系从句；when 可指时间。","逗号包围的非限制性关系从句补充说明，通常用 which 而非 that。","that 在许多限制性从句中可用，但不能随意替代非限制性 which。"],"examples":["The scientist who developed the method joined the discussion.","The new detector, which was installed last year, is now operational."],"pitfall":"不考虑是否加逗号，直接把 every which 都换成 that。","goal":"看清从句是限定对象还是补充信息。"},{"topic":"时态与习惯","en":"Time and habitual meaning","summary":"used to do、be used to doing、have done、had done 和 by the time 等结构表达不同的时间与习惯关系。","rules":["used to do 表过去常有的习惯或状态，现在通常不同。","be used to doing 表已经习惯做某事；to 是介词。","have been doing 可强调从过去持续至今的活动，具体含义取决于语境。","by the time + 过去事件，可以用过去完成时说明更早发生的事。"],"examples":["I used to cycle to work, but now I take the train.","By the time we arrived, the talk had already started."],"pitfall":"把 be used to 后的动词写成原形，或将过去完成时用于所有过去事件。","goal":"将时间先后、持续与习惯区分清楚。"},{"topic":"词形与词性","en":"Word forms and functions","summary":"读写时需要判断一个词应作为名词、动词、形容词还是副词出现。词根相同不代表可以在同一语法位置互换。","rules":["accurate（形）与 accurately（副）所修饰的中心词不同。","analysis（名）/ analyze（动）/ analytical（形）是一个词族，但句法作用不同。","significant（形）/ significance（名）/ significantly（副）常用于科研语境。","数量词与可数性、比较级结构也会决定词形。"],"examples":["The measurements were recorded accurately.","The analysis revealed a statistically significant difference."],"pitfall":"把中文没有明显词形变化的说法逐词移植到英语。","goal":"先判定句法位置，再选择正确的词形。"},{"topic":"近形易混","en":"Look-alike words","summary":"某些英语词拼写相近但意义或词性不同。要用句法位置与语境辨别，不能只依赖字母外观。","rules":["affect 常为动词“影响”；effect 常为名词“效果”，但两者都有其他用法。","complement 是补充；compliment 是称赞。","principal 可指主要的或负责人；principle 是原则。","stationary 表静止；stationery 表文具。"],"examples":["The temperature change can affect the outcome.","The two approaches complement each other."],"pitfall":"依据中文“影响／效果”或拼写相似而机械替换词性。","goal":"熟悉高频近形词的基本区别及例外。"},{"topic":"口语与正式语","en":"Register and tone","summary":"同一意思可用口语、正式和学术语体表达。更复杂的词不总是更好，合适的语域才是核心。","rules":["find out 更日常，determine 更适合部分正式研究语境。","kids 是口语常见词，children 通常更中性。","buy 与 purchase 不是任何语境下都应该替换。","缩写、俚语和口头填充词在正式写作中应审慎使用。"],"examples":["We found out why the application crashed.","The study determined the approximate energy threshold."],"pitfall":"认为每句话都要用昂贵的大词，导致表达生硬甚至不准确。","goal":"让词汇难度和正式程度服从沟通目的。"},{"topic":"表达与改写","en":"Clarity and revision","summary":"好的改写既要准确保留原意，也要减少冗余、理清逻辑关系并避免不必要的歧义。","rules":["due to the fact that 在多数普通语境可以换成 because。","a large number of 可根据语境换为 many，但数量语气未必完全相同。","先把指代不明的 this / it 替换成明确名词。","相邻句子使用 however、therefore 等词前应核对它们表达的逻辑。"],"examples":["Because the sample was small, the estimate was uncertain.","This discrepancy suggests a possible calibration error."],"pitfall":"为了简短而删除关键限定词（如 may、only、under these conditions）。","goal":"在保持逻辑边界的前提下写得简洁。"},{"topic":"短语动词应用","en":"Phrasal verbs in use","summary":"短语动词在口语、工作和科技环境中很常见，但其意义不一定等于动词与介词的简单相加。","rules":["carry out a test 表执行测试；rule out a possibility 表排除可能性。","look up a word 表查词；look into a problem 表调查问题。","put off a meeting 表推迟；call off a meeting 表取消。","可分离短语动词遇到代词宾语时可能要求 put it off 而不是 put off it。"],"examples":["We need to look into the unexpected variation.","The experiment was called off because of the power failure."],"pitfall":"把短语动词的粒子简单翻成地点介词，或忽视可分离结构。","goal":"将常见短语动词作为整体语义单元掌握。"}];
const PRECISION_ITEMS=[{"topic":"动词句型","word":"suggest","stem":"The reviewer suggested ___ the abstract.","answer":"revising","w1":"to revise","w2":"revise","w3":"revised","explain":"Suggest 后可接动名词表示建议做某事；不能直接接 to do。","takeaway":"suggest doing"},{"topic":"动词句型","word":"recommend","stem":"I recommend ___ the assumptions first.","answer":"checking","w1":"to check","w2":"check","w3":"checked","explain":"Recommend doing 是常用结构；recommend that we check 也正确，但不在此空格内。","takeaway":"recommend doing"},{"topic":"动词句型","word":"avoid","stem":"We should avoid ___ the same sample twice.","answer":"counting","w1":"to count","w2":"count","w3":"counted","explain":"Avoid 后接名词或动名词，而不是 to do。","takeaway":"avoid doing"},{"topic":"动词句型","word":"consider","stem":"Have you considered ___ an alternative model?","answer":"using","w1":"to use","w2":"use","w3":"used","explain":"Consider doing 是考虑采取行动的常见形式。","takeaway":"consider doing"},{"topic":"动词句型","word":"manage","stem":"We managed ___ the problem before the deadline.","answer":"to solve","w1":"solving","w2":"solve","w3":"solved","explain":"Manage to do 强调最终成功完成。","takeaway":"manage to do"},{"topic":"动词句型","word":"encourage","stem":"The supervisor encouraged us ___ the result.","answer":"to verify","w1":"verifying","w2":"verify","w3":"verified","explain":"Encourage someone to do 是常见的及物结构。","takeaway":"encourage somebody to do"},{"topic":"动词句型","word":"prevent","stem":"The filter prevents noise ___ entering the signal.","answer":"from","w1":"to","w2":"for","w3":"at","explain":"Prevent X from doing 结构固定。","takeaway":"prevent ... from doing"},{"topic":"动词句型","word":"explain","stem":"Could you explain the procedure ___ me?","answer":"to","w1":"for","w2":"at","w3":"with","explain":"Explain something to someone，先接说明内容。","takeaway":"explain something to someone"},{"topic":"动词句型","word":"remind","stem":"Please remind me ___ the meeting notes.","answer":"to send","w1":"sending","w2":"send","w3":"sent","explain":"Remind somebody to do 提醒尚未完成的行动。","takeaway":"remind somebody to do"},{"topic":"动词句型","word":"insist","stem":"She insisted ___ checking the original data.","answer":"on","w1":"to","w2":"at","w3":"for","explain":"Insist on doing 表坚持做某事。","takeaway":"insist on doing"},{"topic":"介词选择","word":"arrive","stem":"We arrived ___ the airport before noon.","answer":"at","w1":"in","w2":"to","w3":"on","explain":"Arrive at 常用于具体地点；arrive in 常用于国家或城市。","takeaway":"arrive at a place"},{"topic":"介词选择","word":"arrive","stem":"They arrived ___ London yesterday.","answer":"in","w1":"at","w2":"to","w3":"on","explain":"Arrive in 常用于城市或国家。","takeaway":"arrive in a city"},{"topic":"介词选择","word":"depend","stem":"The outcome depends ___ the initial conditions.","answer":"on","w1":"of","w2":"at","w3":"with","explain":"Depend on/upon = 取决于。","takeaway":"depend on"},{"topic":"介词选择","word":"responsible","stem":"Who is responsible ___ this section?","answer":"for","w1":"of","w2":"with","w3":"on","explain":"Responsible for 表对工作或事项负责。","takeaway":"responsible for"},{"topic":"介词选择","word":"similar","stem":"The new result is similar ___ the earlier one.","answer":"to","w1":"with","w2":"as","w3":"of","explain":"Similar to 是常见搭配。","takeaway":"similar to"},{"topic":"介词选择","word":"interested","stem":"I'm interested ___ the underlying mechanism.","answer":"in","w1":"on","w2":"about","w3":"for","explain":"Interested in 表对某事感兴趣。","takeaway":"interested in"},{"topic":"介词选择","word":"impact","stem":"The change had little impact ___ the timing resolution.","answer":"on","w1":"to","w2":"at","w3":"of","explain":"Have an impact on something。","takeaway":"impact on"},{"topic":"介词选择","word":"agree","stem":"We agreed ___ the proposed schedule.","answer":"on","w1":"to","w2":"with","w3":"at","explain":"Agree on a plan/schedule 强调双方达成共识；agree to a proposal 强调接受提议。","takeaway":"agree on a schedule"},{"topic":"介词选择","word":"apply","stem":"She applied ___ a research position.","answer":"for","w1":"to","w2":"with","w3":"at","explain":"Apply for a position；apply to an institution。","takeaway":"apply for a position"},{"topic":"介词选择","word":"result","stem":"Poor calibration can result ___ systematic bias.","answer":"in","w1":"from","w2":"to","w3":"with","explain":"Result in 表导致；result from 表起因。","takeaway":"result in / result from"},{"topic":"冠词与数量","word":"information","stem":"We need ___ more information.","answer":"some","w1":"an","w2":"a","w3":"many","explain":"Information 泛指时不可数；some information。","takeaway":"some information"},{"topic":"冠词与数量","word":"evidence","stem":"The claim is supported by ___ evidence.","answer":"strong","w1":"a strong","w2":"many","w3":"several","explain":"Evidence 通常是不可数名词；strong evidence。","takeaway":"strong evidence"},{"topic":"冠词与数量","word":"advice","stem":"Could you give me ___ advice?","answer":"some","w1":"an","w2":"a","w3":"two","explain":"Advice 通常不可数；a piece of advice 可数化。","takeaway":"some advice"},{"topic":"冠词与数量","word":"equipment","stem":"The lab purchased three pieces of ___.","answer":"equipment","w1":"equipments","w2":"an equipment","w3":"equip","explain":"Equipment 一般不可数，使用 pieces of equipment。","takeaway":"pieces of equipment"},{"topic":"冠词与数量","word":"criterion","stem":"Accuracy is one important ___ for selection.","answer":"criterion","w1":"criteria","w2":"criterions","w3":"critera","explain":"Criterion 为单数；criteria 为复数。","takeaway":"criterion / criteria"},{"topic":"冠词与数量","word":"analysis","stem":"We performed two independent ___.","answer":"analyses","w1":"analysis","w2":"analysises","w3":"analysies","explain":"Analysis 的复数是 analyses。","takeaway":"analysis / analyses"},{"topic":"冠词与数量","word":"phenomenon","stem":"These unusual ___ merit further investigation.","answer":"phenomena","w1":"phenomenons","w2":"phenomenon","w3":"phenomene","explain":"Phenomenon 单数；phenomena 复数。","takeaway":"phenomenon / phenomena"},{"topic":"冠词与数量","word":"fewer","stem":"The revised procedure produced ___ errors.","answer":"fewer","w1":"less","w2":"much","w3":"little","explain":"Errors 是复数可数名词；正式写作优先用 fewer。","takeaway":"fewer errors"},{"topic":"冠词与数量","word":"amount","stem":"The ___ of water was measured precisely.","answer":"amount","w1":"number","w2":"many","w3":"few","explain":"Water 是不可数名词；amount of water。","takeaway":"amount of"},{"topic":"冠词与数量","word":"each","stem":"Each participant ___ a unique ID.","answer":"has","w1":"have","w2":"are having","w3":"were having","explain":"Each participant 是单数主语，通常用 has。","takeaway":"each + singular noun"},{"topic":"时间与时态","word":"since","stem":"She has worked here ___ 2021.","answer":"since","w1":"for","w2":"during","w3":"from","explain":"Since 指持续至今状态的起点。","takeaway":"since + starting point"},{"topic":"时间与时态","word":"for","stem":"She has worked here ___ five years.","answer":"for","w1":"since","w2":"during","w3":"by","explain":"For 表持续时长。","takeaway":"for + duration"},{"topic":"时间与时态","word":"until","stem":"Please submit the form ___ Friday at the latest.","answer":"by","w1":"until","w2":"since","w3":"from","explain":"By Friday = 最迟周五；until 表状态持续到该时刻。","takeaway":"by a deadline"},{"topic":"时间与时态","word":"since","stem":"I ___ in the Netherlands since April.","answer":"have lived","w1":"live","w2":"am living","w3":"lived","explain":"这里强调从过去延续到现在，have lived 与 since 相匹配。","takeaway":"have lived since"},{"topic":"时间与时态","word":"if","stem":"If the test ___, we will repeat it.","answer":"fails","w1":"will fail","w2":"failed","w3":"is fail","explain":"真实条件句中的 if 从句通常用现在时表将来。","takeaway":"if + present, will ..."},{"topic":"时间与时态","word":"when","stem":"I'll contact you when I ___ the results.","answer":"receive","w1":"will receive","w2":"received","w3":"am receive","explain":"时间从句中用一般现在时指将来。","takeaway":"when + present"},{"topic":"时间与时态","word":"already","stem":"I have ___ sent the email.","answer":"already","w1":"yet","w2":"still","w3":"ever","explain":"Already 常用于完成时肯定句。","takeaway":"have already done"},{"topic":"时间与时态","word":"yet","stem":"The data have not arrived ___.","answer":"yet","w1":"already","w2":"since","w3":"during","explain":"Yet 常用于否定句或疑问句表示到目前为止。","takeaway":"not ... yet"},{"topic":"时间与时态","word":"used","stem":"We are used ___ working with noisy signals.","answer":"to","w1":"for","w2":"at","w3":"with","explain":"Be used to 中 to 是介词，后接动名词。","takeaway":"be used to doing"},{"topic":"时间与时态","word":"used","stem":"I ___ work at night, but I no longer do.","answer":"used to","w1":"am used to","w2":"am using to","w3":"use to","explain":"Used to do 表过去的习惯。","takeaway":"used to do"},{"topic":"语气与情态","word":"could","stem":"___ you take a look when you have time?","answer":"Could","w1":"Must","w2":"Need","w3":"Shall","explain":"Could you ... 是请求协助的自然方式；其他选择在此语气或结构不合适。","takeaway":"Could you ...?"},{"topic":"语气与情态","word":"might","stem":"These results ___ indicate an underlying trend, but more data are needed.","answer":"might","w1":"must","w2":"will certainly","w3":"cannot","explain":"Might 体现证据不足时的审慎推测。","takeaway":"might indicate"},{"topic":"语气与情态","word":"should","stem":"You ___ report a safety issue immediately.","answer":"should","w1":"might not","w2":"needn't","w3":"would not","explain":"Should 表建议或规范性要求，不等同法律上的 must。","takeaway":"should do"},{"topic":"语气与情态","word":"must","stem":"Everyone ___ wear protective equipment in this restricted area.","answer":"must","w1":"could","w2":"might","w3":"would","explain":"Must 用于明确强制要求。","takeaway":"must do"},{"topic":"语气与情态","word":"may","stem":"___ I ask a quick question?","answer":"May","w1":"Must","w2":"Need","w3":"Would","explain":"May I ... 是较正式的礼貌请求。","takeaway":"May I ...?"},{"topic":"语气与情态","word":"would","stem":"I ___ appreciate your feedback on this draft.","answer":"would","w1":"must","w2":"can","w3":"need","explain":"Would appreciate 是礼貌请求中常见的表达。","takeaway":"I would appreciate ..."},{"topic":"语气与情态","word":"could","stem":"This difference ___ be explained by measurement noise.","answer":"could","w1":"has to","w2":"will definitely","w3":"must not","explain":"Could 表可能解释之一，避免无根据地断言。","takeaway":"could be explained by"},{"topic":"语气与情态","word":"likely","stem":"The result is ___ to change after recalibration.","answer":"likely","w1":"possible","w2":"maybe","w3":"probability","explain":"Be likely to 是正确搭配；possible 通常用 it is possible that ...。","takeaway":"be likely to"},{"topic":"语气与情态","word":"seem","stem":"The model ___ to perform well on this dataset.","answer":"seems","w1":"seem","w2":"is seeming","w3":"seeming","explain":"Seem to do 表示表面证据；主语 model 为单数。","takeaway":"seems to do"},{"topic":"语气与情态","word":"appear","stem":"The findings ___ consistent with the hypothesis.","answer":"appear","w1":"appear to","w2":"are appearing","w3":"appears","explain":"Appear + adjective；复数 findings 接 appear。","takeaway":"appear consistent"},{"topic":"学术证据","word":"suggest","stem":"The preliminary data ___ a possible association.","answer":"suggest","w1":"prove","w2":"guarantee","w3":"establish beyond doubt","explain":"数据初步呈现关系时用 suggest，避免过度推断。","takeaway":"suggest an association"},{"topic":"学术证据","word":"consistent","stem":"The observations are ___ with the proposed mechanism.","answer":"consistent","w1":"identical","w2":"proven","w3":"certain","explain":"Consistent with 表相符，但不意味着唯一解释。","takeaway":"consistent with"},{"topic":"学术证据","word":"correlation","stem":"A strong ___ does not by itself establish causation.","answer":"correlation","w1":"cause","w2":"reason","w3":"mechanism","explain":"Correlation 是变量间统计关联，不自动证明因果。","takeaway":"correlation ≠ causation"},{"topic":"学术证据","word":"hypothesis","stem":"We designed an experiment to test the ___.","answer":"hypothesis","w1":"theory proof","w2":"certainty","w3":"establishment","explain":"Hypothesis 是可检验的假设；实验可用于检验它。","takeaway":"test a hypothesis"},{"topic":"学术证据","word":"significant","stem":"A statistically ___ effect may still be small in practice.","answer":"significant","w1":"important","w2":"large","w3":"practical","explain":"Statistically significant 是统计概念，不等于实际影响大。","takeaway":"statistically significant"},{"topic":"学术证据","word":"robust","stem":"The conclusion remained ___ across several reasonable model choices.","answer":"robust","w1":"delicate","w2":"arbitrary","w3":"unstated","explain":"Robust 表结论对合理设定变化不敏感。","takeaway":"robust conclusion"},{"topic":"学术证据","word":"replicate","stem":"Independent teams were unable to ___ the result.","answer":"replicate","w1":"imitate casually","w2":"recall","w3":"translate","explain":"Replicate a result 指其他研究者在相应条件下重新得到结果。","takeaway":"replicate a result"},{"topic":"学术证据","word":"uncertainty","stem":"The reported estimate should include its measurement ___.","answer":"uncertainty","w1":"confusion","w2":"doubtful","w3":"ambiguity","explain":"Measurement uncertainty 是度量不确定度的规范表达。","takeaway":"measurement uncertainty"},{"topic":"学术证据","word":"evidence","stem":"The claim requires more ___ before it can be accepted.","answer":"evidence","w1":"evidences","w2":"prove","w3":"proofs","explain":"Evidence 通常不可数。","takeaway":"more evidence"},{"topic":"学术证据","word":"indicate","stem":"The arrows in the plot ___ the direction of change.","answer":"indicate","w1":"assume","w2":"infer","w3":"hypothesize","explain":"Indicate 可以表示图表符号直接指示某件事。","takeaway":"indicate the direction"},{"topic":"因果与比较","word":"result","stem":"The adjustment resulted ___ a measurable improvement.","answer":"in","w1":"from","w2":"to","w3":"of","explain":"Result in 表导致结果。","takeaway":"result in"},{"topic":"因果与比较","word":"result","stem":"The improvement resulted ___ a change in the calibration.","answer":"from","w1":"in","w2":"to","w3":"at","explain":"Result from 表起因于。","takeaway":"result from"},{"topic":"因果与比较","word":"lead","stem":"A software bug can lead ___ data loss.","answer":"to","w1":"into","w2":"for","w3":"on","explain":"Lead to + 名词，表示可能造成的结果。","takeaway":"lead to"},{"topic":"因果与比较","word":"affect","stem":"Temperature changes may ___ the measured phase.","answer":"affect","w1":"effected","w2":"effect on","w3":"effective","explain":"Affect 常为动词，表示影响；effect 常为名词。","takeaway":"affect the phase"},{"topic":"因果与比较","word":"effect","stem":"The change had little ___ on the estimate.","answer":"effect","w1":"affect","w2":"affection","w3":"effective","explain":"Have an effect on 是名词搭配。","takeaway":"an effect on"},{"topic":"因果与比较","word":"compared","stem":"The error was smaller ___ with the baseline.","answer":"compared","w1":"compare","w2":"comparing","w3":"comparison","explain":"Compared with 是分词结构；比对的对象用 with。","takeaway":"compared with"},{"topic":"因果与比较","word":"whereas","stem":"One method is precise, ___ the other is faster.","answer":"whereas","w1":"therefore","w2":"despite","w3":"because of","explain":"Whereas 可连接两个对照的分句。","takeaway":"whereas + clause"},{"topic":"因果与比较","word":"despite","stem":"___ the delay, we completed the test.","answer":"Despite","w1":"Although","w2":"Because","w3":"Nevertheless","explain":"Despite 后接名词短语；although 后接从句。","takeaway":"despite + noun"},{"topic":"因果与比较","word":"although","stem":"___ the test was difficult, it succeeded.","answer":"Although","w1":"Despite","w2":"In spite of","w3":"Due to","explain":"Although 后接完整从句。","takeaway":"although + clause"},{"topic":"因果与比较","word":"consequently","stem":"The file was corrupted; ___, we repeated the analysis.","answer":"consequently","w1":"despite","w2":"whereas","w3":"although","explain":"Consequently 是连接副词，表示因此；前面用分号或句号。","takeaway":"...; consequently, ..."},{"topic":"搭配与用词","word":"decision","stem":"We need to ___ a decision today.","answer":"make","w1":"do","w2":"take up","w3":"perform","explain":"Make a decision 是固定搭配。","takeaway":"make a decision"},{"topic":"搭配与用词","word":"research","stem":"The group ___ extensive research into the problem.","answer":"conducted","w1":"made","w2":"did a","w3":"performed to","explain":"Conduct research 适合学术正式语体；do research 也常用。","takeaway":"conduct research"},{"topic":"搭配与用词","word":"experiment","stem":"They ___ an experiment to verify the model.","answer":"conducted","w1":"constructed","w2":"committed","w3":"completed to","explain":"Conduct/run/perform an experiment 都常见。","takeaway":"conduct an experiment"},{"topic":"搭配与用词","word":"risk","stem":"The new procedure can ___ the risk of failure.","answer":"reduce","w1":"shrink down","w2":"shorten","w3":"small","explain":"Reduce the risk 是自然搭配。","takeaway":"reduce the risk"},{"topic":"搭配与用词","word":"responsibility","stem":"She took ___ for the mistake.","answer":"responsibility","w1":"responsible","w2":"response","w3":"responding","explain":"Take responsibility for 是常见结构。","takeaway":"take responsibility for"},{"topic":"搭配与用词","word":"attention","stem":"Please pay ___ to the units.","answer":"attention","w1":"interest","w2":"mind","w3":"concentration","explain":"Pay attention to 是固定搭配。","takeaway":"pay attention to"},{"topic":"搭配与用词","word":"progress","stem":"We have made considerable ___ this week.","answer":"progress","w1":"progresses","w2":"progressing","w3":"progression","explain":"Make progress 常表示取得进展；progress 一般不可数。","takeaway":"make progress"},{"topic":"搭配与用词","word":"data","stem":"The analyst ___ the data before plotting them.","answer":"processed","w1":"manufactured","w2":"committed","w3":"constructed into","explain":"Process data = 对数据进行处理。","takeaway":"process the data"},{"topic":"搭配与用词","word":"deadline","stem":"We are working against a tight ___.","answer":"deadline","w1":"calendar","w2":"date line","w3":"timetable","explain":"Tight deadline 表截止时间紧迫。","takeaway":"a tight deadline"},{"topic":"搭配与用词","word":"conclusion","stem":"The evidence does not yet support a firm ___.","answer":"conclusion","w1":"closing","w2":"finish","w3":"completion","explain":"Draw/support a conclusion 是常用学术搭配。","takeaway":"support a conclusion"},{"topic":"短语动词","word":"look","stem":"We should ___ the issue before changing the design.","answer":"look into","w1":"look at to","w2":"look forward","w3":"look after","explain":"Look into 表调查、深入了解。","takeaway":"look into an issue"},{"topic":"短语动词","word":"come","stem":"The team ___ a new solution.","answer":"came up with","w1":"came across to","w2":"came on at","w3":"came out for","explain":"Come up with = 想出。","takeaway":"come up with"},{"topic":"短语动词","word":"run","stem":"We ___ an unexpected problem during testing.","answer":"ran into","w1":"ran away","w2":"ran out","w3":"ran over to","explain":"Run into a problem = 遇到困难。","takeaway":"run into a problem"},{"topic":"短语动词","word":"put","stem":"We had to ___ the meeting until Monday.","answer":"put off","w1":"put out","w2":"put up","w3":"put in","explain":"Put off = 推迟。","takeaway":"put off a meeting"},{"topic":"短语动词","word":"figure","stem":"It took us hours to ___ what went wrong.","answer":"figure out","w1":"figure in","w2":"figure through","w3":"figure on","explain":"Figure out = 经过思考弄明白。","takeaway":"figure out"},{"topic":"短语动词","word":"bring","stem":"I'll ___ the concern in tomorrow's meeting.","answer":"bring up","w1":"bring down","w2":"bring about","w3":"bring in for","explain":"Bring up = 提出话题。","takeaway":"bring up a concern"},{"topic":"短语动词","word":"carry","stem":"We need to ___ another measurement.","answer":"carry out","w1":"carry on with to","w2":"carry over at","w3":"carry away","explain":"Carry out = 执行。","takeaway":"carry out a measurement"},{"topic":"短语动词","word":"follow","stem":"I'll ___ the request tomorrow.","answer":"follow up on","w1":"follow up to","w2":"follow down","w3":"follow away","explain":"Follow up on a request = 继续跟进。","takeaway":"follow up on"},{"topic":"短语动词","word":"work","stem":"The plan didn't ___ as expected.","answer":"work out","w1":"work at","w2":"work in","w3":"work over with","explain":"Work out 可表示计划取得成功。","takeaway":"work out"},{"topic":"短语动词","word":"end","stem":"We ___ repeating the test after the software update.","answer":"ended up","w1":"ended to","w2":"ended with to","w3":"ended for","explain":"End up doing = 最后结果做了某事。","takeaway":"end up doing"},{"topic":"逻辑与衔接","word":"however","stem":"The design is compact; ___, it is difficult to repair.","answer":"however","w1":"although","w2":"despite","w3":"because","explain":"However 在此连接两个独立句并作转折。","takeaway":"...; however, ..."},{"topic":"逻辑与衔接","word":"therefore","stem":"The sample was contaminated; ___, we discarded it.","answer":"therefore","w1":"whereas","w2":"despite","w3":"although","explain":"Therefore 表逻辑推论。","takeaway":"...; therefore, ..."},{"topic":"逻辑与衔接","word":"moreover","stem":"The method is accurate; ___, it is relatively fast.","answer":"moreover","w1":"nevertheless","w2":"unless","w3":"whereas","explain":"Moreover 叠加论点；不是转折。","takeaway":"moreover = additionally"},{"topic":"逻辑与衔接","word":"nevertheless","stem":"The results were uncertain; ___, the experiment was informative.","answer":"nevertheless","w1":"because","w2":"therefore","w3":"whereas","explain":"Nevertheless 引出与前文形成让步或对照的信息。","takeaway":"nevertheless"},{"topic":"逻辑与衔接","word":"otherwise","stem":"Keep a backup; ___, you may lose your work.","answer":"otherwise","w1":"moreover","w2":"despite","w3":"although","explain":"Otherwise = 否则。","takeaway":"otherwise"},{"topic":"逻辑与衔接","word":"whereas","stem":"The first sensor is fast, ___ the second is more accurate.","answer":"whereas","w1":"because of","w2":"despite","w3":"therefore","explain":"Whereas 连接对照分句。","takeaway":"whereas"},{"topic":"逻辑与衔接","word":"in addition","stem":"___ to the simulation, we performed measurements.","answer":"In addition","w1":"However","w2":"On the other hand","w3":"Therefore","explain":"In addition to 后接名词或动名词。","takeaway":"in addition to"},{"topic":"逻辑与衔接","word":"in contrast","stem":"___ to the control sample, the treated group improved.","answer":"In contrast","w1":"Despite","w2":"However","w3":"Since","explain":"In contrast to 后接比较对象。","takeaway":"in contrast to"},{"topic":"逻辑与衔接","word":"on the other hand","stem":"The solution is cheaper; ___, it requires more maintenance.","answer":"on the other hand","w1":"as a result","w2":"in fact","w3":"for example","explain":"On the other hand 用于权衡利弊。","takeaway":"on the other hand"},{"topic":"逻辑与衔接","word":"for example","stem":"Several factors matter; ___, temperature can affect timing.","answer":"for example","w1":"despite","w2":"whereas","w3":"as long as","explain":"For example 引出实例，不表示因果。","takeaway":"for example"},{"topic":"邮件与礼貌","word":"confirm","stem":"Could you ___ whether the file has arrived?","answer":"confirm","w1":"promise","w2":"approve","w3":"insist","explain":"Confirm whether 后接是否得到确认的事项。","takeaway":"confirm whether"},{"topic":"邮件与礼貌","word":"clarify","stem":"Could you ___ what you mean by 'stable'?","answer":"clarify","w1":"justify to","w2":"announce on","w3":"advise of to","explain":"Clarify what you mean by ... 用于请求消除歧义。","takeaway":"clarify a point"},{"topic":"邮件与礼貌","word":"appreciate","stem":"I'd ___ it if you could review this.","answer":"appreciate","w1":"apologize","w2":"agree","w3":"acknowledge to","explain":"I'd appreciate it if ... 是常见礼貌结构。","takeaway":"I'd appreciate it if ..."},{"topic":"邮件与礼貌","word":"available","stem":"Would you be ___ for a brief call tomorrow?","answer":"available","w1":"capable","w2":"conveniently","w3":"freeing","explain":"Available for a call 是询问时间是否合适。","takeaway":"available for a call"},{"topic":"邮件与礼貌","word":"follow","stem":"I'm writing to ___ on our earlier discussion.","answer":"follow up","w1":"follow over","w2":"follow out","w3":"follow in","explain":"Follow up on ... 表跟进此前事项。","takeaway":"follow up on"},{"topic":"邮件与礼貌","word":"keep","stem":"I'll ___ you updated as the work progresses.","answer":"keep","w1":"hold","w2":"make","w3":"put","explain":"Keep someone updated = 持续告知某人进展。","takeaway":"keep someone updated"},{"topic":"邮件与礼貌","word":"look","stem":"I look forward to ___ from you.","answer":"hearing","w1":"hear","w2":"heard","w3":"to hear","explain":"Look forward to 的 to 是介词，后接 -ing。","takeaway":"look forward to hearing"},{"topic":"邮件与礼貌","word":"attach","stem":"Please find the revised report ___ for review.","answer":"attached","w1":"attaching","w2":"attach","w3":"attachment","explain":"Attached 在此作后置修饰；也可以说 I’ve attached ...。","takeaway":"find ... attached"},{"topic":"邮件与礼貌","word":"concern","stem":"One ___ I have is the limited sample size.","answer":"concern","w1":"worrying","w2":"concerned","w3":"concern about to","explain":"One concern I have is ... 可以礼貌指出具体问题。","takeaway":"one concern I have"},{"topic":"邮件与礼貌","word":"thank","stem":"Thank you ___ your feedback.","answer":"for","w1":"to","w2":"with","w3":"at","explain":"Thank you for something / doing something。","takeaway":"thank you for"},{"topic":"词义辨析","word":"accurate","stem":"The measurement is ___ but not very precise: the readings vary widely around the true value.","answer":"accurate on average","w1":"precise in every trial","w2":"perfectly reproducible","w3":"far from the target","explain":"Accurate 平均接近真实值；precise 强调读数间一致性。本句刻意区分二者。","takeaway":"accuracy vs precision"},{"topic":"词义辨析","word":"efficient","stem":"The algorithm uses less memory while producing the same result, so it is more ___.","answer":"efficient","w1":"effective in accuracy","w2":"significant","w3":"credible","explain":"Efficient 强调资源利用；effective 强调达成目标。","takeaway":"efficient vs effective"},{"topic":"词义辨析","word":"historic","stem":"The agreement marked a ___ turning point.","answer":"historic","w1":"historical in date only","w2":"history","w3":"historian","explain":"Historic 强调具有历史重要性；historical 仅指与历史有关。","takeaway":"historic vs historical"},{"topic":"词义辨析","word":"economic","stem":"A more ___ heating system saves energy and money.","answer":"economical","w1":"economic","w2":"economics","w3":"economy","explain":"Economical 表节约；economic 关涉经济。","takeaway":"economical vs economic"},{"topic":"词义辨析","word":"principal","stem":"The ___ reason for the failure was a configuration error.","answer":"principal","w1":"principle","w2":"principally as a noun","w3":"principled","explain":"Principal 形容词表示主要的；principle 是原则。","takeaway":"principal vs principle"},{"topic":"词义辨析","word":"complement","stem":"The second method is a useful ___ to the first.","answer":"complement","w1":"compliment","w2":"compliant","w3":"complete","explain":"Complement = 补充物；compliment = 赞美。","takeaway":"complement vs compliment"},{"topic":"词义辨析","word":"stationary","stem":"The instrument remained ___ during the scan.","answer":"stationary","w1":"stationery","w2":"stational","w3":"station","explain":"Stationary = 静止的；stationery = 文具。","takeaway":"stationary vs stationery"},{"topic":"词义辨析","word":"affect","stem":"The temperature drift may ___ the measurement.","answer":"affect","w1":"effect as a noun","w2":"effective","w3":"affected to","explain":"Affect 常用作动词表示影响；effect 常用作名词表示结果。","takeaway":"affect vs effect"},{"topic":"词义辨析","word":"imply","stem":"The report does not ___ that the model is wrong; readers should not infer that.","answer":"imply","w1":"infer","w2":"entail to","w3":"deduce from","explain":"Imply 是说话者或文本暗示；infer 是读者推断。","takeaway":"imply vs infer"},{"topic":"词义辨析","word":"credible","stem":"The witness gave a ___ account supported by independent records.","answer":"credible","w1":"credulous","w2":"creditable with","w3":"credited","explain":"Credible = 可信的；credulous = 轻信的。","takeaway":"credible vs credulous"},{"topic":"日常互动","word":"clarify","stem":"Sorry, could you ___ what you mean by “stable”?","answer":"clarify","w1":"notify","w2":"simplify","w3":"identify","explain":"Clarify 表把含糊之处说明白；此处说的是解释 stable 的具体含义。","takeaway":"clarify what you mean"},{"topic":"日常互动","word":"interrupt","stem":"Sorry to ___, but may I ask a quick question?","answer":"interrupt","w1":"interfere","w2":"intervene","w3":"prevent","explain":"Sorry to interrupt 是礼貌插话的惯用表达。","takeaway":"Sorry to interrupt"},{"topic":"日常互动","word":"mean","stem":"Just to confirm, do you ___ we should repeat the measurement?","answer":"mean","w1":"intend","w2":"refer","w3":"mention","explain":"Do you mean ...? 用来核实对方所表达的具体意思。","takeaway":"Do you mean ...?"},{"topic":"日常互动","word":"point","stem":"That's a fair ___, but the data are incomplete.","answer":"point","w1":"place","w2":"spot","w3":"site","explain":"That's a fair point 承认对方的观点有道理，不等于完全赞同。","takeaway":"a fair point"},{"topic":"日常互动","word":"back","stem":"Can we come ___ to that question after the break?","answer":"back","w1":"over","w2":"through","w3":"into","explain":"Come back to a question 表示稍后继续讨论该问题。","takeaway":"come back to"},{"topic":"日常互动","word":"hear","stem":"I didn't quite ___ the last part. Could you repeat it?","answer":"hear","w1":"listen","w2":"sound","w3":"notice","explain":"Hear 指听见声音；listen 通常不直接接宾语，需 listen to。","takeaway":"hear the last part"},{"topic":"日常互动","word":"sure","stem":"I'm not entirely ___; I'd like to check the figures first.","answer":"sure","w1":"definite","w2":"certainly","w3":"certify","explain":"Not entirely sure 是自然的、带有限定的不确定表达。","takeaway":"not entirely sure"},{"topic":"日常互动","word":"make","stem":"That ___ sense, given the time constraints.","answer":"makes","w1":"does","w2":"takes","w3":"brings","explain":"Make sense 表说得通，主语 that 为第三人称单数。","takeaway":"That makes sense"},{"topic":"日常互动","word":"mind","stem":"Do you ___ if I open the window?","answer":"mind","w1":"object","w2":"prefer","w3":"allow","explain":"Do you mind if ...? 是询问对方是否介意的常见句型。","takeaway":"Do you mind if ...?"},{"topic":"日常互动","word":"follow","stem":"I didn't ___ that part of the explanation.","answer":"follow","w1":"trace","w2":"chase","w3":"track","explain":"I didn't follow 表没有听懂对方论述的逻辑，不一定是没听到声音。","takeaway":"I didn't follow"},{"topic":"职场邮件","word":"follow","stem":"I'm writing to follow ___ on our meeting last week.","answer":"up","w1":"on","w2":"through","w3":"by","explain":"Follow up on something = 对某事跟进；on 后接之前的讨论或事项。","takeaway":"follow up on"},{"topic":"职场邮件","word":"attach","stem":"I've ___ the revised document to this email.","answer":"attached","w1":"connected","w2":"included","w3":"added","explain":"Attach a file to an email 是常见搭配；其他词未必符合此句的邮件动作。","takeaway":"attach a document"},{"topic":"职场邮件","word":"let","stem":"Could you ___ me know whether Thursday works for you?","answer":"let","w1":"give","w2":"make","w3":"tell","explain":"Let me know whether ... 是礼貌要求回复具体信息的惯用句型。","takeaway":"let me know"},{"topic":"职场邮件","word":"convenient","stem":"Please suggest a time that is ___ for you.","answer":"convenient","w1":"comfortable","w2":"available","w3":"suitablely","explain":"Convenient for you 表对对方时间安排方便；comfortable 一般不用于排期。","takeaway":"convenient for you"},{"topic":"职场邮件","word":"appreciate","stem":"I'd ___ it if you could send the notes today.","answer":"appreciate","w1":"admire","w2":"approve","w3":"support","explain":"I'd appreciate it if ... 是礼貌请求，后面常接一个完整从句。","takeaway":"I'd appreciate it if"},{"topic":"职场邮件","word":"regard","stem":"With ___ to the schedule, I suggest a short meeting.","answer":"regard","w1":"respecting","w2":"attention","w3":"reference","explain":"With regard to 意为“关于”，用于较正式的书面表达。","takeaway":"with regard to"},{"topic":"职场邮件","word":"available","stem":"Would you be ___ for a call on Friday morning?","answer":"available","w1":"accessible","w2":"possible","w3":"openly","explain":"Available for a call 表某人有时间参加通话。","takeaway":"be available for"},{"topic":"职场邮件","word":"delay","stem":"Sorry for the ___ in getting back to you.","answer":"delay","w1":"late","w2":"postpone","w3":"slow","explain":"Delay 是名词，可用于 apology for the delay；late 是形容词或副词。","takeaway":"sorry for the delay"},{"topic":"职场邮件","word":"confirm","stem":"Could you please ___ receipt of the file?","answer":"confirm","w1":"conform","w2":"affirmed","w3":"ensure","explain":"Confirm receipt 是确认已收到某物的书面语常见搭配。","takeaway":"confirm receipt"},{"topic":"职场邮件","word":"forward","stem":"I'm looking ___ to hearing your feedback.","answer":"forward","w1":"ahead","w2":"after","w3":"through","explain":"Look forward to + -ing 是固定结构，to 在这里是介词。","takeaway":"look forward to hearing"},{"topic":"学术搭配","word":"conduct","stem":"We ___ a pilot study before the main experiment.","answer":"conducted","w1":"made","w2":"performed of","w3":"produced","explain":"Conduct a study 是自然的学术搭配；make a study 在此语境不自然。","takeaway":"conduct a study"},{"topic":"学术搭配","word":"draw","stem":"We should not ___ a firm conclusion from one trial.","answer":"draw","w1":"make","w2":"do","w3":"pull","explain":"Draw a conclusion 是常见搭配；语境强调避免过早下结论。","takeaway":"draw a conclusion"},{"topic":"学术搭配","word":"pose","stem":"The findings ___ an important question about calibration.","answer":"pose","w1":"do","w2":"give","w3":"putting","explain":"Pose a question 表提出值得研究的问题。","takeaway":"pose a question"},{"topic":"学术搭配","word":"evidence","stem":"The paper provides ___ for the proposed mechanism.","answer":"evidence","w1":"an evidence","w2":"evidences","w3":"evident","explain":"Evidence 通常是不可数名词；provide evidence for ...。","takeaway":"provide evidence for"},{"topic":"学术搭配","word":"raise","stem":"The reviewer ___ a concern about sample selection.","answer":"raised","w1":"lifted","w2":"grown","w3":"risen","explain":"Raise a concern 表提出担忧；rise 通常是不及物动词。","takeaway":"raise a concern"},{"topic":"学术搭配","word":"hypothesis","stem":"The experiment was designed to test the ___.","answer":"hypothesis","w1":"consequence","w2":"theorying","w3":"estimation","explain":"Test a hypothesis 是检验假设，不能直接等同于证明假设。","takeaway":"test a hypothesis"},{"topic":"学术搭配","word":"sample","stem":"A larger sample ___ may improve the precision of the estimate.","answer":"size","w1":"volume","w2":"numbering","w3":"quantity of","explain":"Sample size 表样本量，是固定的统计术语。","takeaway":"sample size"},{"topic":"学术搭配","word":"assumption","stem":"The model relies on several simplifying ___.","answer":"assumptions","w1":"assumes","w2":"assumptive","w3":"assumed","explain":"Several 后接复数名词；simplifying assumptions 是常见学术搭配。","takeaway":"simplifying assumptions"},{"topic":"学术搭配","word":"result","stem":"The analysis ___ a statistically significant result.","answer":"yielded","w1":"made","w2":"kept","w3":"laid","explain":"Yield a result 表得出结果，语体较正式。","takeaway":"yield a result"},{"topic":"学术搭配","word":"account","stem":"The calculation must take detector noise into ___.","answer":"account","w1":"mindful","w2":"counting","w3":"importance","explain":"Take X into account 表将某因素纳入考虑。","takeaway":"take into account"},{"topic":"论证与局限","word":"consistent","stem":"These observations are ___ with the proposed model.","answer":"consistent","w1":"equivalent","w2":"identical","w3":"proven","explain":"Consistent with 表结果与模型相容，并不证明模型是唯一解释。","takeaway":"consistent with"},{"topic":"论证与局限","word":"causation","stem":"Correlation alone does not establish ___.","answer":"causation","w1":"comparison","w2":"population","w3":"calculation","explain":"统计相关本身不能确立因果关系。","takeaway":"correlation is not causation"},{"topic":"论证与局限","word":"limitation","stem":"A key ___ of this study is its small sample size.","answer":"limitation","w1":"limitless","w2":"requirement","w3":"generalization","explain":"Limitation 表研究的局限性，此句用单数名词。","takeaway":"a limitation of a study"},{"topic":"论证与局限","word":"bias","stem":"The selection procedure may introduce systematic ___.","answer":"bias","w1":"opinion","w2":"preference","w3":"will","explain":"Systematic bias 是系统性偏差，与一般主观意见不同。","takeaway":"systematic bias"},{"topic":"论证与局限","word":"suggest","stem":"The preliminary data ___ that further tests may be needed.","answer":"suggest","w1":"prove","w2":"guarantee","w3":"ensure","explain":"数据初步时 suggest 更符合证据强度；其他选项表达过度确定。","takeaway":"data suggest"},{"topic":"论证与局限","word":"uncertainty","stem":"The estimate should include a measure of ___.","answer":"uncertainty","w1":"uncertainly","w2":"unreliability only","w3":"doubtful","explain":"Uncertainty 是名词，表示测量结果或估计的不确定程度。","takeaway":"measurement uncertainty"},{"topic":"论证与局限","word":"plausible","stem":"This is a ___ explanation, but it has not been tested.","answer":"plausible","w1":"proven","w2":"certain","w3":"guaranteed","explain":"Plausible 表看起来合理，不等于已被证实。","takeaway":"a plausible explanation"},{"topic":"论证与局限","word":"confound","stem":"Temperature changes could ___ the comparison between runs.","answer":"confound","w1":"confirm","w2":"calibrate","w3":"corroborate","explain":"Confound 指干扰比较，使解释变得不清楚。","takeaway":"confound a comparison"},{"topic":"论证与局限","word":"replicate","stem":"Independent teams should try to ___ the result.","answer":"replicate","w1":"duplicate of","w2":"repetition","w3":"validation","explain":"Replicate a result 指在独立研究中重现发现；其余形式不合句法。","takeaway":"replicate a result"},{"topic":"论证与局限","word":"scope","stem":"The conclusion holds only within the ___ of the model.","answer":"scope","w1":"scoop","w2":"scale up","w3":"spectacle","explain":"Within the scope 表在所界定的适用范围内。","takeaway":"within the scope"},{"topic":"条件与让步","word":"despite","stem":"___ the rain, the conference continued as planned.","answer":"Despite","w1":"Although","w2":"Even though","w3":"Whereas","explain":"Despite 后接名词短语；其他选项通常需要从句。","takeaway":"despite + noun"},{"topic":"条件与让步","word":"although","stem":"___ the sample was small, the trend was consistent.","answer":"Although","w1":"Despite","w2":"In spite of","w3":"Due to","explain":"Although 后接主谓结构的从句。","takeaway":"although + clause"},{"topic":"条件与让步","word":"unless","stem":"The system will remain offline ___ the test passes.","answer":"unless","w1":"because","w2":"although","w3":"whereas","explain":"Unless 表示“除非”，是恢复上线的必要条件。","takeaway":"unless = if not"},{"topic":"条件与让步","word":"provided","stem":"You may proceed ___ that the safety checks pass.","answer":"provided","w1":"unless","w2":"although","w3":"regardless","explain":"Provided that 表“以……为条件”。","takeaway":"provided that"},{"topic":"条件与让步","word":"whereas","stem":"The first method is faster, ___ the second is more accurate.","answer":"whereas","w1":"because of","w2":"despite","w3":"unless","explain":"Whereas 在此对照两种方法的不同特征。","takeaway":"whereas for contrast"},{"topic":"条件与让步","word":"even","stem":"___ though the device was new, it required calibration.","answer":"Even","w1":"Despite","w2":"In spite","w3":"Unless","explain":"Even though 强调让步关系；后有完整从句。","takeaway":"even though"},{"topic":"条件与让步","word":"regardless","stem":"The rules apply ___ of the participant's experience.","answer":"regardless","w1":"despite","w2":"however","w3":"rather","explain":"Regardless of 表无论某因素如何。","takeaway":"regardless of"},{"topic":"条件与让步","word":"in","stem":"___ spite of the setback, the team met the deadline.","answer":"In","w1":"At","w2":"By","w3":"On","explain":"In spite of 是复合介词，后接名词或 -ing。","takeaway":"in spite of"},{"topic":"条件与让步","word":"otherwise","stem":"Complete the form today; ___, your application may be delayed.","answer":"otherwise","w1":"therefore","w2":"meanwhile","w3":"likewise","explain":"Otherwise 表“不然的话”，说明没有执行前述行动可能发生的后果。","takeaway":"otherwise"},{"topic":"条件与让步","word":"only","stem":"The estimate is valid ___ if the input assumptions are correct.","answer":"only","w1":"even","w2":"since","w3":"unless","explain":"Only if 表示必要条件，不等于 if and only if。","takeaway":"only if"},{"topic":"关系从句","word":"who","stem":"The researcher ___ designed the sensor will present the results.","answer":"who","w1":"where","w2":"whose","w3":"when","explain":"Who 在限制性定语从句中指代人，作为 designed 的主语。","takeaway":"the researcher who"},{"topic":"关系从句","word":"which","stem":"The prototype, ___ arrived yesterday, is still being tested.","answer":"which","w1":"that","w2":"who","w3":"whose","explain":"逗号包围的是非限制性关系从句，通常用 which 而不是 that。","takeaway":"comma + which"},{"topic":"关系从句","word":"whose","stem":"The student ___ report won the prize is presenting today.","answer":"whose","w1":"who","w2":"which","w3":"whom","explain":"Whose 表示所属关系，修饰后面的 report。","takeaway":"whose + noun"},{"topic":"关系从句","word":"where","stem":"This is the laboratory ___ the samples were prepared.","answer":"where","w1":"which","w2":"whose","w3":"who","explain":"Where 指进行实验的地点；与 in which 意义相近。","takeaway":"the place where"},{"topic":"关系从句","word":"when","stem":"I remember the day ___ the experiment first worked.","answer":"when","w1":"what","w2":"whose","w3":"who","explain":"When 在这里用于表示时间的关系从句。","takeaway":"the day when"},{"topic":"关系从句","word":"whom","stem":"The colleague to ___ I spoke works at CERN.","answer":"whom","w1":"who","w2":"whose","w3":"which","explain":"在较正式的介词前置结构中，to whom 较自然。","takeaway":"to whom"},{"topic":"关系从句","word":"that","stem":"The sensor ___ failed has been replaced.","answer":"that","w1":"where","w2":"when","w3":"whose","explain":"That 可以在限制性关系从句中指代物并作主语。","takeaway":"the sensor that"},{"topic":"关系从句","word":"which","stem":"The method, ___ we tested twice, remained stable.","answer":"which","w1":"that","w2":"whose","w3":"where","explain":"非限制性从句通常用 which；这里作 tested 的宾语。","takeaway":"which after comma"},{"topic":"关系从句","word":"who","stem":"The volunteers ___ took part were informed in advance.","answer":"who","w1":"which","w2":"whose","w3":"where","explain":"Who 代指 people，是 took part 的主语。","takeaway":"people who"},{"topic":"关系从句","word":"whose","stem":"The device ___ output was unstable was removed.","answer":"whose","w1":"which","w2":"who","w3":"where","explain":"Whose 也可表示非人事物的所属或特征，例如 device whose output。","takeaway":"device whose output"},{"topic":"时态与习惯","word":"used","stem":"I ___ to walk to work, but now I cycle.","answer":"used","w1":"use","w2":"am used","w3":"have used","explain":"Used to + 动词原形指过去的习惯或状态。","takeaway":"used to do"},{"topic":"时态与习惯","word":"used","stem":"I'm ___ to working with international teams.","answer":"used","w1":"use","w2":"using","w3":"was use","explain":"Be used to doing 指已经习惯某项活动。","takeaway":"be used to doing"},{"topic":"时态与习惯","word":"started","stem":"By the time we arrived, the seminar had already ___.","answer":"started","w1":"start","w2":"starting","w3":"starts","explain":"Had + 过去分词构成过去完成时，说明更早发生的事件。","takeaway":"had already started"},{"topic":"时态与习惯","word":"since","stem":"She has lived in Nijmegen ___ 2024.","answer":"since","w1":"for","w2":"during","w3":"until","explain":"Since 后接起始时间点；for 后接时长。","takeaway":"since a starting point"},{"topic":"时态与习惯","word":"for","stem":"I have worked on this project ___ three years.","answer":"for","w1":"since","w2":"during","w3":"from","explain":"For three years 表持续长度。","takeaway":"for a duration"},{"topic":"时态与习惯","word":"be","stem":"By next June, the prototype will ___ ready for testing.","answer":"be","w1":"been","w2":"being","w3":"is","explain":"Will 后面接动词原形 be。","takeaway":"will be ready"},{"topic":"时态与习惯","word":"finished","stem":"When I called, she had already ___ the report.","answer":"finished","w1":"finish","w2":"finishing","w3":"finishes","explain":"Had finished 是过去完成时形式。","takeaway":"had finished"},{"topic":"时态与习惯","word":"working","stem":"They have been ___ on the upgrade since Monday.","answer":"working","w1":"work","w2":"worked","w3":"works","explain":"Have been + -ing 强调持续进行的活动。","takeaway":"have been working"},{"topic":"时态与习惯","word":"did","stem":"I ___ not know about the meeting until yesterday.","answer":"did","w1":"have","w2":"was","w3":"had been","explain":"明确过去时段 yesterday 对应一般过去时 did not know。","takeaway":"did not know"},{"topic":"时态与习惯","word":"has","stem":"The calibration has ___ completed successfully.","answer":"been","w1":"being","w2":"be","w3":"was","explain":"Has been completed 是现在完成时的被动语态。","takeaway":"has been completed"},{"topic":"词形与词性","word":"accurate","stem":"The scale was calibrated to provide ___ measurements.","answer":"accurate","w1":"accuracy","w2":"accurately","w3":"accurateness","explain":"Measurements 前需要形容词修饰，因此用 accurate。","takeaway":"accurate measurements"},{"topic":"词形与词性","word":"accurately","stem":"The instrument measured the signal ___.","answer":"accurately","w1":"accurate","w2":"accuracy","w3":"accurateness","explain":"动词 measured 需要副词修饰其动作方式。","takeaway":"measure accurately"},{"topic":"词形与词性","word":"analysis","stem":"The final ___ will be included in the report.","answer":"analysis","w1":"analyze","w2":"analytical","w3":"analytically","explain":"定冠词 The 与形容词 final 后需要名词。","takeaway":"final analysis"},{"topic":"词形与词性","word":"analyze","stem":"We need to ___ the measurements before publication.","answer":"analyze","w1":"analysis","w2":"analytical","w3":"analytically","explain":"Need to 后接动词原形。","takeaway":"analyze data"},{"topic":"词形与词性","word":"significant","stem":"The model produced a statistically ___ difference.","answer":"significant","w1":"significance","w2":"significantly","w3":"signify","explain":"形容词 significant 修饰 difference，statistically 是副词。","takeaway":"statistically significant"},{"topic":"词形与词性","word":"significantly","stem":"The new method performed ___ better.","answer":"significantly","w1":"significant","w2":"significance","w3":"signify","explain":"副词 significantly 修饰比较级 better。","takeaway":"significantly better"},{"topic":"词形与词性","word":"reliable","stem":"We need a more ___ estimate.","answer":"reliable","w1":"reliably","w2":"reliability","w3":"rely","explain":"形容词 reliable 修饰 estimate。","takeaway":"a reliable estimate"},{"topic":"词形与词性","word":"reliability","stem":"The ___ of the instrument improved after calibration.","answer":"reliability","w1":"reliable","w2":"reliably","w3":"rely","explain":"The ... of 结构需要名词。","takeaway":"instrument reliability"},{"topic":"词形与词性","word":"comparison","stem":"This ___ does not account for temperature changes.","answer":"comparison","w1":"compare","w2":"comparative","w3":"comparatively","explain":"This 后需要名词作主语。","takeaway":"make a comparison"},{"topic":"词形与词性","word":"varies","stem":"The response ___ with temperature.","answer":"varies","w1":"variety","w2":"variable","w3":"variation","explain":"句子缺少谓语动词，主语 response 为单数。","takeaway":"response varies"},{"topic":"近形易混","word":"affect","stem":"A change in voltage can ___ the output.","answer":"affect","w1":"effect","w2":"defect","w3":"reflect on","explain":"Can 后需动词原形；affect 作动词常表示影响。","takeaway":"affect the output"},{"topic":"近形易混","word":"effect","stem":"The adjustment had a measurable ___ on the output.","answer":"effect","w1":"affect","w2":"effective","w3":"defect","explain":"A measurable ... 需要名词，effect 表效果或影响。","takeaway":"have an effect on"},{"topic":"近形易混","word":"compliment","stem":"She gave her colleague a sincere ___ on the presentation.","answer":"compliment","w1":"complement","w2":"complimentary","w3":"completion","explain":"Compliment 是称赞；complement 是补充或相互配合。","takeaway":"pay a compliment"},{"topic":"近形易混","word":"complement","stem":"The two techniques ___ each other.","answer":"complement","w1":"compliment","w2":"complete to","w3":"complimentary","explain":"Complement each other 表相互补充、形成互补。","takeaway":"complement each other"},{"topic":"近形易混","word":"principal","stem":"The ___ reason for the delay was a network failure.","answer":"principal","w1":"principle","w2":"principled","w3":"principally","explain":"Principal 作形容词表主要的；principle 是名词原则。","takeaway":"principal reason"},{"topic":"近形易混","word":"principle","stem":"The design follows a simple guiding ___.","answer":"principle","w1":"principal","w2":"principally","w3":"principled","explain":"Guiding principle 表指导原则，需名词。","takeaway":"guiding principle"},{"topic":"近形易混","word":"stationery","stem":"The office ordered new ___ for the conference.","answer":"stationery","w1":"stationary","w2":"station","w3":"stational","explain":"Stationery 指文具；stationary 指不动的。","takeaway":"office stationery"},{"topic":"近形易混","word":"stationary","stem":"The car remained ___ at the traffic light.","answer":"stationary","w1":"stationery","w2":"station","w3":"stationed","explain":"Remain stationary 表保持静止。","takeaway":"remain stationary"},{"topic":"近形易混","word":"adapt","stem":"The software must ___ to changing requirements.","answer":"adapt","w1":"adopt","w2":"adept","w3":"add up","explain":"Adapt to 表适应变化；adopt 表采用。","takeaway":"adapt to"},{"topic":"近形易混","word":"adopt","stem":"The team decided to ___ a different strategy.","answer":"adopt","w1":"adapt","w2":"adept","w3":"adjust to","explain":"Adopt a strategy 表采纳一种策略。","takeaway":"adopt a strategy"},{"topic":"口语与正式语","word":"purchase","stem":"All equipment must be ___ through the approved procedure.","answer":"purchased","w1":"buying","w2":"shopped","w3":"buyed","explain":"Formal procurement context 常用 purchased；buyed 不正确。","takeaway":"purchase equipment"},{"topic":"口语与正式语","word":"children","stem":"The survey involved 200 ___ aged 6 to 12.","answer":"children","w1":"kidses","w2":"childs","w3":"childrens","explain":"正式调查写作中 children 是中性且正确的复数形式。","takeaway":"children in a survey"},{"topic":"口语与正式语","word":"determine","stem":"The experiment aimed to ___ the threshold precisely.","answer":"determine","w1":"find out of","w2":"look upon","w3":"seek about","explain":"Determine 常用于正式研究中测定或确定量值。","takeaway":"determine a threshold"},{"topic":"口语与正式语","word":"assist","stem":"Staff are available to ___ visitors with registration.","answer":"assist","w1":"helping","w2":"assistance","w3":"assistant","explain":"Be available to 后接动词原形；assist visitors with ... 是适当的正式表达。","takeaway":"assist with registration"},{"topic":"口语与正式语","word":"approximately","stem":"The experiment lasted ___ two hours.","answer":"approximately","w1":"approximate","w2":"approximation","w3":"approximative","explain":"数字前需要副词 approximately（大约）。","takeaway":"approximately two hours"},{"topic":"口语与正式语","word":"inform","stem":"Please ___ the coordinator of any schedule changes.","answer":"inform","w1":"tell to","w2":"notice to","w3":"say","explain":"Inform somebody of something 是正式的通知结构。","takeaway":"inform somebody of"},{"topic":"口语与正式语","word":"obtain","stem":"The samples were ___ from three independent sites.","answer":"obtained","w1":"gotten of","w2":"receiving","w3":"obtainment","explain":"正式科研语境中 samples were obtained from ... 很自然。","takeaway":"obtain samples"},{"topic":"口语与正式语","word":"require","stem":"The procedure ___ prior approval from the committee.","answer":"requires","w1":"is needing to","w2":"musted","w3":"requiring","explain":"客观说明程序要求时 requires 简洁自然。","takeaway":"require approval"},{"topic":"口语与正式语","word":"regarding","stem":"I am writing ___ the revised timetable.","answer":"regarding","w1":"for regards","w2":"in regard","w3":"with regard","explain":"Regarding 后直接接名词；with regard to 则是完整短语。","takeaway":"regarding the timetable"},{"topic":"口语与正式语","word":"confirm","stem":"Could you ___ the appointment in writing?","answer":"confirm","w1":"confirmation","w2":"conform","w3":"affirmation","explain":"Could you 后接动词原形；confirm the appointment 明确。","takeaway":"confirm an appointment"},{"topic":"表达与改写","word":"because","stem":"___ the system was offline, no data were recorded.","answer":"Because","w1":"Due to","w2":"In spite of","w3":"However","explain":"Because 引导完整原因从句；due to 后一般接名词短语。","takeaway":"because + clause"},{"topic":"表达与改写","word":"many","stem":"___ participants completed the survey.","answer":"Many","w1":"Much","w2":"A great deal","w3":"Amount of","explain":"Participants 为复数可数名词，many 是合适的数量限定词。","takeaway":"many participants"},{"topic":"表达与改写","word":"therefore","stem":"The assumption failed; ___, the result is unreliable.","answer":"therefore","w1":"however","w2":"nevertheless","w3":"whereas","explain":"因此得出的结果不可靠，此处是因果结论；therefore 更贴切。","takeaway":"therefore for a consequence"},{"topic":"表达与改写","word":"however","stem":"The method is accurate; ___, it is expensive.","answer":"however","w1":"therefore","w2":"similarly","w3":"moreover","explain":"前后是权衡关系，however 表转折。","takeaway":"however for contrast"},{"topic":"表达与改写","word":"specifically","stem":"The report identifies one issue; ___, the threshold is unstable.","answer":"specifically","w1":"otherwise","w2":"consequently","w3":"nevertheless","explain":"Specifically 引出前述 issue 的具体内容。","takeaway":"specifically for detail"},{"topic":"表达与改写","word":"in","stem":"___ other words, the experiment needs to be repeated.","answer":"In","w1":"On","w2":"At","w3":"By","explain":"In other words 用另一种说法重述前面的意思。","takeaway":"in other words"},{"topic":"表达与改写","word":"for","stem":"The measurement was repeated, ___ example, at a different temperature.","answer":"for","w1":"by","w2":"as","w3":"in","explain":"For example 插入一个例子说明前述观点。","takeaway":"for example"},{"topic":"表达与改写","word":"moreover","stem":"The tool is lightweight; ___, it requires no installation.","answer":"moreover","w1":"otherwise","w2":"despite","w3":"whereas","explain":"Moreover 加入同方向的补充优点。","takeaway":"moreover for addition"},{"topic":"表达与改写","word":"in","stem":"The results were uncertain; ___ particular, the smallest sample showed large variation.","answer":"in","w1":"on","w2":"at","w3":"for","explain":"In particular 强调更具体的子部分。","takeaway":"in particular"},{"topic":"表达与改写","word":"although","stem":"___ the estimate is precise, its accuracy is questionable.","answer":"Although","w1":"Because of","w2":"Nevertheless","w3":"Despite","explain":"Although 引出让步从句，与后面出现的限制形成对比。","takeaway":"although + clause"},{"topic":"短语动词应用","word":"carry","stem":"We plan to carry ___ several additional tests.","answer":"out","w1":"off","w2":"on","w3":"into","explain":"Carry out tests 表执行测试。","takeaway":"carry out tests"},{"topic":"短语动词应用","word":"rule","stem":"The evidence is not enough to rule ___ other explanations.","answer":"out","w1":"in","w2":"off","w3":"up","explain":"Rule out 表排除某种可能解释。","takeaway":"rule out an explanation"},{"topic":"短语动词应用","word":"look","stem":"Could you look ___ the unexpected change in latency?","answer":"into","w1":"up","w2":"after","w3":"for","explain":"Look into a problem 表调查原因；look up 通常查找信息。","takeaway":"look into a problem"},{"topic":"短语动词应用","word":"put","stem":"We may need to put ___ the meeting until Monday.","answer":"off","w1":"up","w2":"out","w3":"in","explain":"Put off a meeting 表推迟；不是取消。","takeaway":"put off a meeting"},{"topic":"短语动词应用","word":"call","stem":"The event was called ___ because of the storm.","answer":"off","w1":"up","w2":"in","w3":"on","explain":"Call off 表取消原计划的活动。","takeaway":"call off an event"},{"topic":"短语动词应用","word":"bring","stem":"I'd like to bring ___ one concern before we finish.","answer":"up","w1":"out","w2":"after","w3":"in","explain":"Bring up a concern 表提出一个问题或担忧。","takeaway":"bring up a concern"},{"topic":"短语动词应用","word":"figure","stem":"We finally figured ___ why the device was restarting.","answer":"out","w1":"in","w2":"off","w3":"over","explain":"Figure out 表弄明白事情的原因或答案。","takeaway":"figure out why"},{"topic":"短语动词应用","word":"turn","stem":"The issue turned ___ to be a configuration error.","answer":"out","w1":"on","w2":"up","w3":"in","explain":"Turn out to be 表后来发现结果是……。","takeaway":"turn out to be"},{"topic":"短语动词应用","word":"set","stem":"The engineer set ___ the test equipment before the session.","answer":"up","w1":"off","w2":"down","w3":"by","explain":"Set up equipment 表安装、布置设备。","takeaway":"set up equipment"},{"topic":"短语动词应用","word":"follow","stem":"We'll follow ___ with a written summary tomorrow.","answer":"up","w1":"out","w2":"down","w3":"along","explain":"Follow up with ... 表后续再做一项跟进行动。","takeaway":"follow up with"}];
const precisionWordMap=new Map();
PRECISION_ITEMS.forEach((q,i)=>{q.id='ctx20-'+(i+1);const k=q.word.toLowerCase();if(!precisionWordMap.has(k))precisionWordMap.set(k,[]);precisionWordMap.get(k).push(q)});
const precisionTopics=PRECISION_LESSONS.map(x=>x.topic);
const precisionEsc=(s)=>escapeHTML(String(s??''));
const precisionStoreKey='lexicon-context-progress-v20';
let precisionProgress={};try{const r=JSON.parse(localStorage.getItem(precisionStoreKey)||'{}');if(r&&typeof r==='object'&&!Array.isArray(r))precisionProgress=r}catch(e){}
let precisionTopic='动词句型',precisionView='guide',precisionMode='all',precisionQueue=[],precisionIndex=0,precisionAnswered=false,precisionSelected=-1,precisionCorrect=0,precisionTestAnchor='';
const precisionGet=q=>precisionProgress[q.id]||{};
const precisionDue=(q,now=Date.now())=>{const p=precisionGet(q);return p.attempts>0&&(p.due||0)<=now};
function precisionStats(){let done=0,correct=0,due=0,wrong=0;const now=Date.now();for(const q of PRECISION_ITEMS){const p=precisionGet(q);if(p.attempts){done++;correct+=p.correct||0;if(precisionDue(q,now))due++;if(p.lastCorrect===false)wrong++;}}return{done,correct,due,wrong,total:PRECISION_ITEMS.length}}
function precisionSave(){try{localStorage.setItem(precisionStoreKey,JSON.stringify(precisionProgress))}catch(e){}precisionShowStats()}
function precisionShowStats(){let s=precisionStats();const el=$('precision-stat');if(el)el.innerHTML=`<span><strong>${s.total}</strong> 情境题</span><span><strong>${s.done}</strong> 已练</span><span><strong>${s.due}</strong> 待复习</span><span><strong>${s.wrong}</strong> 最近错题</span>`}
function precisionSetView(next){precisionView=next;for(const [id,mode] of [['precision-guide','guide'],['precision-quiz','quiz'],['precision-tracks','track'],['precision-recall','recall']])$(id).classList.toggle('hidden',next!==mode);document.querySelectorAll('[data-precision-view]').forEach(b=>{const on=b.dataset.precisionView===next;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});if(next==='guide')precisionRenderGuide();else if(next==='quiz')precisionRenderQuiz();else if(next==='track')v21TrackRender();else if(next==='recall')v21RecallRender()}
function precisionChooseTopic(next){if(!precisionTopics.includes(next))return;precisionTopic=next;precisionRenderGuide()}
function precisionRenderGuide(){const target=$('precision-guide');if(!target)return;const l=PRECISION_LESSONS.find(x=>x.topic===precisionTopic)||PRECISION_LESSONS[0];const wordExamples=PRECISION_ITEMS.filter(x=>x.topic===l.topic).map(x=>x.word);const uniq=[...new Set(wordExamples)].filter(x=>lookup.has(x)).slice(0,10);
 const modules=PRECISION_LESSONS.map(x=>{let n=PRECISION_ITEMS.filter(q=>q.topic===x.topic).length;let done=PRECISION_ITEMS.filter(q=>q.topic===x.topic&&precisionGet(q).attempts).length;return `<button type="button" class="precision-topic ${x.topic===l.topic?'active':''}" data-prec-topic="${precisionEsc(x.topic)}"><span>${precisionEsc(x.en)}</span><strong>${precisionEsc(x.topic)}</strong><small>${done}/${n} · 已练</small></button>`}).join('');
 target.innerHTML=`<div class="precision-topics" aria-label="学习主题">${modules}</div><article class="precision-lesson"><div class="precision-lesson-label">FOCUS LESSON · 主题精读</div><h3>${precisionEsc(l.en)}<span>${precisionEsc(l.topic)}</span></h3><p class="precision-lead">${precisionEsc(l.summary)}</p><div class="precision-lesson-columns"><div><h4>选择表达时要注意</h4><ol>${l.rules.map(r=>`<li>${precisionEsc(r)}</li>`).join('')}</ol></div><div><h4>Examples · 语境例句</h4>${l.examples.map(e=>`<p class="precision-model">${precisionEsc(e)}</p>`).join('')}<p class="precision-trap"><b>常见误区</b> ${precisionEsc(l.pitfall)}</p></div></div><div class="precision-lesson-end"><p><b>学习目标：</b>${precisionEsc(l.goal)}</p><button class="precision-action" type="button" data-prec-start-topic="${precisionEsc(l.topic)}">练习本主题的 10 道题 <span aria-hidden="true">→</span></button></div>${uniq.length?`<div class="precision-wordlinks"><span>相关词条</span>${uniq.map(w=>`<button type="button" data-prec-linked="${precisionEsc(w)}">${precisionEsc(w)}</button>`).join('')}</div>`:''}</article>`}
function precisionCandidates(topic,mode){const now=Date.now();return PRECISION_ITEMS.filter(q=>(topic==='all'||q.topic===topic)&&(mode==='all'||mode==='new'&&!precisionGet(q).attempts||mode==='due'&&precisionDue(q,now)||mode==='wrong'&&precisionGet(q).lastCorrect===false));}
function precisionHash(str){let h=2166136261;for(const c of str){h=Math.imul(h^c.charCodeAt(0),16777619)}return h>>>0}
function precisionChoices(q){return [q.answer,q.w1,q.w2,q.w3].map((v,i)=>({text:v,index:i})).sort((a,b)=>precisionHash(q.id+':'+a.text)-precisionHash(q.id+':'+b.text));}
function precisionBegin(topic='all',mode='all',anchor=''){precisionMode=mode;const candidates=precisionCandidates(topic,mode);if(!candidates.length){precisionQueue=[];precisionIndex=0;precisionTestAnchor='';precisionSetView('quiz');return}
 const today=Math.floor(Date.now()/86400000);const arr=candidates.slice().sort((a,b)=>{const pa=precisionGet(a),pb=precisionGet(b);const weight=x=>x.attempts===undefined?0:x.lastCorrect===false?-4:(x.due||0)<=Date.now()?-3:2;return weight(pa)-weight(pb)||precisionHash(a.id+today)-precisionHash(b.id+today)});if(anchor)arr.sort((a,b)=>(a.word===anchor?-1:0)-(b.word===anchor?-1:0));
 precisionQueue=arr.slice(0,Math.min(20,arr.length));precisionIndex=0;precisionCorrect=0;precisionAnswered=false;precisionSelected=-1;precisionTestAnchor=anchor;
 $('precision-filter-topic').value=topic;$('precision-filter-mode').value=mode;precisionSetView('quiz');}
function precisionRenderQuiz(){const area=$('precision-quiz-content');if(!area)return;const q=precisionQueue[precisionIndex];if(!q){const s=precisionStats();area.innerHTML=`<div class="precision-quizcard"><p class="precision-lesson-label">PRACTICE · 语境测验</p><h3>${precisionIndex?'本轮练习完成':'没有符合条件的题目'}</h3><p>${precisionIndex?`本轮答对 ${precisionCorrect} / ${precisionIndex} 题。错误的题目已经进入复习队列。`:'试试切换“全部题目”或其他主题。'}</p><div class="precision-actions"><button type="button" class="precision-action" data-prec-restart="all">全部题目重新练习</button><button type="button" class="precision-outline" data-prec-restart="wrong">练习最近错题（${s.wrong}）</button><button type="button" class="precision-outline" data-prec-guide="1">返回主题精读</button></div></div>`;return}
 const opts=precisionChoices(q);const p=precisionGet(q);
 area.innerHTML=`<article class="precision-quizcard"><div class="precision-questiontop"><span>${precisionEsc(q.topic)} · ${precisionIndex+1} / ${precisionQueue.length}</span><span>${p.attempts?`已练 ${p.attempts} 次`:'首次练习'}</span></div><h3>选择最贴合语境的表达</h3><p class="precision-stem">${precisionEsc(q.stem).replace(/___/g,'<strong class="precision-blank">______</strong>')}</p><div class="precision-options" role="group" aria-label="选择答案">${opts.map((o,i)=>{let cl=precisionAnswered?(o.index===0?'correct':i===precisionSelected?'incorrect':''):'';return `<button type="button" class="precision-option ${cl}" data-prec-answer="${i}" ${precisionAnswered?'disabled':''}><span class="precision-option-letter">${String.fromCharCode(65+i)}</span><span>${precisionEsc(o.text)}</span></button>`}).join('')}</div>${precisionAnswered?`<div class="precision-explanation"><strong>${opts[precisionSelected]?.index===0?'答对了':'正确答案：'+precisionEsc(q.answer)}</strong><p>${precisionEsc(q.explain)}</p><span>记忆线索：${precisionEsc(q.takeaway)}</span></div><div class="precision-actions"><button type="button" class="precision-action" data-prec-next="1">${precisionIndex+1===precisionQueue.length?'查看本轮结果':'下一题 →'}</button>${lookup.has(q.word)?`<button type="button" class="precision-outline" data-prec-linked="${precisionEsc(q.word)}">查阅完整词条</button>`:''}</div>`:`<p class="precision-footnote">选择后显示答案解析。支持数字键 1–4。</p>`}</article>`}
function precisionAnswer(index){if(precisionAnswered)return;const q=precisionQueue[precisionIndex];if(!q)return;const choices=precisionChoices(q);if(index<0||index>=choices.length)return;const correct=choices[index].index===0;const p=precisionGet(q);const streak=correct?(p.streak||0)+1:0;const days=correct?[1,3,7,14,30][Math.min(streak,5)-1]:1;
 precisionProgress[q.id]={attempts:(p.attempts||0)+1,correct:(p.correct||0)+(correct?1:0),streak,lastCorrect:correct,due:Date.now()+days*86400000,lastAt:Date.now()};if(correct)precisionCorrect++;precisionAnswered=true;precisionSelected=index;precisionSave();precisionRenderQuiz()}
function precisionNext(){if(!precisionAnswered)return;precisionIndex++;precisionAnswered=false;precisionSelected=-1;precisionRenderQuiz()}
function precisionOpenWord(word){navigate('learner');setLearnTab('precision');precisionBegin('all','all',word);$('precision-page').scrollIntoView({behavior:'smooth',block:'start'});}
function precisionExport(){const data={app:'Lexicon',version:20,type:'context-practice',exportedAt:new Date().toISOString(),progress:precisionProgress};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Lexicon-context-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function precisionInstall(){precisionShowStats();precisionRenderGuide();const el=$('precision-page');if(!el)return;
 el.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;
 if(btn.dataset.precTopic!==undefined){precisionChooseTopic(btn.dataset.precTopic);return}
 if(btn.dataset.precStartTopic!==undefined){precisionBegin(btn.dataset.precStartTopic,'all');return}
 if(btn.dataset.precisionView!==undefined){precisionSetView(btn.dataset.precisionView);return}
 if(btn.dataset.precBegin!==undefined){precisionBegin($('precision-filter-topic').value,$('precision-filter-mode').value);return}
 if(btn.dataset.precAnswer!==undefined){precisionAnswer(Number(btn.dataset.precAnswer));return}
 if(btn.dataset.precNext!==undefined){precisionNext();return}
 if(btn.dataset.precGuide!==undefined){precisionSetView('guide');return}
 if(btn.dataset.precRestart!==undefined){precisionBegin('all',btn.dataset.precRestart);return}
 if(btn.dataset.precLinked!==undefined){openLinkedWord(btn.dataset.precLinked);return}
 if(btn.dataset.precExport!==undefined){precisionExport();return}
 if(btn.dataset.precImport!==undefined){$('precision-import-file').click();return}
 });
 $('precision-import-file').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;const data=JSON.parse(await file.text());if(data.type!=='context-practice'||!data.progress||typeof data.progress!=='object'||Array.isArray(data.progress))throw Error('格式不符');const clean={};for(const [id,p] of Object.entries(data.progress)){if(!/^ctx20-\d+$/.test(id)||!p||typeof p!=='object')continue;const attempts=Math.min(10000,Math.max(0,Number(p.attempts)||0));const due=Math.max(0,Number(p.due)||0);clean[id]={attempts,correct:Math.max(0,Number(p.correct)||0),streak:Math.max(0,Number(p.streak)||0),lastCorrect:p.lastCorrect===true,due,lastAt:Number(p.lastAt)||0};}precisionProgress=clean;precisionSave();precisionRenderGuide();toast('语境练习记录已导入')}catch(err){toast('导入失败：文件格式不正确')}finally{e.target.value=''}});
 document.addEventListener('click',e=>{const a=e.target.closest('[data-prec-word]');if(!a)return;e.stopPropagation();precisionOpenWord(a.dataset.precWord)},true);
 document.addEventListener('keydown',e=>{if(section!=='learner'||learnTab!=='precision'||precisionView!=='quiz')return;if(e.altKey||e.ctrlKey||e.metaKey||e.target.closest('input,textarea,select,[contenteditable=true]'))return;if(!precisionAnswered&&/^[1-4]$/.test(e.key)){e.preventDefault();precisionAnswer(Number(e.key)-1)}else if(precisionAnswered&&e.key==='Enter'){e.preventDefault();precisionNext()}});
}

/* v21 learning paths and answer-first retrieval, no external service required. */
const V21_TRACKS=[
 {name:'日常交流',icon:'✦',en:'Everyday fluency',intro:'听懂、接话、表达意见以及自然地处理日常交流。',topics:['日常互动','口语与正式语','短语动词','短语动词应用','语气与情态','介词选择','词义辨析']},
 {name:'职场协作',icon:'◇',en:'Workplace communication',intro:'在邮件、会议、项目沟通中清晰而得体地提出请求、跟进和反馈。',topics:['职场邮件','邮件与礼貌','动词句型','搭配与用词','逻辑与衔接','日常互动']},
 {name:'学术英语',icon:'◈',en:'Academic reading & writing',intro:'控制证据强度、说明局限、构建论证并熟悉专业搭配。',topics:['学术搭配','论证与局限','学术证据','因果与比较','表达与改写','词形与词性']},
 {name:'语法基础',icon:'□',en:'Grammar for accuracy',intro:'稳固时态、条件、定语从句、词形和常见语法结构。',topics:['冠词与数量','时态与习惯','时间与时态','关系从句','条件与让步','近形易混']}
];
function v21TrackRender(){const host=$('v21-tracks');if(!host)return;
 host.innerHTML=`<div class="v21-guide"><div class="precision-lesson-label">PERSONAL STUDY PATHS</div><h3>Choose a learning direction.</h3><p>每条路线都连接已有讲解和语境练习。完成率按相关主题中已经练习的题目计算，而不是按打开页面的次数计算。可以自由切换路线。</p></div><div class="v21-trackgrid">${V21_TRACKS.map(t=>{const qs=PRECISION_ITEMS.filter(q=>t.topics.includes(q.topic));const done=qs.filter(q=>precisionGet(q).attempts).length;const next=t.topics.find(n=>PRECISION_ITEMS.some(q=>q.topic===n&&!precisionGet(q).attempts))||t.topics[0];const pct=Math.round(done/Math.max(1,qs.length)*100);return `<article class="v21-track"><span class="v21-track-icon">${t.icon}</span><div class="v21-track-en">${precisionEsc(t.en)}</div><h3>${precisionEsc(t.name)}</h3><p>${precisionEsc(t.intro)}</p><div class="v21-track-meter" role="progressbar" aria-label="${precisionEsc(t.name)}完成度" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct}%"></span></div><div class="v21-track-count">已练 ${done} / ${qs.length} 题 · ${pct}%</div><div class="v21-track-chips">${t.topics.map(s=>`<button type="button" data-v21-topic="${precisionEsc(s)}">${precisionEsc(s)}</button>`).join('')}</div><button class="precision-action v21-track-go" type="button" data-v21-topic="${precisionEsc(next)}">继续：${precisionEsc(next)} <span aria-hidden="true">→</span></button></article>`}).join('')}</div>`;
}
const V21_RECALL_KEY='lexicon-recall-progress-v21';let v21RecallProgress={};try{const p=JSON.parse(localStorage.getItem(V21_RECALL_KEY)||'{}');if(p&&typeof p==='object'&&!Array.isArray(p))v21RecallProgress=p;}catch(e){}
let v21RecallQueue=[],v21RecallIndex=0,v21RecallRevealed=false,v21RecallGraded=0,v21RecallMastered=0;
function v21RecallSave(){try{localStorage.setItem(V21_RECALL_KEY,JSON.stringify(v21RecallProgress))}catch(e){}}
function v21RecallGet(q){return v21RecallProgress[q.id]||{}}
function v21RecallDue(q){const p=v21RecallGet(q);return !!(p.attempts&&Number(p.due||0)<=Date.now())}
function v21RecallStats(){const practiced=PRECISION_ITEMS.filter(q=>v21RecallGet(q).attempts).length;const due=PRECISION_ITEMS.filter(v21RecallDue).length;return {practiced,due}}
function v21RecallStart(){let topic=$('v21-recall-topic').value,mode=$('v21-recall-filter').value;
 let pool=PRECISION_ITEMS.filter(q=>(topic==='all'||q.topic===topic)&&(mode==='all'||mode==='new'&&!v21RecallGet(q).attempts||mode==='due'&&v21RecallDue(q)));
 const today=Math.floor(Date.now()/86400000);
 pool.sort((a,b)=>{let pa=v21RecallGet(a),pb=v21RecallGet(b);let wa=pa.attempts?(v21RecallDue(a)?-1:1):0,wb=pb.attempts?(v21RecallDue(b)?-1:1):0;return wa-wb||precisionHash(a.id+today)-precisionHash(b.id+today)});
 v21RecallQueue=pool.slice(0,20);v21RecallIndex=0;v21RecallRevealed=false;v21RecallGraded=0;v21RecallMastered=0;v21RecallRender();
}
function v21RecallRender(){const area=$('v21-recall-content');if(!area)return;const s=v21RecallStats(),q=v21RecallQueue[v21RecallIndex];
 if(!q){area.innerHTML=`<article class="v21-recall-card"><span class="precision-lesson-label">ACTIVE RECALL</span><h3>${v21RecallGraded?'本轮回忆完成':'不看选项，先自己回忆。'}</h3><p>${v21RecallGraded?`这轮完成 ${v21RecallGraded} 题，其中 ${v21RecallMastered} 题自评掌握。`:'先根据句子的上下文填空，随后展示推荐答案与解释。没有机器“自由表达评分”，请根据你实际想到的内容自评。'}</p><div class="v21-recall-foot"><span>累计练习 ${s.practiced} / ${PRECISION_ITEMS.length}</span><span>今日到期 ${s.due} 题</span></div><button class="precision-action" type="button" data-v21-recall-start="1">${v21RecallGraded?'开始下一轮':'开始主动回忆'}</button></article>`;return;}
 area.innerHTML=`<article class="v21-recall-card"><div class="precision-questiontop"><span>${precisionEsc(q.topic)} · ${v21RecallIndex+1} / ${v21RecallQueue.length}</span><span>${v21RecallGet(q).attempts?'已复习 '+v21RecallGet(q).attempts+' 次':'首次回忆'}</span></div><h3>不看选项，尝试补全句子</h3><p class="precision-stem">${precisionEsc(q.stem).replace('___','<span class="v21-recall-blank">__________</span>')}</p><div class="v21-recall-coach">提示：先在心中说出答案，或用纸笔写下；再展开参考答案。部分语境存在其他合理表达，应根据含义与语法自评。</div>${v21RecallRevealed?`<div class="precision-explanation v21-recall-answer"><strong>推荐答案：${precisionEsc(q.answer)}</strong><p>${precisionEsc(q.explain)}</p><span>语块：${precisionEsc(q.takeaway)}</span></div><div class="v21-recall-grades"><button type="button" data-v21-recall-grade="0">还不熟悉 · 明日复习</button><button type="button" data-v21-recall-grade="1">已经掌握 · 延后复习</button></div>${lookup.has(q.word)?`<button class="precision-outline" data-v21-linked="${precisionEsc(q.word)}" type="button">查看 ${precisionEsc(q.word)} 的词条</button>`:''}`:`<button type="button" class="precision-action" data-v21-recall-reveal="1">显示参考答案与解释</button>`}</article>`;
}
function v21RecallGrade(ok){if(!v21RecallRevealed)return;const q=v21RecallQueue[v21RecallIndex];if(!q)return;const prev=v21RecallGet(q);const streak=ok?(prev.streak||0)+1:0;const span=ok?[1,3,7,14,30][Math.min(streak,5)-1]:1;
 v21RecallProgress[q.id]={attempts:(prev.attempts||0)+1,streak,lastCorrect:!!ok,due:Date.now()+span*86400000,lastAt:Date.now()};v21RecallSave();v21RecallIndex++;v21RecallGraded++;if(ok)v21RecallMastered++;v21RecallRevealed=false;v21RecallRender();}
function v21RecallExport(){dl('Lexicon-active-recall-v21.json',JSON.stringify({app:'Lexicon',type:'active-recall',version:21,exportedAt:new Date().toISOString(),progress:v21RecallProgress},null,2),'application/json;charset=utf-8')}
function v21Install(){const el=$('precision-page');if(!el)return;const sel=$('v21-recall-topic');sel.innerHTML='<option value="all">全部主题</option>'+PRECISION_LESSONS.map(x=>`<option value="${precisionEsc(x.topic)}">${precisionEsc(x.topic)}</option>`).join('');v21TrackRender();v21RecallRender();
 el.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.v21Topic!==undefined){precisionChooseTopic(b.dataset.v21Topic);precisionSetView('guide');$('precision-guide').scrollIntoView({behavior:'smooth',block:'start'});}
 else if(b.dataset.v21RecallStart!==undefined){v21RecallStart()}
 else if(b.dataset.v21RecallReveal!==undefined){v21RecallRevealed=true;v21RecallRender()}
 else if(b.dataset.v21RecallGrade!==undefined){v21RecallGrade(b.dataset.v21RecallGrade==='1')}
 else if(b.dataset.v21RecallExport!==undefined){v21RecallExport()}
 else if(b.dataset.v21RecallImport!==undefined){$('v21-recall-file').click()}
 else if(b.dataset.v21Linked!==undefined){openLinkedWord(b.dataset.v21Linked)}
 });
 $('v21-recall-file').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;const obj=JSON.parse(await file.text());if(obj.type!=='active-recall'||!obj.progress||typeof obj.progress!=='object'||Array.isArray(obj.progress))throw Error('type');const clean={};for(const [id,val] of Object.entries(obj.progress)){if(!/^ctx20-\d+$/.test(id)||!val||typeof val!=='object')continue;clean[id]={attempts:Math.max(0,Math.min(10000,Number(val.attempts)||0)),streak:Math.max(0,Math.min(30,Number(val.streak)||0)),lastCorrect:val.lastCorrect===true,due:Math.max(0,Number(val.due)||0),lastAt:Math.max(0,Number(val.lastAt)||0)}}v21RecallProgress=clean;v21RecallSave();v21RecallRender();toast('主动回忆记录已恢复')}catch(err){toast('无法导入主动回忆记录')}finally{e.target.value=''}});
}

