const collectionById=new Map(COLLECTION_DEFS.map(g=>[g.id,g]));
// Only cumulative, nested learning paths have a meaningful predecessor.
const COLLECTION_PREVIOUS={'spoken1500':'spoken500','spoken3000':'spoken1500','spoken5000':'spoken3000','cn-high':'cn-junior','cet4':'cn-high','cet6':'cet4','gre':'gre-priority'};
let onlyNew=false;
try{onlyNew=localStorage.getItem('lexicon-collection-only-new')==='true'}catch(e){}

let activeCollectionId='',practiceCollectionId='',autoOpenCollectionWord=false;
const grePriority=new Set(words.filter(w=>(w.examTags||'').includes('宝')).sort((a,b)=>(a.frequencyOrder||1e9)-(b.frequencyOrder||1e9)).slice(0,3000).map(w=>w.word));
function belongsToCollection(w,id){
 const g=collectionById.get(id);if(!g)return true;
 if(g.kind==='rank')return !!w.frequencyOrder&&w.frequencyOrder<=g.limit;
 if(g.kind==='tags')return [...g.tags].some(t=>(w.examTags||'').includes(t));
 if(g.kind==='toefl')return !!w.core||(w.examTags||'').includes('托');
 if(g.kind==='grePriority')return grePriority.has(w.word);
 if(g.kind==='core')return !!w.core;
 if(g.kind==='va')return !!w.va;
 return true;
}
const collectionCounts=new Map(COLLECTION_DEFS.map(g=>[g.id,words.reduce((n,w)=>n+(belongsToCollection(w,g.id)?1:0),0)]));
function groupMember(w,id){const previous=COLLECTION_PREVIOUS[id];return belongsToCollection(w,id)&&(!onlyNew||!previous||!belongsToCollection(w,previous))}
const incrementalCounts=new Map(COLLECTION_DEFS.map(g=>[g.id,words.reduce((n,w)=>n+(belongsToCollection(w,g.id)&&(!COLLECTION_PREVIOUS[g.id]||!belongsToCollection(w,COLLECTION_PREVIOUS[g.id]))?1:0),0)]));
function groupCount(id){return onlyNew?incrementalCounts.get(id):collectionCounts.get(id)}
function updateCollectionMode(){
 document.querySelectorAll('[data-collection-mode]').forEach(b=>{const on=(b.dataset.collectionMode==='new')===onlyNew;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))});
 const g=collectionById.get(activeCollectionId),prev=COLLECTION_PREVIOUS[activeCollectionId];
 if(g){$('collection-current-meta').textContent=fmt(groupCount(activeCollectionId))+(onlyNew&&prev?' 个新增词条 · 不含 '+collectionById.get(prev).title:' 个词条 · 可与其他词组重叠');}
}
function setCollectionMode(value){onlyNew=value;try{localStorage.setItem('lexicon-collection-only-new',String(onlyNew))}catch(e){}updateCollectionMode();if(section==='collections')renderCollections();if(!['study','insights','analysis','collections'].includes(section))render();}

function collectionTile(g){const size=groupCount(g.id),c=g.category;return `<article class="collection-tile" data-kind="${c}" data-open-collection="${g.id}" tabindex="0" aria-label="打开 ${escapeHTML(g.title)} 词汇组"><div class="collection-tile-head"><span class="collection-tier">STEP ${String(g.tier).padStart(2,'0')}</span><span class="collection-count">${fmt(size)} 词${onlyNew&&COLLECTION_PREVIOUS[g.id]?' · 新增':''}</span></div><h4>${escapeHTML(g.title)}</h4><span class="collection-sub">${escapeHTML(g.subtitle)}</span><p>${escapeHTML(g.short)}</p><div class="collection-tile-bottom"><button type="button" data-open-collection="${g.id}" aria-label="浏览${escapeHTML(g.title)}">浏览词汇 <span aria-hidden="true">→</span></button><button type="button" class="collection-quick" data-study-collection="${g.id}" title="从本组开始复习" aria-label="练习${escapeHTML(g.title)}">开始练习</button></div></article>`}
function renderCollections(){
 updateCollectionMode();
 $('collection-total').textContent=fmt(words.length);
 $('collection-catalog').innerHTML=COLLECTION_CATEGORY.map(c=>`<section class="collection-category"><div class="collection-section-heading"><div><span class="eyeline">${c.en.toUpperCase()}</span><h3>${c.title}</h3><p>${c.subtitle}</p></div><span class="collection-category-count">${COLLECTION_DEFS.filter(g=>g.category===c.id).length} 组</span></div><div class="collection-grid">${COLLECTION_DEFS.filter(g=>g.category===c.id).map(collectionTile).join('')}</div></section>`).join('');
}
function openCollection(id){const g=collectionById.get(id);if(!g)return;activeCollectionId=id;practiceCollectionId='';autoOpenCollectionWord=true;$('group-filter').value=id;['origin','difficulty','frequency','verbal','pos','state'].forEach(k=>$(k).value='all');$('sort').value='recommended';$('search').value='';navigate('group-words')}
function startCollectionPractice(id){activeCollectionId=id;practiceCollectionId=id;navigate('study')}

function getP(w){return progress[w]||{}}
function isDue(w){const p=getP(w);return p.seen&&(p.next||0)<=TODAY()}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.add('hidden'),3400)}
function save(){try{localStorage.setItem('lexicon-progress-v2',JSON.stringify(progress))}catch(e){toast('本地保存失败，请导出学习记录备份')}refreshMetrics()}
function refreshMetrics(){let saved=0,known=0;for(const w of words){const p=getP(w.word);if(p.star)saved++;if(p.stage>=2)known++} $('m-learned').textContent=fmt(known);$('m-saved').textContent=fmt(saved);$('m-learned-sub').textContent=(known/words.length*100).toFixed(1)+'% · 已进入掌握阶段'}
function wordBand(w){return w.freqLevel?'F'+w.freqLevel:'F?'}
function scopeOK(w){return section==='group-words'?groupMember(w,activeCollectionId):section==='saved'?!!getP(w.word).star:section==='core'?w.core:section==='va'?!!w.va:true}
function bestScore(w){return (w.level||10)*1e8+(w.core?0:w.va?1:2)*1e6+(w.va||0)*10000+(w.freqPages||100000)/40}
function matches(w,search){if(!search)return true;return w.word.includes(search)||dialectMatches(w,search)||(w.zh&&w.zh.includes(search))||(w.zhBrief&&w.zhBrief.includes(search))||w.definition.toLowerCase().includes(search)||(w.explain&&w.explain.toLowerCase().includes(search))||(w.glosses&&w.glosses.some(x=>x.toLowerCase().includes(search)))||(w.example&&w.example.toLowerCase().includes(search))||(w.bookDefinition&&w.bookDefinition.toLowerCase().includes(search))}
