 let out=words.filter(w=>(!lexOnlyCurated||Object.prototype.hasOwnProperty.call(SENSE_GLANCE,w.word))&&(focus==='all'||focus==='contrast'&&Object.prototype.hasOwnProperty.call(LEX40_CONTRASTS,w.word)||focus==='usage'&&Object.prototype.hasOwnProperty.call(USAGE_NOTES,w.word))&&(!atlasBrowseSet||atlasBrowseSet.has(w.word))&&scopeOK(w)&&(g==='all'||groupMember(w,g))&&(o==='all'||(o==='core'&&w.core)||(o==='va'&&w.va)||(o==='reading'&&w.origin==='词典阅读拓展')||(o==='exam'&&w.origin==='考试扩展'))&&(d==='all'||w.level===+d)&&(f==='all'||w.freqLevel===+f)&&(v==='all'||(v==='none'&&!w.va)||w.va===+v)&&(p==='all'||w.pos===p)&&(variant==='all'||(variant==='any'?dialectFor(w.word).length:dialectTypes(w).includes(variant)))&&(s==='all'||(s==='new'&&!getP(w.word).seen)||(s==='learning'&&getP(w.word).seen&&(getP(w.word).stage||0)<2)||(s==='known'&&(getP(w.word).stage||0)>=2)||(s==='due'&&isDue(w.word)))&&(focusedWord?w.word===focusedWord:matches(w,q)));
 let comp;
 if(sort==='alpha')comp=(a,b)=>a.word.localeCompare(b.word);
 else if(sort==='freq-asc')comp=(a,b)=>(a.freqPages||1e9)-(b.freqPages||1e9)||a.word.localeCompare(b.word);
 else if(sort==='freq-desc')comp=(a,b)=>(b.freqPages||1e9)-(a.freqPages||1e9)||a.word.localeCompare(b.word);
 else if(sort==='diff-asc')comp=(a,b)=>a.level-b.level||(a.freqPages||1e9)-(b.freqPages||1e9);
 else if(sort==='diff-desc')comp=(a,b)=>b.level-a.level||(a.freqPages||1e9)-(b.freqPages||1e9);
 else if(sort==='va')comp=(a,b)=>(a.va||99)-(b.va||99)||(a.vaOrder||99)-(b.vaOrder||99)||a.word.localeCompare(b.word);
