function synonymsPanel(w){
 const groups=[];const seen=new Set();
 for(const sense of w.glosses||[]){
   const key=String(sense).toLowerCase().replace(/\s+/g,' ').trim();
   if(seen.has(key))continue;seen.add(key);
   const options=(senseToWords.get(key)||[]).filter(v=>v!==w.word&&lookup.has(v));
   if(!options.length)continue;
   options.sort((a,b)=>(lookup.get(a).frequencyOrder||1e8)-(lookup.get(b).frequencyOrder||1e8));
   groups.push({sense,options});
 }
 if(!groups.length)return '<section class="synonyms-panel"><div class="minor-title">同义词 <span>· SYNONYMS BY SENSE</span></div><p class="syn-empty">暂无可以按相同义项确认的同义词。</p></section>';
 const draw=(g)=>`<div class="syn-sense"><p class="syn-meaning">${escapeHTML(g.sense)}</p><div class="syn-word-links">${g.options.map(v=>`<button type="button" class="syn-word" data-related-word="${escapeHTML(v)}" title="跳转到 ${escapeHTML(v)}">${escapeHTML(v)}</button>`).join('')}</div></div>`;
 return `<section class="synonyms-panel"><div class="minor-title">同义词 <span>· SYNONYMS BY SENSE</span></div>${groups.slice(0,4).map(draw).join('')}${groups.length>4?`<details><summary class="syn-more">展开另外 ${groups.length-4} 组义项</summary>${groups.slice(4).map(draw).join('')}</details>`:''}<p class="root-disclaimer">同一词典义项下的词汇可能在语体、搭配和语用上仍有差异。</p></section>`;
}

const MORPH_CASES={"inspect":{"segments":"in- · 向内 + specere · 看","origin":"来自拉丁语 inspicere，原义是向里面看、仔细查看。","note":"inspect 常用于仔细检查状态或质量；respect 虽同源，但现代词义已经转向尊重。"},"retrospect":{"segments":"retro- · 向后 + spect- · 看","origin":"来自拉丁语 retrospicere，意为向后看。","note":"in retrospect 是“事后回顾”，不等于预测未来的 prospect。"},"prospect":{"segments":"pro- · 向前 + spect- · 看","origin":"拉丁语 prospicere 意为向前看，引申为前景、预期。","note":"prospective 指预期的、未来可能成为的。"},"predict":{"segments":"pre- · 事先 + dict- · 说","origin":"来自拉丁语 praedicere，即提前说出。","note":"predict 是预测结果；forecast 更常见于天气、经济等趋势。"},"contradict":{"segments":"contra- · 相反 + dict- · 说","origin":"拉丁语 contradicere 指反对或说相反的话。","note":"contradiction 是相互矛盾；不能与 contrast（对比）混同。"},"dictionary":{"segments":"dict- · 说、词语 + -ary · 相关事物","origin":"词源经晚期拉丁语 dictionarium 与词语和言语相关。","note":"diction 指措辞或发音，dictionary 是词典。"},"transport":{"segments":"trans- · 横越 + port- · 搬运","origin":"来自拉丁语 transportare，意为运送到另一边。","note":"transport 强调运输，transmit 强调传递（信号或信息）。"},"portable":{"segments":"port- · 携带 + -able · 可以","origin":"拉丁语 portare 是携带；后缀 -able 形成“可……的”形容词。","note":"portable 与 import、export 共享 port 家族。"},"import":{"segments":"im-/in- · 向内 + port- · 搬运","origin":"拉丁语 importare 表示带入。","note":"export 是输出；import 也可引申为重要性（import），但语法与意义不同。"},"export":{"segments":"ex- · 向外 + port- · 搬运","origin":"拉丁语 exportare 指向外运送。","note":"import/export 是方向相反的一组贸易用语。"},"manuscript":{"segments":"manu- · 手 + script- · 写","origin":"源自拉丁语 manu scriptus，意为手写的。","note":"manuscript 是手稿；script 是剧本或脚本，字根同源。"},"inscribe":{"segments":"in- · 在上面 + scrib- · 写","origin":"拉丁语 inscribere 是写在某物上。","note":"inscription 是刻文；describe 指描述，不是同样的行为。"},"subscribe":{"segments":"sub- · 在下方 + scrib- · 写","origin":"拉丁语 subscribere 指在下方签名，后产生订阅等意义。","note":"subscribe to a journal 不再要求真的亲笔签名。"},"introduce":{"segments":"intro- · 向内 + duc- · 引导","origin":"来自拉丁语 introducere，即引入。","note":"introduce a person 和 introduce a method 分别是介绍人与引入方法。"},"conduct":{"segments":"con- · 共同 + duc- · 引领","origin":"拉丁语 conducere 原指集合、带领；进入英语后发展出行为、指挥、传导等意义。","note":"conduct an experiment 是主持或实施实验。"},"reduce":{"segments":"re- · 往回 + duc- · 引导","origin":"来自拉丁语 reducere，意为带回，后来有降低、缩减之义。","note":"reduce 是减少；deduce 是从前提推导。"},"reject":{"segments":"re- · 向回 + ject- · 投掷","origin":"来自拉丁语 reicere，原义扔回。","note":"reject a proposal 表示拒绝方案。"},"inject":{"segments":"in- · 向内 + ject- · 投掷","origin":"来自拉丁语 inicere，指抛入。","note":"inject 可指注入药物，也可指引入观点或流动性。"},"project":{"segments":"pro- · 向前 + ject- · 投掷","origin":"来自拉丁语 proicere，意为投向前方。","note":"project 可以是名词“项目”，也可指投射、预测。"},"transmit":{"segments":"trans- · 跨过 + mit- · 送出","origin":"拉丁语 transmittere 指送过、传过去。","note":"transmission、emit、submit 与 mit-/miss- 同源。"},"permission":{"segments":"per- · 通过 + miss- · 发送","origin":"与 permit 同源，来自拉丁语 permittere。","note":"permit 是允许；permission 是允许、许可。"},"credible":{"segments":"cred- · 相信 + -ible · 可以","origin":"credere 是相信；credible 指有理由相信的。","note":"credulous 则是“轻信的”，两者不能互换。"},"incredible":{"segments":"in- · 不 + cred- · 相信 + -ible","origin":"字面上是难以置信的，日常常用于赞叹。","note":"incredible 可以表示难以置信或令人惊叹，语境决定褒贬。"},"revoke":{"segments":"re- · 回 + voc- · 呼叫","origin":"拉丁语 revocare 意为叫回，后引申为撤销。","note":"revoke a license 是撤销许可；evoke 是唤起情感或回忆。"},"vocabulary":{"segments":"voc- · 发声、词语 + -ary","origin":"与拉丁语 vocabulum“词、名称”有关。","note":"vocal（声音的）、vocation（职业召唤）同属发声家族。"},"attract":{"segments":"ad-/at- · 朝向 + tract- · 拉","origin":"拉丁语 attrahere 原义拉向自己。","note":"attraction 是吸引力；retract 是收回。"},"extract":{"segments":"ex- · 向外 + tract- · 拉","origin":"来自拉丁语 extrahere，意为拉出。","note":"extract a sample 可以是提取样品；extract a passage 是摘录。"},"retract":{"segments":"re- · 向后 + tract- · 拉","origin":"拉丁语 retractare 的相关形式有拉回的概念。","note":"retract a claim 是撤回声明。"},"construct":{"segments":"con- · 一起 + struct- · 建造","origin":"拉丁语 construere 是堆砌、建造。","note":"construct 指建造；reconstruct 指重建。"},"obstruct":{"segments":"ob- · 对着、阻拦 + struct- · 建造","origin":"源自拉丁语 obstruere，意为筑起障碍。","note":"obstruction 是阻碍，instruction 不是同义词。"},"transform":{"segments":"trans- · 越过、改变 + form · 形状","origin":"拉丁语 transformare 指改变形态。","note":"transform 常表示显著改变；modify 多为局部调整。"},"invisible":{"segments":"in- · 不 + vis- · 看见 + -ible","origin":"来自拉丁语 invisibilis，意为不可见的。","note":"in- 这里表示否定，但在 inject 中表示“向内”。"},"revise":{"segments":"re- · 再次 + vis- · 看","origin":"来自拉丁语 revisere，与重新查看有关。","note":"revise 可以指修改文本，也可指复习（英式英语）。"},"biology":{"segments":"bio- · 生命 + -logy · 学问","origin":"由希腊语 bios（生命）与 -logia（论述、研究）组成。","note":"bio- 出现在 biography、biosphere 等词中。"},"biography":{"segments":"bio- · 生命 + -graphy · 记录","origin":"希腊词根组合，指对一个人的生命经历的书写。","note":"autobiography 加入 auto-，表示自传。"},"geography":{"segments":"geo- · 地球 + -graphy · 描述","origin":"源于希腊语 gē（地）及 graphein（书写）。","note":"geology 研究地球，geography 偏空间与地表分布。"},"chronology":{"segments":"chron- · 时间 + -logy · 研究","origin":"希腊语 chronos 表示时间。","note":"chronology 强调时间顺序，chronic 指长期持续。"},"synchronize":{"segments":"syn- · 一起 + chron- · 时间 + -ize","origin":"由希腊词根构成，表示使同一时间发生。","note":"synchronization 是同步；anachronism 是时代错置。"},"telephone":{"segments":"tele- · 远 + phon- · 声音","origin":"由希腊词根组合，字面上是远距离的声音。","note":"telephone 与 microphone、phonetics 共享 phon- 家族。"},"microphone":{"segments":"micro- · 小 + phon- · 声音","origin":"组合词原指将微弱声音转为可感知信号的装置。","note":"micro- 指微小，并不意味着声音一定很小。"},"anthropology":{"segments":"anthrop- · 人类 + -logy · 学问","origin":"希腊语 anthrōpos 指人。","note":"anthropology 是人类学，不等于 sociology（社会学）。"},"thermometer":{"segments":"thermo- · 热 + -meter · 测量","origin":"由希腊语 thermos（热）与 metron（度量）构成。","note":"thermometer 测温；barometer 测气压。"},"democracy":{"segments":"demo- · 人民 + -cracy · 统治","origin":"希腊语 dēmos 指人民，kratos 表示力量或统治。","note":"democratic 是形容词；demography 是人口统计。"},"sympathy":{"segments":"sym-/syn- · 共同 + path- · 感受","origin":"希腊语 sympatheia 原指共同感受。","note":"empathy 通常强调设身处地理解感受，两者用法不同。"},"apathy":{"segments":"a- · 没有 + path- · 感受","origin":"源自希腊语 apatheia，现代指漠不关心、缺乏兴趣。","note":"apathy 与 antipathy（反感）意义不同。"},"philosophy":{"segments":"philo- · 爱 + sophia · 智慧","origin":"由希腊语 philo-（喜爱）与 sophia（智慧）构成。","note":"philanthropy 则是 philo-（爱）与 anthrop-（人）。"},"submarine":{"segments":"sub- · 下 + marine · 海","origin":"sub- 与表示海的 marine 结合，指海底的或潜艇。","note":"subterranean 以 terr-（地）表示地下。"},"interconnect":{"segments":"inter- · 相互、之间 + connect · 连接","origin":"前缀 inter- 表示互相或在两者之间。","note":"interconnect 强调相互连接，不只是 connect 的拼写变体。"},"autonomy":{"segments":"auto- · 自己 + nomos · 法律","origin":"希腊语 autonomos 表示自己制定法律，后为自主。","note":"autonomous 是自主的，automatic 不等于自主决策。"},"autobiography":{"segments":"auto- · 自己 + bio- · 生命 + -graphy","origin":"字面是记录自己的生命经历。","note":"biography 写他人传记；autobiography 是自传。"},"audible":{"segments":"aud- · 听 + -ible · 能够","origin":"来自拉丁语 audibilis，即可以听见的。","note":"auditory 指听觉的；audience 原本与听有关。"},"manufacture":{"segments":"manu- · 手 + fact- · 制作","origin":"拉丁语 manu factus 原指手工制作。","note":"现代 manufacture 指制造，不一定是手工。"},"rupture":{"segments":"rupt- · 破裂 + -ure · 状态、结果","origin":"来自拉丁语 rumpere（打破）。","note":"rupture 与 erupt、disrupt、interrupt 属于同源词族。"},"inflammable":{"segments":"in- · 使……进入状态 + flamm- · 火焰","origin":"源自拉丁语 inflammare，意为点燃；这里的 in- 不是否定前缀。","note":"inflammable 与 flammable 都表示容易燃烧，并非相反。"},"invaluable":{"segments":"in- · 不 + valu- · 价值 + -able","origin":"从字面上指“无法估价的”，现代通常形容极为宝贵。","note":"invaluable 不是“没有价值”；valueless 才是无价值的。"}};

