const SEMANTIC_BY_ID = new Map();
const SEMANTIC_BY_WORD = new Map();
let semanticActive = '', semanticSearch = '';
for (const cat of SEMANTIC_DATA) {
  for (const group of cat.groups) {
    group.category = cat.id; group.categoryName = cat.name;
    group.words = [...new Set(group.words.filter(word => lookup.has(word)))];
    if (!group.words.length) continue;
    SEMANTIC_BY_ID.set(group.id,group);
    for (const word of group.words) {
      if (!SEMANTIC_BY_WORD.has(word)) SEMANTIC_BY_WORD.set(word, []);
      SEMANTIC_BY_WORD.get(word).push(group);
    }
  }
}
function semanticPanel(w) {
  const gs=SEMANTIC_BY_WORD.get(w.word)||[];
  if (!gs.length) return atlasPanel(w);
  const cards=gs.slice(0,4).map(g=>{
    const related=g.words.filter(x=>x!==w.word).slice(0,8);
    return `<div class="sem-inline-group"><button type="button" class="sem-link-head" data-sem-open="${escapeHTML(g.id)}"><span>${escapeHTML(g.name)}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></button><div class="sem-inline-words">${related.map(x=>`<button type="button" data-related-word="${escapeHTML(x)}">${escapeHTML(x)}</button>`).join('')}</div></div>`;
  }).join('');
  return `<section class="semantic-context"><div class="minor-title">语义关联 · Meaning networks</div>${cards}<p class="semantic-caution">同一主题中的词未必能在所有语境中互换。相近、相反和专题关联已区分标注。</p></section>`+atlasPanel(w);
}
function renderSemantic() {
  const q=$('semantic-search').value.trim().toLowerCase();
  const catChoice=$('semantic-category').value;
  const typeChoice=$('semantic-type').value;
  const arr=[...SEMANTIC_BY_ID.values()].filter(g=>(catChoice==='all'||g.category===catChoice)&&(typeChoice==='all'||g.type===typeChoice)&&(!q||(`${g.name} ${g.english} ${g.categoryName} ${g.words.join(' ')}`).toLowerCase().includes(q)));
  $('semantic-count').textContent=`${fmt(SEMANTIC_BY_ID.size)} 个语义组 · ${fmt(SEMANTIC_BY_WORD.size)} 个关联词`;
  $('semantic-index').innerHTML=arr.length?arr.map(g=>{
    const ex=g.words.slice(0,5).join(' · ');
    const label=g.type==='contrast'?'对照词':g.type==='similar'?'近义聚合':'专题关联';
    return `<button type="button" class="semantic-tile" data-sem-open="${escapeHTML(g.id)}"><span class="sem-tile-kicker"><span>${escapeHTML(g.categoryName)}</span><span>${label}</span></span><span class="sem-tile-title">${escapeHTML(g.name)}</span><span class="sem-tile-en">${escapeHTML(g.english)}</span><span class="sem-tile-words">${escapeHTML(ex)}</span><span class="sem-tile-bottom">${g.words.length} 个词 <svg class="lex-ico" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 17 17 7m-8 0h8v8"/></svg></span></button>`;
  }).join(''):'<div class="root-empty">没有找到匹配的语义组。</div>';
  $('semantic-index').classList.toggle('hidden',!!semanticActive);
  $('semantic-detail').classList.toggle('hidden',!semanticActive);
  if(semanticActive) renderSemanticDetail();
}
function renderSemanticDetail() {
  const g=SEMANTIC_BY_ID.get(semanticActive);if(!g)return;
  $('semantic-detail-title').textContent=g.name;
  $('semantic-detail-en').textContent=g.english+' · '+g.categoryName;
  $('semantic-detail-type').textContent=g.type==='contrast'?'对照关系':g.type==='similar'?'意义相近':'专题关联';
  $('semantic-detail-count').textContent=`${g.words.length} 个收录词条`;
  $('semantic-members').innerHTML=g.words.slice().sort((a,b)=>(lookup.get(a).frequencyOrder||999999)-(lookup.get(b).frequencyOrder||999999)).map(x=>{
    const w=lookup.get(x);
    const meaning=(w.zhBrief||w.zh||w.definition||'').split('\n')[0].slice(0,75);
    return `<button type="button" class="semantic-member" data-related-word="${escapeHTML(x)}"><span class="sem-word-en">${escapeHTML(x)}</span><span class="sem-word-zh">${escapeHTML(meaning)}</span><span class="sem-word-arrow" aria-hidden="true"><svg class="lex-ico" viewBox="0 0 24 24"><path d="M7 17 17 7m-8 0h8v8"/></svg></span></button>`;
  }).join('');
}
function openSemantic(id) {
  if (!SEMANTIC_BY_ID.has(id))return;
  semanticActive=id;navigate('semantics');renderSemantic();
  $('semantics-page').scrollIntoView({behavior:'smooth',block:'start'});
}
function installSemantic() {
  const catSel=$('semantic-category');
  for(const c of SEMANTIC_DATA){
    const opt=document.createElement('option');opt.value=c.id;opt.textContent=c.name;catSel.append(opt);
  }
  $('semantic-search').addEventListener('input',()=>{semanticActive='';renderSemantic()});
  catSel.addEventListener('change',()=>{semanticActive='';renderSemantic()});
  $('semantic-type').addEventListener('change',()=>{semanticActive='';renderSemantic()});
  $('semantic-index').addEventListener('click',e=>{const b=e.target.closest('[data-sem-open]');if(b)openSemantic(b.dataset.semOpen)});
  $('semantic-members').addEventListener('click',e=>{const b=e.target.closest('[data-related-word]');if(b)openLinkedWord(b.dataset.relatedWord)});
  $('semantic-close').addEventListener('click',()=>{semanticActive='';renderSemantic()});
  $('entries').addEventListener('click',e=>{const atlas=e.target.closest('[data-atlas-open]');if(atlas){e.preventDefault();e.stopPropagation();openAtlasTopic(atlas.dataset.atlasOpen);return}const b=e.target.closest('[data-sem-open]');if(b){e.preventDefault();e.stopPropagation();openSemantic(b.dataset.semOpen)}},true);
}


