Object.assign(MORPH_CASES,{"circumspect":{"segments":"circum- · 周围 + spect- · 看","origin":"拉丁语 circumspectus，原义可理解为“四下观察”；引申为谨慎周到。","note":"同源词 spectator、inspect 各有不同的现代词义。"},"philanthropy":{"segments":"phil- · 爱 + anthrop- · 人类","origin":"希腊语 philanthrōpia，原义为对人类的爱。","note":"philanthropist 指慈善家；并非所有 charitable 活动都叫 philanthropy。"},"misanthrope":{"segments":"mis- · 厌恶 + anthrop- · 人","origin":"希腊语 misanthrōpos，意为厌恶人类的人。","note":"与 philanthropy 在“人”的词根上有关，态度相反。"},"anthropology":{"segments":"anthrop- · 人类 + -logy · 研究","origin":"经希腊语 anthrōpos（人）与 -logia（研究）构成。","note":"是研究人类及其文化、社会、生物发展的学科。"},"geology":{"segments":"geo- · 地球 + -logy · 研究","origin":"由希腊语 gē（地球）与 -logia（研究）形成。","note":"geography 的 graph- 是描述、记录，与 -logy 不同。"},"chronology":{"segments":"chron- · 时间 + -logy · 研究","origin":"源自希腊语 chronos（时间），表示按时间顺序组织事件。","note":"chronological order 是按年代顺序，非逻辑因果顺序。"},"anachronism":{"segments":"ana- · 错置／向后 + chron- · 时间","origin":"源自希腊语含时间位置错误之意的构词。","note":"指时代错置，不仅是“过时”。"},"microscope":{"segments":"micro- · 小 + -scope · 看","origin":"由希腊语 mikros（小）和 skopein（观察）构成。","note":"与 telescope 在观察仪器的构词上形成对照。"},"telescope":{"segments":"tele- · 远 + -scope · 看","origin":"由希腊语 tēle（远）和 skopein（观察）构成。","note":"tele- 还见于 telephone、television。"},"euphemism":{"segments":"eu- · 好、委婉 + phem- · 说话","origin":"来自希腊语 euphēmismos，原义与说吉利话有关。","note":"euphemism 是委婉语，不必是谎言。"},"cacophony":{"segments":"caco- · 难听、坏 + -phony · 声音","origin":"由希腊语 kakos（坏）和 phōnē（声音）形成。","note":"与 euphony（悦耳）语义相反。"},"euphony":{"segments":"eu- · 好 + -phony · 声音","origin":"希腊语 eu（好）和 phōnē（声音）的结合。","note":"指悦耳的声音或语言音韵。"},"synonym":{"segments":"syn- · 一起 + -onym · 名称","origin":"由希腊语 syn（共同）与 onyma（名字）组成。","note":"同义词并不保证所有语境可互换。"},"antonym":{"segments":"anti- · 相反 + -onym · 名称","origin":"anti-（相反）与 -onym（名字）构成。","note":"反义关系通常依赖具体义项。"},"pseudonym":{"segments":"pseudo- · 假 + -onym · 名称","origin":"由希腊语 pseudēs（假的）与 onyma（名字）构成。","note":"pseudonym 是笔名、化名，不一定意味着欺诈。"},"homonym":{"segments":"homo- · 相同 + -onym · 名称","origin":"由希腊语 homos（相同）与 onyma（名字）构成。","note":"同形／同音词与同义词是不同概念。"},"ambivalent":{"segments":"ambi- · 两边 + valent- · 强、有力量","origin":"来自拉丁语 ambi-（两边）与 valentia（力量、价值）相关构词。","note":"指对同一事物同时具有相反的感受，不等于漠不关心。"},"magnanimous":{"segments":"magn- · 大 + anim- · 心灵","origin":"来自拉丁语 magnus（大）与 animus（心灵、精神）。","note":"现代常指宽宏大量，而非身体巨大。"},"unanimous":{"segments":"uni- · 一 + anim- · 心意","origin":"来自拉丁语 ūnus（一）与 animus（心意）。","note":"unanimous decision 是全体一致通过的决定。"},"monologue":{"segments":"mono- · 单独 + -logue · 说话","origin":"来自希腊语 monos（单一）与 logos（言说）。","note":"dialogue 是对话，与 monologue 对照。"},"dialogue":{"segments":"dia- · 通过、彼此 + -logue · 言说","origin":"源自希腊语 dialogos，指通过交谈展开意义。","note":"dia- 不是 di-（二）的同义词；dialogue 不限于两人。"},"autonomy":{"segments":"auto- · 自我 + -nomy · 法则","origin":"来自希腊语 autos（自己）与 nomos（法律、规则）。","note":"强调自己治理或作决定；automate 则指自动化。"},"heterogeneous":{"segments":"hetero- · 不同 + -gen- · 种类","origin":"来自希腊语 heteros（不同）与 genos（种类、血统）。","note":"与 homogeneous（同质的）相对，常用于统计与材料科学。"},"homogeneous":{"segments":"homo- · 相同 + -gen- · 种类","origin":"由希腊语 homos（相同）与 genos（种类）构成。","note":"不表示“没有任何差别”，而是某种性质上相对均一。"},"hypothesis":{"segments":"hypo- · 在下 + thesis · 放置、命题","origin":"经希腊语 hypothesis，原义与置于其下的基础或前提有关。","note":"现代科学语境指可以检验的解释性设想。"},"synthesis":{"segments":"syn- · 一起 + thesis · 放置","origin":"源自希腊语 synthesis，意为放在一起、组合。","note":"analysis 强调拆解；synthesis 强调整合。"},"antithesis":{"segments":"anti- · 反对 + thesis · 命题","origin":"源自希腊语 antithesis，表示对置、反题。","note":"在修辞中还可指对照的句式结构。"},"photosynthesis":{"segments":"photo- · 光 + synthesis · 合成","origin":"photo- 源自希腊语 phōs（光），与 synthesis（组合）构成。","note":"植物利用光能合成有机物的过程，别和 photography 混同。"},"obviate":{"segments":"ob- · 在前／阻挡 + via · 道路","origin":"拉丁语 obviāre 指拦在路上、预先应对，后形成“使问题不再必要”的含义。","note":"obviate the need for 是重要搭配，不等于简单 avoid。"},"pathology":{"segments":"path- · 疾病、痛苦 + -logy · 研究","origin":"源自希腊语 pathos（遭受、疾病）与 -logia（研究）。","note":"医学中指病理学；pathological 在别的语境也有引申义。"},"psychology":{"segments":"psych- · 心智、灵魂 + -logy · 研究","origin":"源自希腊语 psychē（心灵）与 -logia（研究）。","note":"psychological 强调心理，physiological 强调生理。"},"biology":{"segments":"bio- · 生命 + -logy · 研究","origin":"由希腊语 bios（生命）与 -logia（研究）形成。","note":"bio- 是生物相关构词成分，不意味着所有 b-i-o 拼写都同源。"}});

