Object.assign(MORPH_CASES,{"circumspect":{"segments":"circum- · 周围 + specere · 看","origin":"来自拉丁语 circumspectus，原义是向四周仔细观察。","note":"语义引申为“谨慎考虑周围风险”；与 inspect 有同源部分。"},"converge":{"segments":"con- · 一起 + vergere · 倾斜、转向","origin":"来自拉丁语 convergere，原义是倾向同一点。","note":"既可指路线汇聚，也可指意见、结果趋于一致。"},"diverge":{"segments":"di- · 分开 + vergere · 转向","origin":"来自拉丁语 divergere，意为向不同方向分开。","note":"是 converge 的常见反义词；统计中可指估计不再收敛。"},"adhere":{"segments":"ad- · 向着 + haerere · 黏附","origin":"源自拉丁语 adhaerere，意为贴在、附着于。","note":"adhere to 也表示遵守规则、坚持原则。"},"coherent":{"segments":"co- · 一起 + haerere · 贴合","origin":"来自拉丁语 cohaerere，原义为粘合、结合在一起。","note":"现代可指论证逻辑连贯；与 cohesive 有关联但不完全同义。"},"inherent":{"segments":"in- · 内在 + haerere · 附着","origin":"经拉丁语 inhaerere，原义指内在附着。","note":"inherent in 表示某性质为事物固有，而非外加。"},"include":{"segments":"in- · 在内 + claudere · 关闭","origin":"源自拉丁语 includere，原义是关在里面。","note":"包括某项内容，注意 include 不保证清单穷尽。"},"exclude":{"segments":"ex- · 向外 + claudere · 关闭","origin":"来自拉丁语 excludere，原义为把某物关在外面。","note":"exclude from 是“排除在……之外”。"},"conclude":{"segments":"con- · 完全 + claudere · 关闭","origin":"经拉丁语 concludere，意为关闭、结束、作出结论。","note":"conclude that 表示得出结论；与 summary（总结）不完全相同。"},"preclude":{"segments":"pre- · 预先 + claudere · 关闭","origin":"来自拉丁语 praecludere，表示预先堵住、阻止。","note":"preclude doing/from doing 需按句法辨析；语义比 hinder 强。"},"diffuse":{"segments":"dis- · 分开 + fundere · 倾倒","origin":"源自拉丁语 diffundere，意为向各处倾倒、散布。","note":"既可指扩散，也可形容文字或光线不集中。"},"profuse":{"segments":"pro- · 向前 + fundere · 倾倒","origin":"源自拉丁语 profusus（倾泻出来的）。","note":"profuse praise / apologies 指大量甚至过度的赞美或道歉。"},"suffuse":{"segments":"sub- · 从下 + fundere · 倾倒","origin":"源于拉丁语 suffundere，意为从下面倾倒、遍布。","note":"常见 be suffused with light/color/feeling。"},"invert":{"segments":"in- · 倒转 + vertere · 转动","origin":"来自拉丁语 invertere，原义是翻转。","note":"可指倒置顺序或数学运算中的反演。"},"reverse":{"segments":"re- · 向后 + vertere · 转动","origin":"由拉丁语 reversus 相关词形演变而来，原义转回去。","note":"reverse 既可作动词，也可作形容词和名词。"},"convert":{"segments":"con- · 完全 + vertere · 转变","origin":"来自拉丁语 convertere，意为转过去、改变。","note":"convert A into B；与 transform 语义有重叠。"},"subvert":{"segments":"sub- · 从下 + vertere · 转动","origin":"源于拉丁语 subvertere，原义从下面翻倒。","note":"现代常指破坏制度、权威或既有秩序。"},"evolve":{"segments":"e- · 向外 + volvere · 滚动、展开","origin":"来自拉丁语 evolvere，原义为展开、解开卷轴。","note":"科学语境指逐步变化；不自动表示“进步”。"},"revolve":{"segments":"re- · 回转 + volvere · 滚动","origin":"来自拉丁语 revolvere，表示滚动、转回。","note":"revolve around 可表示围绕中心运行或以某事为核心。"},"involve":{"segments":"in- · 向内 + volvere · 卷入","origin":"来自拉丁语 involvere，原义是卷入、包住。","note":"involve doing something，而非 involve to do。"},"circumscribe":{"segments":"circum- · 周围 + scribere · 写","origin":"拉丁语 circumscribere 原义是在周围画线、界定。","note":"现代常指限制活动范围或权力。"},"prescribe":{"segments":"pre- · 预先 + scribere · 写","origin":"来自拉丁语 praescribere，意为预先写下、规定。","note":"医生 prescribe medicine；法规 prescribe rules。"},"describe":{"segments":"de- · 写下 + scribere · 写","origin":"来自拉丁语 describere，原义为写下、描绘。","note":"describe what/how；不要把它与 prescribe 混淆。"},"transcribe":{"segments":"trans- · 转换 + scribere · 写","origin":"经拉丁语 transcribere，指转写、抄录。","note":"可指把录音转成文字；translate 才是翻译意义。"},"emit":{"segments":"e- · 向外 + mittere · 发送","origin":"来自拉丁语 emittere，意为发出、送出。","note":"常见 emit light/radiation/sound；不要与 omit 混淆。"},"admit":{"segments":"ad- · 向着 + mittere · 送入","origin":"来自拉丁语 admittere，原义允许进入。","note":"现代可表示承认事实，也表示准许进入。"},"commit":{"segments":"com- · 一起 + mittere · 送出、托付","origin":"来自拉丁语 committere，后演变出托付与犯下行为等义项。","note":"commit a crime 与 commit to a plan 是不同常用义。"},"omit":{"segments":"ob- · 离开 + mittere · 放开","origin":"来自拉丁语 omittere，原义为放开、让其落下。","note":"表示遗漏；不是 emit 的同义词。"},"auditory":{"segments":"audire · 听 + -ory · 相关的","origin":"auditory 通过拉丁语 audire（听）相关词形构成。","note":"auditory memory 为听觉记忆；audio- 为同源构词形式。"},"inaudible":{"segments":"in- · 不 + audible · 听得见的","origin":"由否定前缀 in- 与 audible 组合。","note":"声音太小而听不见，不等于 silent（完全无声）。"},"benevolent":{"segments":"bene- · 好、善 + velle · 希望","origin":"来自拉丁语 benevolentia，含有善意、希望他人好。","note":"通常指人的仁慈或善意。"},"malevolent":{"segments":"male- · 坏、恶 + velle · 希望","origin":"来自拉丁语 malevolentia，意为恶意。","note":"比 unfriendly 更强烈，强调恶意伤害的意图。"},"beneficial":{"segments":"bene- · 好 + facere · 做","origin":"来自拉丁语 beneficium 相关词形，含有做好事、带来好处之义。","note":"beneficial to 表示对……有益。"},"magnify":{"segments":"magn- · 大 + facere · 使成为","origin":"来自拉丁语 magnificare，意为使之大、赞美。","note":"可指放大，也可指夸大问题。"},"metamorphosis":{"segments":"meta- · 改变 + morphē · 形态","origin":"源自希腊语 metamorphōsis，意为形状改变。","note":"既可表示生物变态，也可指彻底转变。"},"philanthropy":{"segments":"phil- · 喜爱 + anthrōpos · 人","origin":"经希腊语 philanthrōpia，原义为爱人类。","note":"现代 philanthropy 常指公益慈善。"},"geology":{"segments":"geo- · 地球 + -logy · 研究","origin":"希腊语 gē（土地、地球）与 -logia（论述、研究）构成。","note":"与 geography（地理描述）关注点有所不同。"},"ecology":{"segments":"oikos · 家、环境 + -logy · 研究","origin":"经德语 Ökologie 造词，源自希腊语 oikos 与 -logia。","note":"研究生物与环境的关系，不等同于“环境保护”本身。"},"latitude":{"segments":"latus · 宽阔 + -tude · 状态","origin":"来源于拉丁语 latitudo（宽度），地理上逐渐专指纬度。","note":"latitude 还可表示自由裁量空间；longitude 是经度。"},"longitude":{"segments":"longus · 长 + -tude · 状态","origin":"来自拉丁语 longitudo（长度），地理上专指经度。","note":"longitude 与 latitude 分别是经度与纬度。"},"consequent":{"segments":"con- · 跟随 + sequi · 跟随","origin":"源于拉丁语 consequens（随之而来的）。","note":"强调结果随前因产生，不等同于 subsequent 的纯时间顺序。"},"subsequent":{"segments":"sub- · 随后 + sequi · 跟随","origin":"来自拉丁语 subsequi，意为在后面跟随。","note":"表示时间上的后续；不必然有因果关系。"},"consequence":{"segments":"con- · 接续 + sequi · 跟随","origin":"来源于拉丁语 consequentia，指随后发生的事。","note":"可以是结果；需留意语境是否特别强调不利后果。"},"prospective":{"segments":"pro- · 向前 + specere · 看","origin":"源自拉丁语 prospicere（向前看）相关词形。","note":"a prospective student 是潜在／未来可能的学生，不是观察前景的人。"},"circumference":{"segments":"circum- · 周围 + ferre · 携带","origin":"来自拉丁语 circumferentia，指周围的边界。","note":"数学中是圆周长，区别于 diameter 直径。"},"retain":{"segments":"re- · 向后 + tenere · 持有","origin":"来自拉丁语 retinere，指保持、抓住。","note":"retain information 是保留信息；retain a lawyer 指聘请律师。"},"detain":{"segments":"de- · 远离 + tenere · 保持","origin":"经拉丁语 detinere，表示扣住、留住。","note":"detain 常用于拘留人或延误离开。"},"tenacious":{"segments":"tenax · 抓紧、坚守 + tenere · 抓住","origin":"来自拉丁语 tenax（执着的、抓得紧）。","note":"既可表示人坚持，也可形容抓握或附着牢固。"},"pertinent":{"segments":"per- · 贯穿 + tenere · 伸展、保持","origin":"经拉丁语 pertinere（延及、与之有关）演变而来。","note":"pertinent to 是切题；不意味着该词和 retain 可直接同义。"}});
