Object.assign(MORPH_CASES,{"distract":{"segments":"dis- · 分开 + trahere · 拉","origin":"来自拉丁语 distrahere，原义向不同方向拉扯。","note":"distract someone from something 表示使其分心；不是 physically extract 的同义词。"},"abstract":{"segments":"ab- · 离开 + trahere · 拉","origin":"来自拉丁语 abstrahere，原义是把某物从另一个事物中拉开。","note":"引申出脱离具体情境的抽象概念；作名词又可指论文摘要。"},"contract":{"segments":"con- · 一起 + trahere · 拉","origin":"来自拉丁语 contrahere，原义拉到一起。","note":"引申出收缩和契约等多个义项；名词和动词可能有不同重音。"},"instruct":{"segments":"in- · 在……上 + struere · 安排、建造","origin":"来自拉丁语 instruere，原义包括准备、布置和装备。","note":"现代主要表示指导、传授或指示；不要机械翻译词根。"},"destroy":{"segments":"de- · 向下、除去 + struere · 建造、堆放","origin":"经古法语及拉丁语 destruere 传入英语，原义为拆散、毁坏。","note":"词源与 construct 有关系，但两词在现代并非简单前缀反义替换。"},"compress":{"segments":"com- · 一起 + premere · 压","origin":"来自拉丁语 comprimere，原义是压在一起。","note":"可用于压缩文件、压缩气体；compression 还指医学按压。"},"express":{"segments":"ex- · 向外 + premere · 压","origin":"来自拉丁语 exprimere，原义是压出、挤出。","note":"现代常用于 express an opinion（表达观点）；表达与压缩并不是反义义项。"},"impress":{"segments":"im- · 向内 + premere · 压","origin":"来自拉丁语 imprimere，原义是压进、留下印记。","note":"现代既可表示使人印象深刻，也可指印刷或留下压痕。"},"suppress":{"segments":"sub- · 在下 + premere · 压","origin":"来自拉丁语 supprimere，原义是向下压制。","note":"suppress a reaction / suppress evidence 等搭配各自涉及抑制或掩盖。"},"depress":{"segments":"de- · 向下 + premere · 压","origin":"来自拉丁语 deprimere，原义向下压。","note":"可表示压低价格、使心情低落；医学领域还有特定含义。"},"precede":{"segments":"prae- · 在前 + cedere · 前进、走","origin":"来自拉丁语 praecedere，意为走在前面。","note":"precede 是及物动词；A precedes B 表示 A 先于 B。"},"proceed":{"segments":"pro- · 向前 + cedere · 行进","origin":"来自拉丁语 procedere，意为向前走。","note":"proceed with a plan 表示继续做；proceed to do 表示接着做。"},"recede":{"segments":"re- · 向后 + cedere · 走","origin":"来自拉丁语 recedere，意为后退。","note":"recede 可指潮水退去、发际线后移或影响力减弱。"},"intercede":{"segments":"inter- · 在……之间 + cedere · 行进","origin":"来自拉丁语 intercedere，后发展为介入、代为求情。","note":"intercede on someone's behalf 常指替某人说情，不能与 precede 混淆。"},"exceed":{"segments":"ex- · 向外、越过 + cedere · 走","origin":"来自拉丁语 excedere，原义走到外面、越过。","note":"exceed the limit 表示超过上限；常见 exceed expectations。"},"access":{"segments":"ad- · 向着 + cedere · 走、到达","origin":"来自拉丁语 accessus 相关词形，含有靠近、进入之义。","note":"现代既可表示取得访问权限，也可指进入渠道。"},"perceive":{"segments":"per- · 彻底 + capere · 取、抓住","origin":"来自拉丁语 percipere，意为领会、察觉。","note":"perceive a pattern 表示察觉模式；perception 是感知或认知。"},"conceive":{"segments":"con- · 一起 + capere · 取","origin":"来自拉丁语 concipere，后发展出形成想法、设想及怀孕等含义。","note":"conceive of a solution 常指构想方案；也有生育意义。"},"deceive":{"segments":"de- · 离开、误导 + capere · 取","origin":"经古法语及拉丁语 decipere 演变而来，意为欺骗、诱使犯错。","note":"deceive somebody into doing something 表示骗某人做某事。"},"receive":{"segments":"re- · 向回、接收 + capere · 取","origin":"源自拉丁语 recipere，意为拿回、接收。","note":"receive a message / receive payment；不应误将 perceive 视为 receive 的近义词。"},"contribute":{"segments":"con- · 一起 + tribuere · 分配、给予","origin":"来自拉丁语 contribuere，字面上有共同给予、贡献的意思。","note":"contribute to an outcome 强调促成因素，不自动意味着唯一原因。"},"attribute":{"segments":"ad- · 向着 + tribuere · 给予、分配","origin":"来自拉丁语 attribuere，原义是归给、分配给。","note":"attribute A to B 是把 A 归因或归属于 B；需要区分 association 和 causation。"},"distribute":{"segments":"dis- · 分开 + tribuere · 分配、给予","origin":"来自拉丁语 distribuere，表示分配、分散给各部分。","note":"distribute resources 比 aggregate resources 更强调向多个对象分配。"},"intervene":{"segments":"inter- · 在……之间 + venire · 来","origin":"源自拉丁语 intervenire，意为来到中间。","note":"intervene in a conflict 指介入冲突；医学上可指干预治疗。"},"convene":{"segments":"con- · 一起 + venire · 来","origin":"来自拉丁语 convenire，有聚集、会合之义。","note":"The committee convened 表示委员会开会；convene a meeting 表示召集会议。"},"prevent":{"segments":"prae- · 在前 + venire · 来","origin":"来自拉丁语 praevenire，原义是抢先来到、预先采取行动。","note":"现代 prevent harm 表示防止危害；词源不会改变现代动词搭配。"},"disseminate":{"segments":"dis- · 分开 + semen · 种子","origin":"来自拉丁语 disseminare，原义是撒播种子。","note":"现代尤其常表示 disseminate information（传播信息）；不等于随机散落。"}});
function etymologyPanel(w){
 const groups=rootsByWord.get(w.word)||[];
 const originalHint=w.etyHint||'';
 // The source dictionary often repeats the same etymology in its main explanation.
 const hint=originalHint&&(w.explain||'').includes(originalHint)?'':originalHint;
 const families=[...groups].sort((a,b)=>(rootKind(a)==='root'?0:rootKind(a)==='prefix'?1:2)-(rootKind(b)==='root'?0:rootKind(b)==='prefix'?1:2)).slice(0,5).map(r=>{
  const related=r.words.filter(x=>x!==w.word&&lookup.has(x)).sort((a,b)=>(lookup.get(a).frequencyOrder||1e9)-(lookup.get(b).frequencyOrder||1e9)).slice(0,8);
  return `<div class="etym-family"><div class="etym-root"><button type="button" class="root-link etym-root-mark" data-open-root="${escapeHTML(r.id)}" title="查看 ${escapeHTML(r.id)} 的所有同根词">${escapeHTML(r.id)}</button><span><strong>${escapeHTML(r.label)}</strong><small>${escapeHTML(r.meaning)}</small></span></div>${related.length?`<div class="related-words">${related.map(x=>`<button type="button" data-related-word="${escapeHTML(x)}" title="浏览 ${escapeHTML(x)}"><span>${escapeHTML(x)}</span><small>${escapeHTML((lookup.get(x).zhBrief||lookup.get(x).zh||'').split('\n')[0].slice(0,38))}</small></button>`).join('')}</div>`:''}</div>`}).join('');
 const c=MORPH_CASES[w.word];
 const caseDetail=c?`<div class="morph-study"><div class="morph-study-head">词形拆解 · MORPHOLOGY</div><div class="morph-study-parts">${c.segments.split(' + ').map(part=>`<span>${escapeHTML(part)}</span>`).join('<b>+</b>')}</div><p>${escapeHTML(c.origin)}</p><div class="morph-study-tip"><strong>词义与用法</strong>${escapeHTML(c.note)}</div></div>`:'';
 if(!hint&&!families&&!caseDetail)return '';
 return `<section class="etym-panel"><div class="minor-title etym-panel-title">词源与词族 <span>ORIGINS & CONNECTIONS</span></div>${caseDetail}${hint?(c?`<details class="etym-source-details"><summary>词典中的补充词源说明</summary><p class="etym-note">${escapeHTML(hint)}</p></details>`:`<p class="etym-note">${escapeHTML(hint)}</p>`):''}${families||''}${!hint&&!families?`<p class="etym-empty">暂无已核对的离线词源。</p>`:''}<a class="etym-more" href="https://en.wiktionary.org/wiki/${encodeURIComponent(w.word)}" target="_blank" rel="noopener noreferrer">查看更完整的词源资料 <svg class="lex-ico" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 17 17 7m-8 0h8v8"/></svg></a></section>`;
}


