const derivationsByWord=new Map();
for(const [id,arr] of Object.entries(DERIVATION_GROUPS)) {
 const found=[...new Set(arr)].filter(x=>lookup.has(x));
 if(found.length<2)continue;
 for(const word of found) {
  const previous=derivationsByWord.get(word)||[];
  previous.push({id,words:found});
  derivationsByWord.set(word,previous);
 }
}
const contrastsByWord=new Map();
for(const p of EXTENDED_CONTRASTS){
 if(!lookup.has(p.a)||!lookup.has(p.b))continue;
 for(const word of [p.a,p.b]){
  const earlier=contrastsByWord.get(word)||[];
  if(!earlier.some(x=>x.a===p.a&&x.b===p.b))earlier.push(p);
  contrastsByWord.set(word,earlier);
 }
}
function precisionPanel(w){
 const u=USAGE_NOTES[w.word];
 const forms=(derivationsByWord.get(w.word)||[]).slice(0,2);
 const contrasts=LEX40_CONTRASTS[w.word]?.length?[]:(contrastsByWord.get(w.word)||[]).slice(0,3);
 if(!u&&!forms.length&&!contrasts.length)return '';
 const usage=u?`<div class="precision-usage">
 ${showZh&&u[0]!==u[1]?.[0]?.[1]?`<p class="precision-lead">${escapeHTML(u[0])}</p>`:''}
 <div class="precision-label">Useful patterns · 常用搭配</div>
 <div class="precision-patterns">${u[1].map(p=>`<div class="precision-pattern"><strong>${escapeHTML(p[0])}</strong>${showZh?`<span>${escapeHTML(p[1])}</span>`:''}</div>`).join('')}</div>
 <blockquote lang="en" class="precision-example">${escapeHTML(u[2])}</blockquote>
 ${showZh&&u[4]?`<p class="lex42-usage-translation" lang="zh-CN">${escapeHTML(u[4])}</p>`:''}${showZh&&u[3]?`<p class="precision-caution"><strong>使用提示</strong> ${escapeHTML(u[3])}</p>`:''}
 </div>`:'';
 const formSection=forms.map(g=>`<div class="precision-deriv-group"><div class="precision-label">Word family · 同源与派生</div><div class="precision-links">${g.words.map(word=>word===w.word?`<span class="precision-current">${escapeHTML(word)}</span>`:`<button type="button" data-related-word="${escapeHTML(word)}">${escapeHTML(word)}</button>`).join('')}</div></div>`).join('');
 const contrastSection=contrasts.length?`<div class="precision-contrasts"><div class="precision-label">Frequently confused · 易混淆词</div>${contrasts.map(c=>{let other=c.a===w.word?c.b:c.a;return `<div class="precision-contrast"><button type="button" data-related-word="${escapeHTML(other)}">${escapeHTML(other)} <svg class="lex-ico" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 17 17 7m-8 0h8v8"/></svg></button>${showZh?`<p>${escapeHTML(c.note)}</p>`:''}<div class="precision-contrast-examples" lang="en"><span>${escapeHTML(c.exampleA)}</span><span>${escapeHTML(c.exampleB)}</span></div></div>`}).join('')}</div>`:'';
 return `<section class="precision-panel"><div class="minor-title">精准用法与关联 <span>USAGE & CONNECTIONS</span></div>${usage}${formSection}${contrastSection}</section>`;
}


