Object.assign(V30_USAGE_EXAMPLES,{"admonish":["admonish someone for doing something","因某种行为郑重告诫某人","The editor admonished the team for ignoring the evidence.","编辑严肃批评团队忽视证据的做法。"],"acquiesce":["acquiesce in a decision","默许某项决定","She disagreed with the policy but eventually acquiesced in the decision.","她不同意这项政策，但最终默许了这一决定。"],"accrue":["benefits accrue over time","收益逐渐积累","Small improvements accrue over time.","微小的改进会随着时间逐渐累积。"],"adduce":["adduce evidence","举出证据","The report adduces several independent measurements.","报告举出了几项独立测量作为证据。"],"admittedly":["admittedly ..., but ...","固然……，但……","Admittedly, the sample is small, but the trend is consistent.","诚然，样本较小，但趋势是一致的。"],"affiliation":["institutional affiliation","机构隶属关系","Please indicate your institutional affiliation on the form.","请在表格中填写所属机构。"],"allay":["allay concerns","消除或缓解担忧","The additional tests helped allay concerns about the result.","补充测试有助于缓解对结果的担忧。"],"amenable":["be amenable to suggestions","愿意接受建议","The proposal is still amenable to revision.","这项提案仍可修改。"],"anachronism":["a historical anachronism","时代错置","The modern device is an anachronism in the period drama.","这台现代设备出现在古装剧里显得时代错置。"],"apprise":["apprise someone of developments","将进展告知某人","We will apprise the team of any changes.","如有变化，我们会及时告知团队。"],"arbitrate":["arbitrate a dispute","仲裁争议","An independent panel will arbitrate the dispute.","独立委员会将对这一争议进行仲裁。"],"ascribe":["ascribe an effect to a cause","将结果归因于某个原因","We cannot ascribe the difference to temperature alone.","我们不能仅把这一差异归因于温度。"],"assiduous":["assiduous research","勤勉细致的研究","Her assiduous research uncovered the missing reference.","她细致勤勉的研究找到了缺失的参考文献。"],"assuage":["assuage fears","缓解恐惧或忧虑","The explanation did little to assuage their fears.","这一解释几乎未能缓解他们的担忧。"],"astute":["an astute observation","敏锐的观察","His astute observation exposed a flaw in the argument.","他的敏锐观察揭示了论证中的缺陷。"],"attenuate":["attenuate a signal","衰减信号","A long cable can attenuate the signal.","长电缆可能使信号衰减。"],"awry":["go awry","出岔子；偏离预期","The plan went awry when the data failed to load.","数据无法加载，使计划出了岔子。"],"baffle":["be baffled by something","对某事感到困惑","The unexpected result baffled the researchers.","意外的结果令研究人员困惑不解。"],"belie":["belie an apparent simplicity","与表面上的简单相矛盾","The apparent simplicity belies a complex process.","表面上的简单掩盖了复杂的过程。"],"blatant":["a blatant contradiction","明显而难以接受的矛盾","The two statements contain a blatant contradiction.","这两种说法之间存在明显的矛盾。"],"blunder":["a costly blunder","代价高昂的严重失误","Skipping the final check proved to be a costly blunder.","跳过最终检查被证明是代价高昂的严重失误。"],"affinity":["have an affinity for","对……有天然亲近感或喜好","She has an affinity for languages and literature.","她对语言和文学有天然的兴趣。"],"actuate":["actuate a switch","驱动开关","The controller actuates the switch at the programmed time.","控制器在预定时刻驱动开关。"],"bankruptcy":["file for bankruptcy","申请破产","The company filed for bankruptcy after prolonged losses.","公司在长期亏损后申请了破产。"],"aperture":["adjust the aperture","调整光圈开口","A smaller aperture allows less light to reach the sensor.","较小的光圈让到达传感器的光线更少。"],"adroit":["adroit handling of a problem","巧妙处理问题","Her adroit handling of the dispute avoided further delays.","她巧妙地处理争议，避免了进一步延误。"],"aloof":["remain aloof from","与……保持距离","The committee remained aloof from the political debate.","委员会与政治争论保持了距离。"],"append":["append a note to the report","在报告末尾附加说明","Please append the calibration record to the report.","请在报告后附上校准记录。"],"balancing":["balance competing priorities","平衡相互竞争的优先事项","The team is balancing speed against accuracy.","团队正在权衡速度与准确性。"]});
Object.assign(V30_USAGE_EXAMPLES,{"anomalous":["an anomalous observation","异常观测值","The anomalous observation warrants further checks, not automatic deletion.","这一异常观测值需要进一步检查，而不能直接删除。"],"clock":["a stable clock reference","稳定的时钟参考","The two devices use the same stable clock reference.","两个设备使用同一稳定的时钟参考。"],"confounded":["be confounded by","受到……的混杂影响","The apparent improvement may be confounded by temperature changes.","表面上的改进可能受到温度变化的混杂影响。"],"correction":["apply a correction","应用修正","We applied a correction for the measured offset.","我们针对测得的偏移量进行了修正。"],"credulous":["be credulous about","轻信……","A careful reader should not be credulous about unsupported claims.","谨慎的读者不应轻信缺乏证据的说法。"],"divergence":["a divergence between results","结果之间的分歧","The divergence between the two results needs an explanation.","这两个结果之间的差异需要解释。"],"fidelity":["signal fidelity","信号保真度","The new cable preserved signal fidelity over a longer distance.","新电缆在更长距离下保持了信号保真度。"],"inconsistency":["an inconsistency in the report","报告中的不一致","We found an inconsistency between the table and the main text.","我们发现表格与正文之间有一处不一致。"],"latent":["a latent problem","潜在问题","The change exposed a latent problem in the design.","这次改动暴露了设计中的潜在问题。"],"odds":["the odds of success","成功的胜算","The odds of success are not the same as the probability of success.","成功的赔率式胜算并不等同于成功的概率。"],"permissible":["within permissible limits","在允许的范围内","The measurement is within permissible limits.","测量结果处于允许的范围内。"],"predictive":["predictive performance","预测性能","We evaluated predictive performance on unseen data.","我们用未见过的数据评估预测性能。"],"presumption":["a presumption of innocence","无罪推定","The legal system recognizes the presumption of innocence.","法律制度承认无罪推定原则。"],"recurrence":["the recurrence of an error","错误再次出现","The recurrence of the error suggests a systematic cause.","错误再次出现，表明可能存在系统性原因。"],"statistical":["statistical significance","统计显著性","Statistical significance alone does not establish practical importance.","统计显著性本身并不意味着具有实际重要性。"],"surreptitious":["a surreptitious recording","秘密录制","The conversation was captured in a surreptitious recording.","这段谈话被秘密录制了下来。"],"gradient":["a temperature gradient","温度梯度","A temperature gradient can produce a spatial variation in the response.","温度梯度可能使响应随空间位置变化。"],"predictable":["a predictable pattern","可预测的模式","The repeated failures followed a predictable pattern.","这些反复发生的故障遵循可预测的模式。"],"qualified":["a qualified conclusion","附带条件的结论","The evidence supports only a qualified conclusion.","这些证据只能支持一个附带限定条件的结论。"],"underestimate":["underestimate the uncertainty","低估不确定性","Ignoring correlations can underestimate the uncertainty.","忽略相关性可能低估不确定性。"]});
Object.assign(V30_USAGE_EXAMPLES,{"acquire":["acquire a skill","掌握一项技能","It takes time to acquire a new skill.","掌握一项新技能需要时间。"],"adherence":["adherence to a protocol","遵守操作规程","Adherence to the protocol helps reduce avoidable errors.","遵守操作规程有助于减少可避免的错误。"],"advisory":["issue an advisory","发布提示或警示","The agency issued an advisory about the severe weather.","该机构发布了一则恶劣天气警示。"],"alien":["an alien concept","陌生的概念","The concept was initially alien to most students.","这个概念起初对大多数学生都很陌生。"],"angle":["approach from a different angle","从不同角度切入","Let's approach the problem from a different angle.","我们换个角度分析这个问题。"],"array":["an array of sensors","一组传感器","The device contains an array of temperature sensors.","该设备包含一组温度传感器。"],"assistance":["request assistance","请求协助","Please request assistance if the procedure is unclear.","如果操作程序不清楚，请寻求协助。"],"basic":["a basic assumption","基本假设","The argument rests on a basic assumption.","这个论证建立在一个基本假设之上。"],"blast":["a blast of cold air","一阵冷风","A blast of cold air came through the open door.","一阵冷风从敞开的门吹进来。"],"bone":["bone density","骨密度","The study measured bone density in adults.","这项研究测量了成年人的骨密度。"],"brace":["brace for impact","做好迎接冲击的准备","The crew braced for impact.","机组人员做好了迎接冲击的准备。"],"cable":["a shielded cable","屏蔽电缆","We used a shielded cable to limit interference.","我们使用屏蔽电缆来减小干扰。"],"candidate":["a candidate for the position","职位候选人","She is a strong candidate for the position.","她是该职位很有竞争力的候选人。"],"canon":["the literary canon","公认的文学经典","The course questions what belongs in the literary canon.","这门课探讨哪些作品应当被纳入公认的文学经典。"],"chat":["have a quick chat","简单聊一聊","Can we have a quick chat after the meeting?","我们能在会后简单聊一下吗？"],"chip":["a silicon chip","硅芯片","The sensor uses a custom silicon chip.","该传感器使用一颗定制硅芯片。"],"code":["a code of conduct","行为准则","Every participant must follow the code of conduct.","每位参与者都必须遵守行为准则。"],"coil":["a coil of wire","一卷电线","The technician replaced a damaged coil of wire.","技术员更换了一卷受损的电线。"],"crude":["a crude estimate","粗略估计","This is only a crude estimate of the total cost.","这只是对总成本的粗略估计。"],"data":["the available data","现有数据","The available data do not support a causal conclusion.","现有数据不足以支持因果结论。"],"dated":["a dated interface","过时的界面","The software still has a dated interface.","这款软件的界面仍显得过时。"],"departure":["a departure from tradition","背离传统","The new approach is a clear departure from tradition.","新方法明显不同于传统做法。"],"digit":["a three-digit number","三位数","Enter the three-digit number shown on the screen.","输入屏幕上显示的三位数。"],"discrete":["discrete time intervals","离散时间间隔","Samples were collected at discrete time intervals.","样本在离散的时间间隔上采集。"],"distribution":["a skewed distribution","偏斜分布","The measurements follow a highly skewed distribution.","测量值呈明显的偏斜分布。"],"heterogeneous":["a heterogeneous sample","异质样本","The sample is heterogeneous in age and background.","这个样本在年龄和背景方面具有异质性。"],"homogeneous":["a homogeneous mixture","均匀混合物","Stir until the mixture becomes homogeneous.","搅拌至混合物变得均匀。"],"intervene":["intervene early","及早干预","It is better to intervene early than wait for failure.","及早干预比等到故障发生更好。"],"operational":["become operational","开始正式运行","The new system became operational in July.","新系统于七月投入运行。"]});
Object.assign(V30_USAGE_EXAMPLES,{"basis":["on the basis of","根据；以……为依据","The decision was made on the basis of the available evidence.","这项决定是根据现有证据作出的。"],"constituent":["constituent parts","组成部分","The constituent parts must be tested separately before integration.","各组成部分必须在集成前分别测试。"],"deplete":["deplete resources","耗尽资源、消耗储备","Repeated tests depleted the available samples.","反复试验消耗了可用样本。"],"devise":["devise a method","设计一种方法","We devised a method to identify the source of the drift.","我们设计了一种识别漂移来源的方法。"],"endemic":["endemic to a region","为某地区所特有或长期存在","The infection is endemic to parts of the region.","这种感染在该地区的部分地方长期存在。"],"evasive":["give an evasive answer","含糊其词地回答","The spokesperson gave an evasive answer to the question.","发言人对这个问题给出了回避性的回答。"],"expedite":["expedite the process","加快进程","Parallel validation could expedite the approval process.","并行验证可以加快审批进程。"],"imperative":["it is imperative that","……至关重要、迫切必要","It is imperative that the measurements remain reproducible.","确保测量结果可复现至关重要。"],"irreversible":["irreversible damage","不可逆的损害","The reaction may cause irreversible damage to the sensor.","这种反应可能对传感器造成不可逆损害。"],"susceptible":["be susceptible to","易受……影响","The oscillator is susceptible to temperature fluctuations.","振荡器容易受到温度波动的影响。"],"wary":["be wary of","警惕、谨慎对待","Be wary of drawing conclusions from a small sample.","不要轻率地根据小样本得出结论。"],"collateral":["provide collateral","提供抵押品","The borrower provided property as collateral for the loan.","借款人以房产为贷款提供抵押。"],"correspondence":["one-to-one correspondence","一一对应关系","There is no one-to-one correspondence between words and meanings.","单词和词义之间并不存在一一对应关系。"],"contract":["enter into a contract","签订合同","The organization entered into a contract with the supplier.","该机构与供应商签订了合同。"],"faculty":["faculty members","高校教职人员（尤见美式英语）","Faculty members were invited to review the proposal.","教职人员受邀审查该提案。"],"generic":["generic solution","通用解决方案","A generic solution may overlook important local constraints.","通用方案可能忽略重要的局部约束。"],"gravity":["the gravity of the situation","事态的严重性","The report makes clear the gravity of the situation.","报告明确揭示了事态的严重性。"],"instrumental":["be instrumental in","对……发挥关键作用","The prototype was instrumental in identifying the timing issue.","原型装置对发现时间同步问题发挥了关键作用。"],"matrix":["correlation matrix","相关矩阵","The correlation matrix shows relationships between the measured variables.","相关矩阵展示了各测量变量之间的关系。"],"medium":["through a medium","通过介质","Sound requires a medium through which to travel.","声音传播需要介质。"],"passive":["passive voice","被动语态","The passive voice can be useful when the actor is unknown.","当动作执行者未知时，被动语态可能很有用。"],"primary":["primary objective","首要目标","Our primary objective is to reduce the measurement uncertainty.","我们的首要目标是降低测量不确定度。"],"query":["database query","数据库查询","The query returned only records from the selected period.","该查询只返回所选时段的记录。"],"scrutiny":["under close scrutiny","受到严格审查","The results came under close scrutiny after the discrepancy emerged.","出现差异后，研究结果受到严格审查。"],"spatial":["spatial resolution","空间分辨率","Spatial resolution determines which features can be distinguished.","空间分辨率决定能够区分哪些特征。"],"thesis":["central thesis","中心论点","The central thesis is supported by three independent arguments.","这一中心论点由三项独立论证支持。"],"transaction":["commit a transaction","提交事务（数据库）","The database commits the transaction only after all checks pass.","只有全部检查通过后，数据库才提交该事务。"],"volume":["traffic volume","流量；业务量","Traffic volume increased sharply during the event.","活动期间流量大幅增加。"]});
