Object.assign(USAGE_NOTES,{"adequate":["足够用于某事／足以做某事",[["adequate for / adequate to do","足够用于某事／足以做某事"]],"The sample size may not be adequate for this analysis.","","样本量可能不足以用于这项分析。"],"adjust":["校正某因素／适应某变化",[["adjust for / adjust to","校正某因素／适应某变化"]],"The estimate was adjusted for temperature.","","估计值已针对温度因素作出校正。"],"assess":["评估……的影响",[["assess the impact of","评估……的影响"]],"We need to assess the impact of the new settings.","","我们需要评估新设置的影响。"],"attribute":["把 A 归因于 B",[["attribute A to B","把 A 归因于 B"]],"They attributed the shift to thermal drift.","","他们把这一偏移归因于热漂移。"],"available":["可供某人使用／可用于某事",[["be available to / be available for","可供某人使用／可用于某事"]],"The raw data are available for further analysis.","","原始数据可用于进一步分析。"],"bias":["引入偏差／系统性偏差",[["introduce bias / systematic bias","引入偏差／系统性偏差"]],"The selection procedure may introduce bias.","","这一筛选程序可能引入偏差。"],"clarify":["澄清是否……／厘清区别",[["clarify whether / clarify the distinction","澄清是否……／厘清区别"]],"Could you clarify whether the result is final?","","你能澄清这个结果是否已经定稿吗？"],"coincide":["与……同时发生或相符",[["coincide with","与……同时发生或相符"]],"The two peaks do not coincide in time.","","这两个峰值出现的时间并不一致。"],"compare":["比较 A 与 B",[["compare A with B","比较 A 与 B"]],"We compared the measured phase with the reference.","","我们将测得的相位与参考相位进行了比较。"],"compile":["汇总清单／整理结果",[["compile a list / compile the results","汇总清单／整理结果"]],"She compiled the results into a single report.","","她把结果整理成了一份报告。"],"confirm":["确认……／确认收到",[["confirm that / confirm receipt","确认……／确认收到"]],"Please confirm that the files arrived intact.","","请确认文件是否完整收到。"],"constraint":["在限制条件下／施加约束",[["under a constraint / impose a constraint","在限制条件下／施加约束"]],"The design must satisfy the timing constraints.","","设计必须满足时序约束。"],"correlate":["与……存在相关性",[["correlate with","与……存在相关性"]],"The drift correlates with the temperature change.","","漂移与温度变化存在相关性。"],"deduce":["从……推断出",[["deduce from","从……推断出"]],"We can deduce the delay from the measured phase.","","我们可以根据测得的相位推断延迟。"],"demonstrate":["证明／展示……",[["demonstrate that","证明／展示……"]],"The test demonstrates that the link is stable.","","测试表明链路是稳定的。"],"deviate":["偏离……",[["deviate from","偏离……"]],"The signal deviates from the expected waveform.","","信号偏离了预期波形。"],"distinct":["与……明显不同",[["distinct from","与……明显不同"]],"The two sources of error are distinct from each other.","","这两种误差来源彼此不同。"],"enable":["使某人能够做某事",[["enable someone to do","使某人能够做某事"]],"The tool enables users to compare two datasets.","","这个工具使用户能够比较两组数据。"],"exceed":["超出限值／超出预期",[["exceed a limit / exceed expectations","超出限值／超出预期"]],"The observed jitter did not exceed the limit.","","观测到的抖动没有超过限值。"],"feasible":["技术上可行",[["technically feasible","技术上可行"]],"The proposal is feasible but expensive.","","这个方案可行，但成本很高。"],"indicate":["表明……",[["indicate that","表明……"]],"The results indicate that further testing is needed.","","结果表明还需要进一步测试。"],"inevitable":["使某事不可避免",[["make something inevitable","使某事不可避免"]],"The delay is not inevitable if we redesign the pipeline.","","如果重新设计处理流程，延迟并非不可避免。"],"interpret":["把 A 解读为 B",[["interpret A as B","把 A 解读为 B"]],"Do not interpret correlation as proof of causation.","","不要把相关性解读为因果关系的证明。"],"preliminary":["初步结果／初步估计",[["preliminary results / preliminary estimate","初步结果／初步估计"]],"These preliminary results need independent verification.","","这些初步结果需要独立核实。"],"relevant":["与……相关",[["relevant to","与……相关"]],"Only the measurements relevant to the question are shown.","","这里只展示与这个问题相关的测量结果。"],"resolve":["解决问题／决心做某事",[["resolve an issue / resolve to do","解决问题／决心做某事"]],"We resolved the synchronization issue yesterday.","","我们昨天解决了同步问题。"]});
for(const guide of [{"words":["assess","evaluate"],"rule":"两者都可表示评估。assess 常侧重判断程度、影响或风险；evaluate 常侧重根据标准判断质量、效果或价值，语境存在重叠。","examples":[["We assessed the risk before the test.","测试前我们评估了风险。"],["We evaluated the method against the benchmark.","我们按照基准对该方法进行了评价。"]]},{"words":["confirm","verify"],"rule":"confirm 强调确认某事属实或已经发生；verify 更强调通过独立检查、数据或程序核验。两者有时可以互换。","examples":[["Please confirm the meeting time.","请确认会议时间。"],["We verified the result using a second instrument.","我们用另一台仪器核验了结果。"]]},{"words":["correlate","cause"],"rule":"correlate 描述相关变化；cause 表示引起结果。观察到相关性本身不足以证明因果关系。","examples":[["Temperature and drift are correlated.","温度与漂移存在相关性。"],["The faulty cable caused the interruption.","故障电缆导致了中断。"]]},{"words":["distinct","different"],"rule":"different 一般说事物不一样；distinct 进一步突出差异清楚、能够独立辨认。","examples":[["The two designs are different.","这两种设计不同。"],["We identified three distinct sources of noise.","我们识别出三种彼此可区分的噪声来源。"]]},{"words":["plausible","possible"],"rule":"possible 只表示有可能；plausible 强调听起来合理、符合已知情况，但并不等于事实已经证实。","examples":[["It is possible that the file is missing.","文件有可能丢失了。"],["That is a plausible explanation for the delay.","这是对延迟的一种看似合理的解释。"]]},{"words":["imply","indicate"],"rule":"imply 表示言语或事实间接暗示；indicate 可以是直接表明，也可以是数据呈现出某种迹象。","examples":[["The wording implies a stronger claim.","这种措辞暗示了更强的断言。"],["The measurements indicate a possible drift.","测量结果表明可能存在漂移。"]]},{"words":["approximate","precise"],"rule":"approximate 指近似值；precise 指明确、精细。近似值也可以精确地表述其误差范围，二者不是严格反义。","examples":[["The approximate cost is €200.","费用大约是两百欧元。"],["We need a more precise estimate.","我们需要一个更精确的估计。"]]},{"words":["retain","maintain"],"rule":"retain 侧重保留下来、不失去；maintain 侧重持续保持状态、水平或运作。","examples":[["Retain the original logs.","保留原始日志。"],["Maintain a constant temperature.","维持恒定的温度。"]]},{"words":["deduce","infer"],"rule":"infer 泛指由证据推断；deduce 通常强调根据前提或已知事实进行有逻辑的推演。普通语境有重叠。","examples":[["We inferred a problem from the pattern.","我们根据这个模式推测存在问题。"],["From these assumptions, we can deduce the result.","根据这些前提，我们可以推导出结果。"]]},{"words":["implement","execute"],"rule":"implement 强调把计划或制度付诸实施；execute 强调执行命令、程序或计划的具体动作。","examples":[["The team implemented the new policy.","团队实施了新政策。"],["The program executes the command.","程序执行该命令。"]]},{"words":["subsequent","consecutive"],"rule":"subsequent 意为后续的、之后的；consecutive 意为连续发生、中间没有间隔的。","examples":[["Subsequent tests confirmed the finding.","后续测试确认了这一发现。"],["The system failed on three consecutive days.","系统连续三天发生故障。"]]}]){for(const word of guide.words){(LEX40_CONTRASTS[word]??=[]).push(guide)}}

