Object.assign(USAGE_NOTES,{"noise":["减少噪声／背景噪声",[["reduce noise / background noise","减少噪声／背景噪声"]],"The filter removes much of the background noise.","","滤波器去除了大部分背景噪声。"],"precedent":["开创先例",[["set a precedent","开创先例"]],"The ruling could set a precedent for similar cases.","","这一裁决可能为类似案件开创先例。"],"preclude":["排除……的可能",[["preclude the possibility of","排除……的可能"]],"The missing data preclude a reliable conclusion.","","缺失的数据使我们无法得出可靠结论。"],"sanction":["实施制裁／正式批准决定",[["impose sanctions / sanction a decision","实施制裁／正式批准决定"]],"The authorities imposed sanctions after the violation.","","违规事件发生后，当局实施了制裁。"],"conjecture":["提出猜想／检验猜想",[["make a conjecture / test a conjecture","提出猜想／检验猜想"]],"The conjecture remains unproved.","","这一猜想仍未得到证明。"],"substantiate":["用证据支持主张",[["substantiate a claim","用证据支持主张"]],"The report failed to substantiate its central claim.","","这份报告未能用证据支持其核心主张。"],"refute":["驳倒某项论点",[["refute an argument","驳倒某项论点"]],"The new evidence refutes the earlier explanation.","","新的证据驳倒了先前的解释。"],"rebut":["反驳指控",[["rebut an accusation","反驳指控"]],"She rebutted the criticism with detailed figures.","","她用详细的数据反驳了批评。"],"contest":["质疑或申诉某项决定",[["contest a decision","质疑或申诉某项决定"]],"The applicant can contest the decision within thirty days.","","申请人可以在三十天内对该决定提出异议。"],"allege":["声称……（尚待证实）",[["allege that","声称……（尚待证实）"]],"The article alleged that records had been altered.","","文章声称记录遭到篡改，但这一说法尚待核实。"],"allude":["间接提及……",[["allude to","间接提及……"]],"The speaker alluded to a possible change in policy.","","发言人间接提到了政策可能变化。"],"efficacy":["治疗效果／方法有效性",[["treatment efficacy / efficacy of a method","治疗效果／方法有效性"]],"The trial evaluated the efficacy of the new treatment.","","试验评估了新疗法的有效性。"],"retrospective":["回顾性研究",[["retrospective study","回顾性研究"]],"The authors conducted a retrospective study of patient records.","","研究人员对患者记录开展了回顾性研究。"],"oversight":["监管监督／疏忽遗漏",[["regulatory oversight / an oversight","监管监督／疏忽遗漏"]],"The missing attachment was an oversight.","","漏掉附件只是一次疏忽。"],"interference":["电磁干扰",[["electromagnetic interference","电磁干扰"]],"The cable shielding reduced electromagnetic interference.","","电缆屏蔽层降低了电磁干扰。"],"lag":["A 与 B 之间的时间滞后",[["a time lag between A and B","A 与 B 之间的时间滞后"]],"There is a short lag between the command and the response.","","命令与响应之间存在短暂的时间滞后。"],"viability":["评估……的可行性",[["assess the viability of","评估……的可行性"]],"We must assess the viability of the proposed approach.","","我们必须评估所提方法是否可行。"],"persistent":["持续存在的症状／误差",[["persistent symptoms / persistent error","持续存在的症状／误差"]],"A persistent error remained after recalibration.","","重新校准后仍存在一项持续性的误差。"],"periodically":["定期检查",[["check periodically","定期检查"]],"The system checks the temperature periodically.","","系统会定期检查温度。"],"recurrent":["反复发生的故障",[["recurrent failures","反复发生的故障"]],"We investigated recurrent failures in the readout link.","","我们调查了读出链路中反复发生的故障。"],"sequential":["顺序执行",[["sequential execution","顺序执行"]],"The program executes the steps sequentially.","","程序按照顺序逐步执行。"],"consolidated":["汇总报告",[["consolidated report","汇总报告"]],"The team prepared a consolidated report of the tests.","","团队整理了一份汇总各项测试的报告。"],"explicit":["明确表达某事",[["make something explicit","明确表达某事"]],"Please make the assumptions explicit in the report.","","请在报告中明确写出这些假设。"],"implication":["某项决定可能产生的影响",[["the implications of a decision","某项决定可能产生的影响"]],"We discussed the implications of the updated schedule.","","我们讨论了更新日程可能产生的影响。"]});
for(const guide of [{"words":["conjecture","hypothesis"],"rule":"conjecture 通常指尚待证明的猜想；hypothesis 在研究中更强调可检验的具体假设。数学 conjecture 常指尚未证明的命题。","examples":[["The conjecture has not been proved.","这个猜想还没有得到证明。"],["The experiment tests a specific hypothesis.","实验检验一项具体假设。"]]},{"words":["refute","rebut"],"rule":"refute 强调证据或推理显示论点有误；rebut 强调提出反驳理由，反驳本身未必已经驳倒对方。","examples":[["The data refute the original claim.","数据驳倒了原来的主张。"],["The author rebutted the criticism.","作者回应并反驳了批评。"]]},{"words":["precedent","precedence"],"rule":"precedent 是先例；precedence 是优先权或先后次序，两者读写相近但意义不同。","examples":[["The decision set a legal precedent.","这一决定开创了法律先例。"],["Safety takes precedence over speed.","安全优先于速度。"]]},{"words":["transient","persistent"],"rule":"transient 强调短暂后消失，persistent 强调持续或反复存在；二者经常用于错误、信号和症状，但并非所有语境都严格对立。","examples":[["The signal showed a transient spike.","信号出现了一次短暂的尖峰。"],["A persistent offset remained.","仍然存在持续性的偏移。"]]},{"words":["recurrent","continuous"],"rule":"recurrent 表示间隔性地反复发生；continuous 表示不中断地持续。","examples":[["The fault is recurrent.","故障反复出现。"],["The sensor records continuously.","传感器持续不断地记录数据。"]]},{"words":["efficacy","effectiveness"],"rule":"efficacy 常用于受控条件下的预期作用；effectiveness 更常指实际使用中的效果。但具体领域的区分可能不同。","examples":[["The trial measured treatment efficacy.","试验测量了治疗效能。"],["The study examined real-world effectiveness.","研究考察了实际应用中的效果。"]]},{"words":["inclusive","exclusive"],"rule":"inclusive 指包括多种人群或情况；exclusive 指专属或排他的，也可表示某数值不包含端点，须按语境理解。","examples":[["The event is open and inclusive.","活动开放且具有包容性。"],["The fee is exclusive of tax.","该费用不含税。"]]},{"words":["allegation","evidence"],"rule":"allegation 是尚未证实的指控或说法；evidence 是支持或反驳说法的证据。报道中需要清晰区分。","examples":[["The allegation has not been verified.","这项指控尚未核实。"],["Investigators collected new evidence.","调查人员收集了新的证据。"]]}]){for(const w of guide.words){(LEX40_CONTRASTS[w]??=[]).push(guide)}}

