Object.assign(V30_USAGE_EXAMPLES,{"hereby":["I hereby confirm that ...","兹确认……（正式书面用语）","I hereby confirm that the report has been submitted.","兹确认报告已提交。"],"arguably":["arguably the most important","可以说最重要的","This is arguably the most important limitation of the method.","这可以说是该方法最重要的局限。"],"ostensibly":["ostensibly to do something","表面上是为了做某事","The visit was ostensibly intended to discuss cooperation.","这次访问表面上是为了讨论合作。"],"effectively":["effectively impossible","实际上不可能","The required precision makes a direct measurement effectively impossible.","所需的精度使直接测量实际上无法实现。"],"namely":["namely, ...","即……（引出明确内容）","Two factors remain, namely noise and temperature drift.","还有两个因素，即噪声和温度漂移。"],"indefinitely":["postpone indefinitely","无限期推迟","The meeting was postponed indefinitely.","会议被无限期推迟。"],"initially":["initially expected","最初预期的","The initial estimate was lower than the measured value.","初步估计值低于实测值。"],"steadily":["increase steadily","稳步增加","The signal amplitude increased steadily over time.","信号幅度随时间稳步上升。"],"sharply":["drop sharply","急剧下降","The efficiency dropped sharply at low temperatures.","在低温下，效率急剧下降。"],"strictly":["strictly speaking","严格地说","Strictly speaking, these two quantities are not independent.","严格地说，这两个量并不独立。"],"theoretically":["theoretically possible","理论上可行","The approach is theoretically possible but hard to implement.","这种方法在理论上可行，但实现起来很困难。"],"practically":["practically identical","几乎完全相同","The two distributions were practically identical.","这两个分布几乎完全相同。"],"deliberately":["deliberately choose","有意选择","We deliberately chose a simple reference model.","我们有意选择了一个简单的参考模型。"],"mutually":["mutually exclusive","互斥的","The two event categories are mutually exclusive.","这两类事件互不重叠。"],"collectively":["collectively account for","合计占……","These components collectively account for most of the uncertainty.","这些组成部分合计贡献了大部分不确定度。"],"independently":["measure independently","独立测量","We measured each channel independently.","我们分别独立测量了每条通道。"],"systematically":["systematically review","系统地审查","The team systematically reviewed the calibration steps.","团队系统地审查了各项校准步骤。"],"succinct":["a succinct explanation","简明扼要的解释","Please give a succinct explanation of the result.","请简明扼要地解释结果。"],"lucid":["a lucid account","清楚明白的叙述","The paper offers a lucid account of the method.","论文清楚地介绍了这一方法。"],"imminent":["an imminent deadline","迫在眉睫的截止日期","The deadline is imminent, so we need to prioritize the checks.","截止日期临近，因此我们需要优先完成检查。"],"averse":["be averse to","不愿意；反感……","Some teams are averse to changing a working system.","有些团队不愿改动运行正常的系统。"],"disinterested":["a disinterested observer","公正、无利害关系的观察者","A disinterested reviewer assessed the evidence.","一位没有利益关联的评审人员审查了证据。"],"stipulate":["stipulate that ...","规定……","The protocol stipulates that each test must be recorded.","规程规定每项测试都必须记录。"],"thereof":["any part thereof","其中的任何部分（正式书面语）","The contract covers the system and any component thereof.","合同涵盖该系统及其任何组成部分。"]});
for(const guide of [{"words":["ostensibly","seemingly"],"rule":"ostensibly 强调公开或表面上的说法可能掩盖真实目的；seemingly 表示看起来如此，未必暗示有人隐瞒。","examples":[["The trip was ostensibly for research.","这趟旅行表面上是为了研究。"],["The two answers were seemingly identical.","两个答案看上去一样。"]]},{"words":["arguably","undoubtedly"],"rule":"arguably 表示可以提出合理论据支持的评价；undoubtedly 表示说话者认为没有合理疑问，确信程度更强。","examples":[["This is arguably the better method.","可以说这是更好的方法。"],["The new method is undoubtedly faster.","新方法无疑更快。"]]},{"words":["effectively","efficiently"],"rule":"effectively 指达到预期效果，也可指实际上；efficiently 指以较少时间、成本或资源完成任务。","examples":[["The filter removes noise effectively.","滤波器能够有效去除噪声。"],["The program uses memory efficiently.","程序能够高效利用内存。"]]},{"words":["imminent","eminent","immanent"],"rule":"imminent 指即将发生；eminent 指某人声望卓著；immanent 指存在于某个体系内部，三者不能互换。","examples":[["A decision is imminent.","决定即将公布。"],["She is an eminent scientist.","她是一位杰出的科学家。"]]},{"words":["disinterested","indifferent"],"rule":"disinterested 在严谨用法中强调公正、没有利害关系；indifferent 强调漠不关心或不在意。前者也有“不感兴趣”的日常用法，正式写作宜区分。","examples":[["We need a disinterested reviewer.","我们需要一位没有利益关联的公正评审。"],["She was indifferent to the outcome.","她对结果漠不关心。"]]},{"words":["gradually","steadily"],"rule":"gradually 强调变化是逐步发生的；steadily 强调速度或过程稳定。某变化可以同时逐步而稳定地进行。","examples":[["The temperature rose gradually.","温度逐渐升高。"],["The clock drift increased steadily.","时钟漂移稳定地增大。"]]},{"words":["terse","succinct"],"rule":"terse 强调简短，有时带生硬或不耐烦的感觉；succinct 强调以少量文字清楚表达重点，通常含褒义。","examples":[["His reply was terse.","他的答复很简短，甚至有些生硬。"],["The summary is succinct and clear.","这份摘要简明清晰。"]]},{"words":["formerly","previously"],"rule":"formerly 常表示过去的身份、名称或状态现已改变；previously 更中性，表示在所说时间之前。","examples":[["The site was formerly a factory.","这处地点以前是一家工厂。"],["The result was previously reported.","这一结果此前曾有报告。"]]},{"words":["temporarily","indefinitely"],"rule":"temporarily 强调状态只持续一段有限时间；indefinitely 表示没有确定结束时间，并不必然意味着永久。","examples":[["The service is temporarily unavailable.","服务暂时不可用。"],["The launch has been postponed indefinitely.","发布已被无限期推迟。"]]}]){for(const w of guide.words){(LEX40_CONTRASTS[w]??=[]).push(guide)}}


