 const examLabels={'中':'中考','高':'高考','四':'CET-4','六':'CET-6','研':'考研','托':'TOEFL','雅':'IELTS','宝':'GRE'};const examOverview=w.examTags?`<div class="exam-roles"><span>词汇组</span>${[...w.examTags].map(t=>`<span class="exam-role">${examLabels[t]||t}</span>`).join('')}</div>`:'';
