 const gl=w.glosses||[]; const primary=gl.slice(0,6);const more=gl.slice(6);
 const glosses=gl.length?`<div class="minor-title">Distinct meanings · Dictionary senses <span class="sense-total">${gl.length} senses</span></div><ol class="sense-list">${primary.map(glossItem).join('')}</ol>${more.length?`<details class="sense-more"><summary>显示其他 ${more.length} 个词典义项</summary><ol class="sense-list" start="7">${more.map((x,i)=>glossItem(x,i+6)).join('')}</ol></details>`:''}`:'';
