 let avg='';for(let f=1;f<=10;f++){const arr=valid.filter(w=>w.freqLevel===f),v=arr.length?arr.reduce((s,w)=>s+w.level,0)/arr.length:0;avg+=`<div class="average-row"><strong>F${f}</strong><div class="average-track"><div class="average-fill" style="width:${(v/10*100).toFixed(2)}%"></div></div><strong>${v?v.toFixed(2):'—'}</strong><span class="average-count">${fmt(arr.length)} 词</span></div>`}$('average-difficulty').innerHTML=avg;
