/* v27 Search Clarity: a single declarative source for displaying and clearing active conditions. */
function installSearchClarity(){
 const $=id=>document.getElementById(id);
 const config={
  main:{q:'search',sel:['group-filter','origin','difficulty','frequency','verbal','dialect-filter','pos','state','study-focus','sort']},
  dialect:{q:'dialect-search',button:'[data-dialect-type].selected',label:'英美差异类型'},
  root:{q:'root-search',sel:['root-type','root-language']},
  'root-members':{q:'root-member-search'},
  atlas:{q:'atlas-search',check:['atlas-show-candidates']},
  semantic:{q:'semantic-search',sel:['semantic-category','semantic-type']},
  contrast:{q:'contrast-search'},
  prep:{q:'prep-search',button:'[data-pcat].selected',label:'介词类别'},
  'prep-contrast':{q:'prep-contrast-search'},
  'prep-collocation':{q:'prep-collocation-search',button:'[data-pcoll].selected',label:'搭配类别'},
  learner:{q:'learner-search',sel:['learner-category']}
 };
 const esc=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const selected=el=>el.selectedOptions?.[0]?.textContent?.trim()||el.value;
 const sectionText={main:'词汇',dialect:'英美差异',root:'词根', 'root-members':'词族成员',atlas:'语义领域',semantic:'语义关系',contrast:'词义辨析',prep:'介词', 'prep-contrast':'介词辨析', 'prep-collocation':'固定搭配',learner:'学习内容'};
 function collect(key){
  const c=config[key],out=[],q=$(c.q);
  if(q?.value.trim())out.push({kind:'input',id:c.q,label:'关键词',value:q.value.trim()});
  (c.sel||[]).forEach(id=>{const el=$(id);if(el&&el.value!=='all'&&!(id==='sort'&&el.value==='recommended'))out.push({kind:'select',id,label:el.closest('.field')?.querySelector('label')?.textContent.trim()||el.getAttribute('aria-label')||({sort:'排序方式','root-type':'构词类型','root-language':'来源','semantic-category':'语义主题','semantic-type':'关系类型','learner-category':'学习内容类型'}[id]||'筛选'),value:selected(el)})});
  (c.check||[]).forEach(id=>{const el=$(id);if(el?.checked)out.push({kind:'check',id,label:'扩展选项',value:el.closest('label')?.textContent?.trim()||'已启用'})});
  if(c.button){const el=document.querySelector(c.button);if(el){const v=el.dataset.dialectType||el.dataset.pcat||el.dataset.pcoll; if(v!=='all'&&v!=='全部')out.push({kind:'button',id:key,label:c.label,value:el.textContent.trim()})}}
  return out;
 }
 function update(){
  Object.keys(config).forEach(key=>{
   const summary=$('lex-search-summary-'+key);if(!summary)return;
   const chips=collect(key),active=chips.length>0,container=summary.closest('.lex-query-tools');
   summary.dataset.active=String(active);if(container)container.dataset.active=String(active);
   const counter=$('lex-count-'+key);if(counter){counter.textContent=active?`已应用 ${chips.length} 项条件`:'未设置条件';counter.classList.toggle('active',active);counter.setAttribute('role','status');counter.setAttribute('aria-label',counter.textContent)}
   const inp=$(config[key].q);if(inp)inp.dataset.searchActive=String(!!inp.value.trim());
   const dot='<i class="lex-query-status-dot" aria-hidden="true"></i>';
   summary.innerHTML='<span class="lex-query-summary-status">'+dot+'<b>'+(active?`已应用 ${chips.length} 项搜索条件`:'未设置搜索条件')+'</b>'+(active?' · 点击标签可撤销':' · 当前显示全部'+sectionText[key])+'</span>'+
   '<span class="lex-query-chips">'+chips.map((f,i)=>`<button type="button" class="lex-query-chip" data-lex-scope="${key}" data-lex-chip="${i}" title="撤销 ${esc(f.label)}：${esc(f.value)}" aria-label="撤销 ${esc(f.label)}：${esc(f.value)}"><span class="lex-query-chip-label">${esc(f.label)}：${esc(f.value)}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button>`).join('')+'</span>'+(active?`<button type="button" class="lex-query-clear" data-lex-scope="${key}" data-lex-clear-all="1">清除全部条件</button>`:'');
  });
 }
 function clearOne(key,item){
  if(!item)return;
  if(key==='main'&&item.kind==='select'&&item.id==='group-filter'&&section==='group-words'){activeCollectionId='';$(item.id).value='all';navigate('all');return;}
  if(item.kind==='button'){
   const all=key==='dialect'?document.querySelector('[data-dialect-type="all"]'):key==='prep'?document.querySelector('[data-pcat="全部"]'):document.querySelector('[data-pcoll="全部"]');if(all)all.click();return;
  }
  const el=$(item.id);if(!el)return;
  if(item.kind==='input'){el.value='';el.dispatchEvent(new Event('input',{bubbles:true}));}
  else if(item.kind==='check'){el.checked=false;el.dispatchEvent(new Event('change',{bubbles:true}));}
  else {el.value='all';if(item.id==='sort')el.value='recommended';el.dispatchEvent(new Event('change',{bubbles:true}));}
 }
 document.addEventListener('click',e=>{const target=e.target.closest('[data-lex-scope]');if(!target)return;const key=target.dataset.lexScope;const entries=collect(key);if(target.dataset.lexClearAll==='1'){if(key==='main'){resetFilters();atlasBrowseSet=null;$('atlas-scope-bar').classList.add('hidden');render();}else entries.forEach(f=>clearOne(key,f));}else clearOne(key,entries[Number(target.dataset.lexChip)]);requestAnimationFrame(update)});
 let raf=0;function schedule(){if(raf)return;raf=requestAnimationFrame(()=>{raf=0;update()})}
 document.addEventListener('input',schedule,true);document.addEventListener('change',schedule,true);document.addEventListener('click',schedule,true);
 // Clear/reset via keyboard Escape only when the focused search box has a query.
 document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const inp=e.target;if(inp.matches?.('input[type="search"]')&&inp.value.trim()){inp.value='';inp.dispatchEvent(new Event('input',{bubbles:true}));e.preventDefault();e.stopPropagation();}} ,true);
 // Global '/' shortcut focuses the visible section search instead of unexpectedly jumping to Vocabulary.
 document.addEventListener('keydown',e=>{if(e.key!=='/'||e.altKey||e.ctrlKey||e.metaKey||e.target.closest('input,select,textarea,[contenteditable]'))return;
  const input=[...document.querySelectorAll('input[type="search"]')].find(x=>{const r=x.getBoundingClientRect();return r.width>80&&r.height>20&&!x.closest('.hidden')});
  if(input){e.preventDefault();e.stopImmediatePropagation();input.focus();}},true);
 update();
 window.lexSearchClarity={update,collect};
}



