function installCuratedFilter(){
  function setup(){
    const input=document.getElementById('only-bilingual');
    const wrap=document.getElementById('lex-curated-label');
    if(!input||!wrap)return;
    input.checked=!!lexOnlyCurated;
    function paint(){wrap.classList.toggle('is-active',input.checked);wrap.setAttribute('title',input.checked?'正在仅显示英中精释词条；再次点击恢复全部词条':'只看有中英逐义对应简明解释的词条');}
    paint();
    input.addEventListener('change',()=>{
      lexOnlyCurated=input.checked;
      try{localStorage.setItem('lexicon-v39-curated-only',lexOnlyCurated?'1':'0')}catch(_e){}
      paint();render(true);
    });
    const clear=document.getElementById('clear-filters');
    clear?.addEventListener('click',()=>{input.checked=false;paint();});
    // Avoid hard-to-read inert controls while keeping actions keyboard-accessible.
    document.getElementById('entries')?.addEventListener('keydown',(event)=>{
      if((event.key==='Enter'||event.key===' ')&&event.target?.classList?.contains('entry-head')){
        event.preventDefault();const word=event.target.dataset.open;
        if(word)event.target.click();
      }
    });
  }
  setup();
}


