/* Lexicon v54 content expansion */
Object.assign(V30_USAGE_EXAMPLES,{"exactly":["exactly what / exactly when","恰好……；准确地指出所指对象或时间","That is exactly what the report says.","报告说的正是这个意思。"],"routinely":["be routinely checked","按常规接受检查","The sensors are routinely checked before each run.","每次运行前都会按常规检查传感器。"],"habitually":["habitually arrive late","习惯性地迟到（可能带批评）","He habitually arrives late, even for important meetings.","他习惯性迟到，连重要会议也不例外。"],"presumably":["presumably because","推测原因；提示尚未证实","The output changed, presumably because the temperature rose.","输出发生变化，推测是由于温度上升。"],"supposedly":["supposedly reliable","据称可靠；说话人可能保留怀疑","The supposedly reliable measurement was not reproducible.","那项据称可靠的测量结果却无法复现。"],"subsequently":["subsequently found","随后发现；只表示时间先后","The problem was subsequently traced to a loose connector.","后来查明问题源于连接器松动。"],"eventually":["eventually succeed","经过一段时间最终成功","After several attempts, the team eventually succeeded.","经过多次尝试，团队最终成功了。"],"ultimately":["ultimately depend on","归根结底取决于","The decision ultimately depends on the available evidence.","这一决定归根结底取决于现有证据。"],"verify":["verify that / verify a result","核实事实或结果是否正确","Verify that the calibration file matches the hardware.","核实校准文件与硬件相匹配。"],"evaluate":["evaluate the performance of","根据标准评估性能","We evaluated the performance on a separate test set.","我们使用独立测试集评估了性能。"],"forecast":["forecast demand","预测未来需求","The model forecasts demand for the next quarter.","该模型预测下季度的需求。"],"accuracy":["measurement accuracy","测量准确度，强调接近真值","Improving precision does not automatically improve accuracy.","提高精密度并不会自动提高准确度。"],"consistent":["be consistent with","与……相一致；不等于证实","The observation is consistent with the proposed explanation.","这一观察结果与所提出的解释相符。"],"coherent":["a coherent argument","内部逻辑连贯的论证","The article presents a coherent argument for the change.","文章对这一调整提出了逻辑连贯的论证。"],"simultaneous":["simultaneous measurements","同时进行的测量","The two sensors recorded simultaneous measurements.","两个传感器同时进行了测量。"],"concurrent":["concurrent requests","并发请求；不一定严格同时执行","The server handles several concurrent requests.","服务器能够处理多个并发请求。"],"definitive":["a definitive answer","确定的、具有决定性的回答","The experiment did not yield a definitive answer.","这项实验尚未给出确切答案。"],"tentative":["a tentative conclusion","暂时性的结论，仍需验证","We reached only a tentative conclusion from the limited data.","根据有限的数据，我们只能得出暂时性的结论。"],"reliable":["a reliable estimate","可靠的估计；多次使用表现可信","The method provides a reliable estimate within this range.","该方法在这一范围内能够提供可靠的估计。"],"resilient":["resilient to disruptions","面对干扰仍能恢复或维持功能","The design is resilient to short network interruptions.","这一设计能够应对短暂的网络中断。"],"stable":["remain stable under","在……条件下保持稳定","The reference remained stable under small temperature changes.","参考信号在小幅温度变化下保持稳定。"],"negligible":["a negligible impact on","影响小到可忽略","The adjustment had a negligible impact on the final estimate.","这一调整对最终估计的影响可以忽略。"],"sufficient":["sufficient evidence to","足够的证据支持某项判断","We do not yet have sufficient evidence to reject the model.","我们目前还没有充分证据否定这个模型。"],"noticeable":["a noticeable difference","肉眼或直观可觉察的差别","The new display has a noticeable improvement in clarity.","新显示屏的清晰度有明显可觉察的提升。"],"conflate":["conflate two concepts","把两个不同概念混同","Do not conflate measurement precision with accuracy.","不要把测量精密度与准确度混为一谈。"],"understate":["understate the uncertainty","低报或弱化不确定性","Ignoring a source of error can understate the uncertainty.","忽略某项误差来源可能低估不确定性。"],"overstate":["overstate the evidence","夸大证据所能支持的结论","The headline overstates what the study actually shows.","这个标题夸大了研究实际表明的内容。"],"distill":["distill the main argument","提炼核心论点","The summary distills the main argument into two paragraphs.","摘要把核心论点提炼为两段文字。"],"paraphrase":["paraphrase a passage","用自己的话转述段落","Paraphrase the passage without changing its meaning.","请在不改变意思的前提下用自己的话转述这段文字。"],"resume":["resume operations","中断后恢复运行","The team resumed operations after the maintenance window.","维护窗口结束后团队恢复了运行。"],"inequity":["address an inequity","处理不公正的差异","The reform aims to address inequities in access to education.","改革旨在解决教育机会方面的不公平。"],"complementary":["complementary approaches","相互补充的方法","The two approaches are complementary rather than competing.","这两种方法是互补的，而非相互竞争的。"],"complimentary":["complimentary admission","免费入场；不是“互补入场”","The ticket includes complimentary admission to the exhibition.","这张票包含展览的免费入场资格。"]});
for(const note of [{"words":["presumably","supposedly"],"rule":"presumably 表示依据情况作出的推测；supposedly 往往表示“据称”，有时暗含说话者并未完全采信。两者都不自动表示事实已被证实。","examples":[["The train is presumably delayed by the weather.","火车大概是因天气而晚点。"],["The supposedly new device was already in use.","这台据称是新设备的机器其实早就在使用。"]]},{"words":["eventually","ultimately"],"rule":"eventually 强调经过一段时间后终于发生；ultimately 强调最终结果、根本原因或最重要的考量，不一定具有漫长的时间过程。","examples":[["The service eventually recovered.","服务经过一段时间终于恢复。"],["The outcome ultimately depends on funding.","结果归根结底取决于资金。"]]},{"words":["routinely","habitually"],"rule":"routinely 强调按常规或程序重复；habitually 强调个人长期习惯，常可带批评色彩；不能一律译成“常常”。","examples":[["The system is routinely inspected.","系统按常规接受检查。"],["He habitually skips the final review.","他习惯性地跳过最终审查。"]]},{"words":["noticeable","significant"],"rule":"noticeable 是能被察觉；significant 可以是重要、影响大，在统计学中又有特定定义。肉眼可见不等于统计显著，统计显著也不一定意味着实际影响很大。","examples":[["The difference is noticeable in the plot.","图中可以看出这个差别。"],["The result is statistically significant but small.","结果在统计上显著，但效应很小。"]]},{"words":["observable","visible"],"rule":"observable 强调能够通过观察或仪器测量；visible 更侧重视觉上能看见，也可泛指明显。不可直接将“可测量”译成 visible。","examples":[["The oscillation is observable only with specialized equipment.","这种振荡只有借助专门设备才能观测到。"],["The mark is clearly visible.","这个标记清晰可见。"]]},{"words":["inequality","inequity"],"rule":"inequality 描述差异或不平等，未必直接作道德判断；inequity 则强调不公正、不公平。解释社会现象时需要分开事实层面的差异与价值判断。","examples":[["Income inequality increased.","收入差距扩大了。"],["The program seeks to reduce inequity in access.","该项目旨在减少获取机会方面的不公平。"]]},{"words":["coherent","consistent"],"rule":"coherent 强调各部分构成连贯整体；consistent 强调相互不冲突或多次保持一致。论证可能自洽却与事实不符；数据可能一致却未形成完整解释。","examples":[["The essay develops a coherent argument.","这篇文章形成了连贯的论证。"],["The measurements are consistent across runs.","多次运行的测量结果保持一致。"]]},{"words":["concurrent","simultaneous"],"rule":"simultaneous 通常强调同一时刻发生；concurrent 强调时间段重叠或并发推进。在软件中 concurrent tasks 可以交错执行，不一定真正并行。","examples":[["The clocks generated simultaneous edges.","这些时钟同时产生了边沿。"],["The server processes concurrent requests.","服务器处理并发请求。"]]},{"words":["complementary","complimentary"],"rule":"complementary 意为互补的；complimentary 既可表示赞美，也可表示免费的。两者拼写接近，但含义和搭配明显不同。","examples":[["The methods provide complementary information.","这些方法提供互补的信息。"],["Complimentary refreshments are available.","提供免费茶点。"]]},{"words":["paraphrase","summarize"],"rule":"paraphrase 用不同措辞重述原意，通常保留较多信息；summarize 抽取重点、缩短篇幅。不能用“概括”替代所有转述任务。","examples":[["Paraphrase the sentence in plain English.","请用通俗英语改写这个句子，保持原意。"],["Summarize the report in a paragraph.","请用一段话概述这份报告。"]]}])for(const word of note.words){(LEX40_CONTRASTS[word]??=[]).push(note)}


/* Lexicon v55: sense-verified distinctions and natural bilingual examples. */
Object.assign(V30_USAGE_EXAMPLES,{"make":["make a decision / make progress","常与 decision、progress 等抽象名词搭配，不能直接用 do 替代","We need to make a decision before Friday.","我们需要在星期五之前作出决定。"],"good":["be good at / be good for","good at 表示擅长；good for 表示有益，二者不能互换","She is good at explaining difficult ideas.","她很擅长解释复杂的概念。"],"get":["get used to doing something","逐渐习惯某事，to 在此为介词，后接名词或动名词","It takes time to get used to a new accent.","适应一种新的口音需要时间。"],"take":["take into account","把某种因素考虑在内，不是字面上的“拿进去”","The model takes measurement uncertainty into account.","该模型考虑了测量不确定性。"],"go":["go wrong","发生差错、出问题，不能按“去错误的地方”直译","Several things went wrong during the test.","测试过程中出了好几处问题。"],"set":["set a precedent","开创先例，也常见 set a deadline、set a limit","The ruling could set a precedent for future cases.","这项裁决可能为今后的案件开创先例。"],"run":["run a test / run a business","表示执行测试或经营业务，而不仅是“跑步”","We ran the test twice to check reproducibility.","我们把测试运行了两遍，以检查可复现性。"],"matter":["it matters whether / what","强调某个条件或区别很重要","It matters whether the signal is delayed or distorted.","信号究竟是延迟还是失真，这一点很重要。"],"actual":["the actual value / actual cost","指实际数值或真实成本，未必等于“当前”的","The actual cost was higher than the estimate.","实际成本高于估算值。"],"probable":["a probable cause / probable outcome","表示根据证据判断为较可能，而非已证实","The report identifies a probable cause, not a confirmed one.","报告指出的是一个可能性较大的原因，而非已证实的原因。"],"likely":["be likely to do something","表示很可能发生；通常不用 likely 直接替代 possible","The temperature is likely to rise overnight.","夜间气温很可能上升。"],"liable":["be liable for / be liable to","liable for 常表示法律责任；liable to 表示容易发生某事，常带负面结果","The company may be liable for the damage.","公司可能需要为损失承担法律责任。"],"hesitant":["be hesitant to agree","因不确定而犹豫，并非一定不愿意","She was hesitant to agree without further evidence.","没有更多证据，她不敢贸然同意。"],"reluctant":["be reluctant to do something","不太愿意去做，不只是暂时犹豫","He was reluctant to share the preliminary findings.","他不太愿意分享初步发现。"],"skeptical":["be skeptical of a claim","对说法持保留态度，要求更充分的证据","Reviewers were skeptical of the unusually strong claim.","审稿人对这一异常强烈的结论持怀疑态度。"],"cynical":["be cynical about motives","怀疑动机真诚，往往带消极判断","She was cynical about the company’s sudden promises.","她对公司的突然承诺持不信任态度。"],"reign":["during the reign of","指某位君主的统治时期","Trade expanded during the reign of the new monarch.","在新君主统治期间，贸易扩大了。"],"rein":["rein in spending","约束开支，不要与 reign（统治）混淆","The team had to rein in spending after the budget cut.","预算削减后，团队不得不控制开支。"],"improbable":["an improbable coincidence","非常不大可能的巧合；不是不可能的巧合","It was an improbable coincidence, but it did happen.","这是个极不可能发生的巧合，但确实发生了。"],"thoroughness":["check for thoroughness","检查是否全面仔细，区别于单纯的写作长度","The review was praised for its thoroughness.","这次审查因全面细致而受到称赞。"],"coercion":["under coercion","在威胁或强制下；表达缺乏自由选择","A statement obtained under coercion may be unreliable.","通过胁迫取得的陈述可能不可靠。"],"specific":["be specific about something","明确指出细节，而不是泛泛而谈","Please be specific about the conditions of the experiment.","请明确说明实验条件。"],"cumbersome":["a cumbersome procedure","程序繁琐、不易执行，不单纯表示慢","The team replaced the cumbersome approval process.","团队替换了繁琐的审批流程。"],"comprehend":["comprehend the implications","理解潜在影响，而非仅仅看懂字面","It is difficult to comprehend the implications without context.","没有上下文，很难理解其中的深层影响。"],"inertia":["institutional inertia","制度或机构的惯性，可能阻碍改革","Institutional inertia slowed the reform.","体制惯性减缓了改革进程。"],"cognitive":["cognitive load","理解、思考和记忆所需的认知负荷","A simpler layout reduces cognitive load for readers.","更简洁的布局能减轻读者的认知负荷。"],"predicate":["predicate logic","谓词逻辑；不同于语法中的普通“谓语”","Predicate logic can express relations between objects.","谓词逻辑能够表达对象之间的关系。"],"preserve":["preserve the original wording","保留原文措辞，不等于节约资源","The translation should preserve the original ambiguity.","译文应保留原文的歧义。"],"conserve":["conserve energy / conserve water","强调节约使用有限资源","Insulating the building helps conserve energy.","为建筑物增加隔热层有助于节约能源。"],"ensure":["ensure that something happens","采取措施确保结果；不要与表示投保的 insure 混淆","A second check helps ensure that the data are complete.","再次检查有助于确保数据完整。"],"insure":["insure against loss","投保以应对损失，典型用法与 ensure 不同","The shipment was insured against damage.","这批货物已投保运输损坏险。"]});
for(const note of [{"words":["hesitant","reluctant"],"rule":"hesitant 强调犹豫、拿不准或谨慎；reluctant 则强调不愿意，可能即使没有疑问也不想做。二者都能接 to do，但表达的态度不同。","examples":[["I was hesitant to publish before checking the figures.","在核对数字之前，我对发表一事犹豫不决。"],["She was reluctant to publish even after the checks.","即使核查完毕，她仍不情愿发表。"]]},{"words":["skeptical","cynical"],"rule":"skeptical 是对证据不足保持怀疑，可能在获得证据后改变看法；cynical 常是对他人诚意和动机持消极、不信任的判断。不要把理性怀疑等同于愤世嫉俗。","examples":[["The scientist was skeptical until the result was replicated.","在结果得到复现之前，这位科学家持怀疑态度。"],["He was cynical about every offer of help.","他对每一次帮助提议都怀疑其动机。"]]},{"words":["liable","likely"],"rule":"likely 通常中性地表示“很可能”；liable to 除了表示可能发生，还常暗示容易出现不利结果。liable for 则完全是另一种结构，表示对某事负有责任。","examples":[["The train is likely to arrive on time.","列车很可能准点到达。"],["The device is liable to fail in high humidity.","这种设备在高湿度下容易出故障。"]]},{"words":["efficient","effective"],"rule":"efficient 强调以较少时间、成本或资源完成任务；effective 强调确实达到预期目标。一种方法可以高效却无效，也可以有效却效率低。","examples":[["The new workflow is more efficient but less accurate.","新流程效率更高，但准确度更低。"],["The treatment was effective, although costly.","这种治疗有效，尽管代价高昂。"]]},{"words":["adopt","adapt"],"rule":"adopt 指采用方法、政策或收养；adapt 指调整以适应新的要求（adapt A for B、adapt to C）。使用现成方法与改造方法是不同动作。","examples":[["The team adopted a new calibration method.","团队采用了一种新的校准方法。"],["They adapted the method to a different detector.","他们对这种方法作了调整，使其适用于另一种探测器。"]]},{"words":["preserve","conserve"],"rule":"preserve 强调保持原有状态、品质、证据或历史；conserve 强调节约和妥善利用资源，也可以指保护自然与文物。二者在“保护”意义上有交集，但搭配和侧重点不同。","examples":[["The archive preserves the original letters.","档案馆保存着原始信件。"],["The policy aims to conserve water.","这项政策旨在节约用水。"]]},{"words":["good","well"],"rule":"good 常作形容词，说明人或物的品质；well 常作副词，说明动作完成得如何。well 也可以作形容词表示身体健康，good 则可出现在 feel good 一类固定表达中。","examples":[["She is a good writer.","她是一位优秀的作家。"],["She writes very well.","她写得很好。"]]},{"words":["get","receive"],"rule":"get 的义项广泛，除“得到”外还可表示变得、到达、理解等；receive 更正式，聚焦收到某物或接受某种待遇。不能把所有 get 都替换为 receive。","examples":[["I got home late.","我很晚才到家。"],["I received the package yesterday.","我昨天收到了包裹。"]]},{"words":["specific","particular"],"rule":"specific 强调明确而具体、针对某个条件；particular 强调从一类对象中指定的某一个，也可指讲究、挑剔。两者有重合，但 particular 不总表示有足够细节。","examples":[["Give me a specific reason for the change.","请告诉我这次改动的具体理由。"],["I remember one particular conversation.","我记得其中一次特别的谈话。"]]},{"words":["comprehend","understand"],"rule":"understand 是通用的“理解”；comprehend 较正式，常强调对复杂内容、含义或后果的领会。并非所有 understand 都应该改写为 comprehend。","examples":[["I understand your question.","我明白你的问题。"],["It takes time to comprehend the full implications.","理解其中的全部影响需要时间。"]]}])for(const word of note.words){(LEX40_CONTRASTS[word]??=[]).push(note)}

