Object.assign(V30_USAGE_EXAMPLES,{"account":["account for a difference","解释差异的原因；也可表示“占比”","Temperature changes may account for part of the observed drift.","温度变化可能解释部分观测到的漂移。"],"entail":["entail a risk / entail doing","意味着必然涉及某种后果或要求，常接名词或 -ing","Implementing the proposal will entail additional maintenance.","实施这一方案将涉及额外的维护工作。"],"distinguish":["distinguish A from B","把 A 与 B 区分开，强调相关差别","It is important to distinguish correlation from causation.","区分相关关系与因果关系十分重要。"],"contrast":["contrast A with B","将两个对象对照，突显差异","The report contrasts laboratory results with field observations.","报告将实验室结果与现场观测作了对照。"],"longitudinal":["a longitudinal study","纵向研究；跨时间反复跟踪同一对象","The longitudinal study followed the same participants for five years.","这项纵向研究对同一批参与者跟踪了五年。"],"comprise":["comprise three parts","表示“由……组成”；通常整体作主语","The review comprises three independent sections.","这篇综述由三个独立章节组成。"],"constitute":["constitute evidence / constitute a breach","构成某物；强调满足某种定义或条件","A single unusual result does not constitute proof.","单个异常结果并不构成证明。"],"hence":["hence the need for","因此、由此产生；偏正式、书面语","The measurements vary considerably, hence the need for calibration.","这些测量结果差异很大，因此有必要进行校准。"],"ambiguous":["an ambiguous statement","说法可作多种解释；不等于说话者故意含糊","The instruction was ambiguous about the required time.","该指令对所要求的时间表述不清。"],"rigorous":["rigorous testing / rigorous analysis","严格而系统、方法扎实；不只是难度很高","The claim requires rigorous independent testing.","这一主张需要经过严格的独立检验。"],"likelihood":["the likelihood of an outcome","日常指某事发生的可能性；统计学中可有专门定义","We assessed the likelihood of a delay before scheduling the test.","安排测试前，我们评估了延误的可能性。"],"contingent":["be contingent on approval","以某条件得到满足为前提，常接 on/upon","Funding is contingent on approval of the revised plan.","资金拨付取决于修订方案是否获批。"]});
for(const guide of [{"words":["surmise","infer"],"rule":"surmise 是基于有限线索作出猜测，可能相当不确定；infer 强调依据观察、论据等进行推断。两者均不保证结论正确。","examples":[["I can only surmise why she left early.","我只能猜测她为何提前离开。"],["We infer the temperature trend from repeated readings.","我们根据重复读数推断温度趋势。"]]},{"words":["ambivalence","ambiguity"],"rule":"ambivalence 指同一人对同一对象有相互冲突的感情或态度；ambiguity 指措辞、意义或情境存在多种解释。","examples":[["He felt ambivalence about accepting the offer.","对于是否接受提议，他心情矛盾。"],["The wording creates ambiguity about the deadline.","这种措辞让截止日期存在歧义。"]]},{"words":["reciprocal","mutual"],"rule":"reciprocal 强调双方互相给予、作用或承担义务；mutual 强调各方共同拥有某种感受、利益或关系。reciprocal obligations 与 mutual respect 是典型搭配。","examples":[["The two institutions have reciprocal access agreements.","两家机构签有相互开放访问的协议。"],["The collaboration depends on mutual trust.","这项合作依赖彼此信任。"]]},{"words":["longitudinal","temporal"],"rule":"longitudinal 研究在一段时间内反复跟踪同一对象；temporal 泛指“与时间有关的”，并不要求追踪同一对象。","examples":[["The longitudinal study followed the same participants for five years.","这项纵向研究对同一批参与者进行了五年跟踪。"],["The analysis reveals a temporal pattern.","这项分析揭示了一种时间上的模式。"]]},{"words":["deterrent","obstacle"],"rule":"deterrent 指让某人不愿采取行动的威慑因素；obstacle 指直接阻碍行动的困难或障碍。前者作用于意愿，后者不一定如此。","examples":[["High fees may act as a deterrent.","高额费用可能使人望而却步。"],["A technical obstacle delayed the upgrade.","一项技术障碍使升级推迟了。"]]}])for(const w of guide.words)(LEX40_CONTRASTS[w]??=[]).push(guide);


