/* v45: user-focused query utilities, keeping all other filter selections intact. */
(function(){
 const input=document.getElementById('search');
 const clear=document.getElementById('lex45-query-clear');
 const start=document.getElementById('lex45-start');
 if(!input||!clear)return;
 const sync=()=>{const active=!!input.value;clear.hidden=!active;clear.setAttribute('aria-hidden',String(!active))};
 input.addEventListener('input',sync);
 clear.addEventListener('click',()=>{if(!input.value)return;input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));input.focus({preventScroll:true})});
 start?.addEventListener('click',()=>{
  if(document.getElementById('library')?.classList.contains('hidden'))navigate('all');
  input.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
  input.focus({preventScroll:true});
 });
 sync();
})();


/* v46: export a concise, readable word note without touching learning-progress storage. */
(function(){
 const list=document.getElementById('entries');if(!list)return;
 list.addEventListener('click',async event=>{
  const btn=event.target.closest('[data-copy-meaning]');if(!btn)return;
  event.preventDefault();event.stopPropagation();
  const panel=btn.closest('.lex-meaning-pair');if(!panel)return;
  const entry=btn.closest('[data-entry-word]');
  const title=entry?.dataset.entryWord||btn.dataset.copyMeaning||'';
  const english=panel.querySelector('.lex-meaning-en')?.textContent.trim()||'';
  const chinese=panel.querySelector('.lex-meaning-zh')?.textContent.trim()||'';
  const text=[title,english,chinese].filter(Boolean).join('\n');
  if(!text)return;
  let copied=false;
  if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);copied=true}catch(_){}}
  if(!copied){let temp=document.createElement('textarea');temp.value=text;temp.style.cssText='position:fixed;left:-9999px;top:0;opacity:0';document.body.append(temp);temp.select();try{copied=!!document.execCommand('copy')}catch(_){}temp.remove()}
  const label=btn.querySelector('span');if(label){label.textContent=copied?'已复制':'复制失败';setTimeout(()=>{if(label.isConnected)label.textContent='复制释义'},1750)}
  const announce=document.getElementById('lex46-copy-status');if(announce)announce.textContent=copied?'已复制 '+title+' 的简明释义':'当前浏览器不允许自动复制，请选择文字手动复制';
 });
})();
